window.CBT_DATA=window.CBT_DATA||{};window.CBT_DATA["written/2025-2"]={"track":"written","round":"2025-2","questions":[{"id":"written-2025-2-1","no":1,"unit":"소프트웨어 설계","q":"바람직한 소프트웨어 설계 지침으로 볼 수 없는 것은?","choices":["모듈의 크기를 가능한 작게 구성해 병행성 수준을 높여야 한다.","결합도는 최소화하고 응집도는 최대화한다.","하나의 입구와 하나의 출구를 갖게 해야 한다.","복잡도와 중복성을 줄이며 일관성을 유지시킨다."],"ans":1,"exp":{"concept":"좋은 소프트웨어 설계는 모듈을 서로 덜 엮이게(결합도 낮게), 한 모듈 안은 한 가지 일에 집중하게(응집도 높게) 만드는 것이 핵심이다. 모듈 크기는 무조건 작게가 아니라 '적당한' 크기를 유지해야 한다. 너무 잘게 쪼개면 모듈 수와 모듈 사이 호출이 늘어나 오히려 관리가 어려워진다.","choices":[{"verdict":"정답","why":"설계 지침은 모듈 크기를 '적당하게' 유지하라고 한다. 가능한 한 작게 쪼개면 모듈 간 인터페이스와 호출이 늘어나 복잡해지므로 바람직한 지침이 아니다."},{"verdict":"오답","why":"결합도는 약하게, 응집도는 강하게 하는 것은 모듈 독립성을 높이는 대표적인 설계 지침이다."},{"verdict":"오답","why":"모듈은 하나의 입구와 하나의 출구를 갖도록 설계해야 흐름을 추적하기 쉽다. 올바른 지침이다."},{"verdict":"오답","why":"복잡도와 중복성을 줄이고 일관성을 유지하는 것도 교재에 나오는 설계 지침이다."}],"keywords":[{"term":"모듈 독립성","desc":"결합도는 낮추고 응집도는 높여 모듈이 서로 영향을 덜 받게 하는 성질"},{"term":"결합도(Coupling)","desc":"모듈과 모듈 사이의 상호 의존 정도"},{"term":"응집도(Cohesion)","desc":"한 모듈 안의 구성 요소들이 서로 관련된 정도"},{"term":"단일 입구·단일 출구","desc":"모듈의 진입점과 종료점을 하나씩만 두는 설계 원칙"}],"memo":"모듈 크기는 '가능한 작게'가 아니라 '적당하게'. '가능한 한', '최대한' 같은 극단적 표현이 붙은 보기를 먼저 의심한다."}},{"id":"written-2025-2-2","no":2,"unit":"소프트웨어 설계","q":"UI 설계 원칙 중 누구나 쉽게 이해하고 사용할 수 있어야 한다는 원칙은?","choices":["유효성","학습성","직관성","유연성"],"ans":3,"exp":{"concept":"UI 설계 원칙은 직관성, 유효성, 학습성, 유연성 네 가지다. 그중 직관성은 처음 보는 사람도 설명서 없이 보고 바로 이해하고 쓸 수 있어야 한다는 원칙이다. 엘리베이터의 위·아래 화살표 버튼처럼 보자마자 무엇을 하는지 아는 것이 직관성이다.","choices":[{"verdict":"오답","why":"유효성은 사용자의 목적을 정확하고 완벽하게 달성할 수 있어야 한다는 원칙이다."},{"verdict":"오답","why":"학습성은 누구나 쉽게 배우고 익힐 수 있어야 한다는 원칙이다. '이해하고 사용'이 아니라 '배우고 익히기'에 초점이 있다."},{"verdict":"정답","why":"직관성은 누구나 쉽게 이해하고 사용할 수 있어야 한다는 원칙으로, 문제의 설명과 일치한다."},{"verdict":"오답","why":"유연성은 사용자의 요구사항을 최대한 수용하고 실수를 최소화해야 한다는 원칙이다."}],"keywords":[{"term":"직관성","desc":"누구나 쉽게 이해하고 사용할 수 있어야 함"},{"term":"유효성","desc":"사용자의 목적을 정확하고 완벽하게 달성해야 함"},{"term":"학습성","desc":"누구나 쉽게 배우고 익힐 수 있어야 함"},{"term":"유연성","desc":"사용자의 요구를 최대한 수용하고 실수를 최소화해야 함"}],"memo":"이해·사용은 직관성, 배우기·익히기는 학습성, 목적 달성은 유효성, 요구 수용·실수 최소화는 유연성으로 짝지어 외운다."}},{"id":"written-2025-2-3","no":3,"unit":"소프트웨어 설계","q":"다음 중 시스템의 구성 요소에 해당하지 않는 것은?","choices":["Maintenance","Feedback","Process","Control"],"ans":1,"exp":{"concept":"시스템은 입력을 받아 처리하고 결과를 내보내는 덩어리로, 기본 구성 요소는 입력(Input), 처리(Process), 출력(Output), 제어(Control), 피드백(Feedback) 다섯 가지다. 정수기에 비유하면 수돗물이 입력, 필터링이 처리, 깨끗한 물이 출력, 수질 감시가 제어, 감시 결과로 필터를 조정하는 것이 피드백이다.","choices":[{"verdict":"정답","why":"Maintenance(유지보수)는 개발이 끝난 뒤 시스템을 고치고 관리하는 활동이지 시스템의 기본 구성 요소가 아니다."},{"verdict":"오답","why":"Feedback(피드백)은 출력 결과를 다시 입력이나 처리에 반영하는 요소로, 시스템 구성 요소에 해당한다."},{"verdict":"오답","why":"Process(처리)는 입력된 데이터를 가공해 출력으로 바꾸는 요소로, 시스템 구성 요소에 해당한다."},{"verdict":"오답","why":"Control(제어)는 각 과정이 올바르게 진행되도록 감독하는 요소로, 시스템 구성 요소에 해당한다."}],"keywords":[{"term":"입력(Input)","desc":"처리할 데이터나 조건을 시스템에 넣는 요소"},{"term":"처리(Process)","desc":"입력을 가공해 출력으로 바꾸는 요소"},{"term":"출력(Output)","desc":"처리된 결과를 내보내는 요소"},{"term":"제어(Control)","desc":"각 과정이 올바르게 진행되는지 감독하는 요소"},{"term":"피드백(Feedback)","desc":"출력 결과를 다시 입력이나 처리에 반영하는 요소"}],"memo":"입력·처리·출력에 제어와 피드백을 더한 다섯 가지. 유지보수(Maintenance)는 생명주기의 단계일 뿐 구성 요소가 아니다."}},{"id":"written-2025-2-4","no":4,"unit":"소프트웨어 설계","q":"요구사항 명세에 관한 설명 중 틀린 것은?","choices":["잘못된 부분이 확인되면 그 내용을 요구사항 정의서에서 추적할 수 있어야 한다.","구체적인 명세를 위하여 자료 사전(DD)가 사용될 수 있다.","분석된 요구사항을 바탕으로 모델을 작성하고 문서화하는 것이다.","기능 요구사항은 빠짐없이 완전하고 명확하게 기술하여야 한다."],"ans":2,"exp":{"concept":"요구사항 명세는 분석한 요구사항을 바탕으로 모델을 만들고 문서로 정리하는 단계다. 교재는 기능 요구사항은 빠짐없이 명확하게, 비기능 요구사항은 필요한 것만 명확하게 쓰고, 설계 중 잘못이 발견되면 요구사항 정의서에서 추적할 수 있어야 하며, 구체적인 명세를 위해 소단위 명세서(Mini-Spec)를 활용할 수 있다고 설명한다.","choices":[{"verdict":"오답","why":"설계 과정에서 잘못된 부분이 확인되면 그 내용을 요구사항 정의서에서 추적할 수 있어야 한다는 것은 교재의 설명과 같다."},{"verdict":"정답","why":"교재 문장은 '구체적인 명세를 위해 소단위 명세서(Mini-Spec)가 활용될 수 있다'이다. 이 보기는 소단위 명세서를 자료 사전(DD)으로 바꿔 놓은 것이어서 틀린 설명으로 처리된다."},{"verdict":"오답","why":"요구사항 명세는 분석된 요구사항을 바탕으로 모델을 작성하고 문서화하는 것이라는 정의 그대로다."},{"verdict":"오답","why":"기능 요구사항은 빠짐없이 완전하고 명확하게 기술해야 한다는 것은 교재의 설명과 같다."}],"keywords":[{"term":"요구사항 명세","desc":"분석된 요구사항을 바탕으로 모델을 작성하고 문서화하는 단계"},{"term":"소단위 명세서(Mini-Spec)","desc":"DFD의 각 처리(프로세스)가 하는 일을 구체적으로 기술한 문서"},{"term":"자료 사전(DD, Data Dictionary)","desc":"자료 흐름도에 나오는 자료의 이름과 구성 요소를 정의한 사전"}],"memo":"요구사항 명세에서 '구체적인 명세'와 짝을 이루는 것은 소단위 명세서(Mini-Spec)다. 자료 사전은 자료를 정의하는 도구로 구분해 둔다."}},{"id":"written-2025-2-5","no":5,"unit":"소프트웨어 설계","q":"UML 모델에서 사용되는 구조적 다이어그램에 해당하지 않는 것은?","choices":["Object Diagram","Component Diagram","State Diagram","Class Diagram"],"ans":3,"exp":{"concept":"UML 다이어그램은 시스템의 뼈대(구조)를 보여 주는 구조적 다이어그램과, 시간에 따른 움직임(행위)을 보여 주는 행위 다이어그램으로 나뉜다. 구조적 다이어그램은 클래스, 객체, 컴포넌트, 배치, 복합체 구조, 패키지 다이어그램이다. 상태 다이어그램은 객체의 상태가 변하는 과정을 그리므로 행위 다이어그램이다.","choices":[{"verdict":"오답","why":"객체 다이어그램(Object Diagram)은 클래스의 인스턴스인 객체들과 그 관계를 표현하는 구조적 다이어그램이다."},{"verdict":"오답","why":"컴포넌트 다이어그램(Component Diagram)은 구현 모듈인 컴포넌트 간의 관계를 표현하는 구조적 다이어그램이다."},{"verdict":"정답","why":"상태 다이어그램(State Diagram)은 객체가 이벤트에 따라 상태가 어떻게 바뀌는지를 표현하는 행위 다이어그램이므로 구조적 다이어그램이 아니다."},{"verdict":"오답","why":"클래스 다이어그램(Class Diagram)은 클래스와 속성, 연산, 관계를 표현하는 대표적인 구조적 다이어그램이다."}],"keywords":[{"term":"구조적 다이어그램","desc":"클래스, 객체, 컴포넌트, 배치, 복합체 구조, 패키지 다이어그램"},{"term":"행위 다이어그램","desc":"유스케이스, 시퀀스, 커뮤니케이션, 상태, 활동, 상호작용 개요, 타이밍 다이어그램"},{"term":"상태 다이어그램","desc":"객체의 상태 변화를 표현하는 행위 다이어그램"}],"memo":"이름에 '상태', '활동', '시퀀스', '유스케이스'처럼 움직임이 느껴지면 행위 다이어그램, '클래스', '객체', '컴포넌트', '배치', '패키지'처럼 물건 이름이면 구조적 다이어그램이다."}},{"id":"written-2025-2-6","no":6,"unit":"소프트웨어 설계","q":"럼바우(Rumbaugh) 분석 기법에서 정보 모델링이라고도 불리며, 시스템에 요구되는 객체를 찾아내고 속성과 연산을 식별하며 객체들 간의 관계를 규정하여 다이어그램으로 표시하는 모델링은?","choices":["Dynamic","Function","Static","Object"],"ans":4,"exp":{"concept":"럼바우(Rumbaugh) 분석 기법은 객체 모델링, 동적 모델링, 기능 모델링 세 단계로 시스템을 분석한다. 그중 객체 모델링은 정보 모델링이라고도 하며, 필요한 객체를 찾고 속성과 연산을 정하고 객체 간 관계를 객체 다이어그램으로 그린다. 순서는 객체(Object) → 동적(Dynamic) → 기능(Functional)이다.","choices":[{"verdict":"오답","why":"동적 모델링(Dynamic Modeling)은 상태 다이어그램을 이용해 시간 흐름에 따른 객체의 상태 변화와 제어 흐름을 표현한다."},{"verdict":"오답","why":"기능 모델링(Functional Modeling)은 자료 흐름도(DFD)를 이용해 입력이 처리되어 출력으로 바뀌는 과정을 표현한다."},{"verdict":"오답","why":"럼바우 기법의 세 모델링은 객체, 동적, 기능이며 '정적(Static) 모델링'이라는 단계는 없다."},{"verdict":"정답","why":"객체 모델링(Object Modeling)은 정보 모델링이라고도 하며, 객체와 속성·연산, 객체 간 관계를 객체 다이어그램으로 표시한다. 문제의 설명과 일치한다."}],"keywords":[{"term":"럼바우 분석 기법","desc":"객체 모델링 → 동적 모델링 → 기능 모델링 순으로 분석하는 객체지향 분석 기법(OMT)"},{"term":"객체 모델링","desc":"정보 모델링이라고도 하며 객체 다이어그램 사용"},{"term":"동적 모델링","desc":"상태 다이어그램으로 상태 변화 표현"},{"term":"기능 모델링","desc":"자료 흐름도(DFD)로 입력에서 출력까지의 처리 과정 표현"}],"memo":"럼바우는 '객동기'(객체-동적-기능) 순서. 정보 모델링이라는 말이 나오면 객체 모델링이다."}},{"id":"written-2025-2-7","no":7,"unit":"소프트웨어 설계","q":"UML(Unified Modeling Language)에 관한 설명으로 옳지 않은 것은?","choices":["기능적 모델은 사용자 관점에서 본 시스템의 기능으로, UML에서는 Use Case Diagram을 사용한다.","정적 모델은 객체, 속성, 연관관계, 오퍼레이션 등 시스템의 구조를 나타내며, UML에서는 Class Diagram을 사용한다.","State Diagram은 객체들 간의 메시지 교환을 나타내고, Sequence Diagram은 하나의 객체가 갖는 상태와 그 상태 변화에 따른 동작 순서를 나타낸다.","동적 모델은 시스템의 내부 동작을 의미하며, UML에서는 Sequence Diagram, State Diagram, Activity Diagram을 사용한다."],"ans":3,"exp":{"concept":"UML로 시스템을 볼 때는 세 관점이 있다. 사용자 입장에서 무슨 기능을 하는지(기능적 모델: 유스케이스 다이어그램), 무엇으로 이루어졌는지(정적 모델: 클래스 다이어그램), 어떻게 움직이는지(동적 모델: 시퀀스·상태·활동 다이어그램)다. 시퀀스 다이어그램은 객체끼리 주고받는 메시지 순서를, 상태 다이어그램은 한 객체의 상태 변화를 그린다.","choices":[{"verdict":"오답","why":"기능적 모델은 사용자 관점에서 본 시스템 기능을 표현하며 유스케이스 다이어그램(Use Case Diagram)을 쓴다. 옳은 설명이다."},{"verdict":"오답","why":"정적 모델은 객체, 속성, 연관 관계, 오퍼레이션 같은 구조를 표현하며 클래스 다이어그램(Class Diagram)을 쓴다. 옳은 설명이다."},{"verdict":"정답","why":"두 다이어그램의 설명이 서로 바뀌었다. 객체 간 메시지 교환을 나타내는 것은 시퀀스 다이어그램이고, 하나의 객체가 갖는 상태와 그 변화를 나타내는 것은 상태 다이어그램이다."},{"verdict":"오답","why":"동적 모델은 시스템 내부 동작을 표현하며 시퀀스, 상태, 활동 다이어그램을 쓴다. 옳은 설명이다."}],"keywords":[{"term":"기능적 모델","desc":"사용자 관점의 기능 표현, 유스케이스 다이어그램"},{"term":"정적 모델","desc":"시스템 구조 표현, 클래스 다이어그램"},{"term":"동적 모델","desc":"시스템 내부 동작 표현, 시퀀스·상태·활동 다이어그램"},{"term":"시퀀스 다이어그램","desc":"객체 간 메시지 교환을 시간 순서대로 표현"}],"memo":"시퀀스(Sequence)는 '순서' → 객체들 사이 메시지 순서, 상태(State)는 '한 객체의 상태 변화'. 설명이 서로 바뀐 보기가 자주 나온다."}},{"id":"written-2025-2-8","no":8,"unit":"소프트웨어 설계","q":"코드 설계에서 일정한 일련번호를 부여하는 방식에 해당하는 코드는?","choices":["표의 숫자 코드","순차 코드","연상 코드","블록 코드"],"ans":2,"exp":{"concept":"코드 설계는 자료를 분류·식별하기 위해 번호나 기호를 붙이는 방법을 정하는 것이다. 순차 코드(Sequence Code)는 일정한 기준에 따라 처음부터 차례대로 1, 2, 3… 같은 일련번호를 붙이는 가장 단순한 방식이다. 번호표 기계에서 순서대로 뽑히는 대기 번호를 떠올리면 된다.","choices":[{"verdict":"오답","why":"표의 숫자 코드(유효 숫자 코드)는 길이, 넓이, 부피 같은 물리적 수치를 그대로 코드에 넣는 방식이다."},{"verdict":"정답","why":"순차 코드는 자료의 발생 순서나 크기 순서 등 일정 기준에 따라 차례로 일련번호를 붙이는 방식으로, 문제의 설명과 일치한다."},{"verdict":"오답","why":"연상 코드(Mnemonic Code)는 명칭이나 약호와 관계있는 숫자·문자·기호를 써서 코드만 보고 대상을 떠올릴 수 있게 하는 방식이다(예: TV-40)."},{"verdict":"오답","why":"블록 코드(구분 코드)는 공통성이 있는 것끼리 블록으로 묶고, 각 블록 안에서 일련번호를 붙이는 방식이다."}],"keywords":[{"term":"순차 코드","desc":"일정 기준에 따라 차례로 일련번호를 부여하는 코드"},{"term":"블록 코드","desc":"공통성 있는 것끼리 블록으로 구분하고 블록 안에서 일련번호 부여"},{"term":"연상 코드","desc":"명칭과 관계있는 문자·숫자로 대상을 연상할 수 있게 한 코드"},{"term":"표의 숫자 코드","desc":"물리적 수치를 그대로 코드에 적용한 코드"}],"memo":"'일련번호'만 있으면 순차 코드, '블록 안의 일련번호'면 블록 코드, '수치 그대로'면 표의 숫자 코드, '연상'이면 연상 코드."}},{"id":"written-2025-2-9","no":9,"unit":"소프트웨어 설계","q":"소프트웨어 모델링에 관한 설명으로 옳지 않은 것은?","choices":["객체지향 방법론에서는 UML 표기법을 활용한다.","모델링 작업의 결과물은 다른 모델링 작업에 영향을 미칠 수 없다.","소프트웨어 모델을 사용하면 개발될 소프트웨어에 대한 이해도와 이해 당사자 간의 의사소통 향상에 도움이 된다.","구조적 방법론에서는 DFD(Data Flow Diagram), DD(Data Dictionary) 등을 이용하여 요구사항의 결과를 표현한다."],"ans":2,"exp":{"concept":"소프트웨어 모델링은 만들 소프트웨어를 그림과 표기법으로 미리 표현해 보는 작업이다. 모델은 개발자와 사용자 등 이해 당사자가 같은 그림을 보고 소통하게 해 준다. 또한 한 모델링의 결과물은 다음 모델링과 설계의 입력이 되므로 서로 영향을 주고받는다.","choices":[{"verdict":"오답","why":"객체지향 방법론은 UML 표기법으로 모델을 표현한다. 옳은 설명이다."},{"verdict":"정답","why":"모델링 결과물은 다른 모델링 작업에 영향을 미친다. 예를 들어 클래스 모델이 바뀌면 시퀀스 모델도 바뀌어야 하므로 '영향을 미칠 수 없다'는 틀린 설명이다."},{"verdict":"오답","why":"모델을 사용하면 개발할 소프트웨어를 이해하기 쉬워지고 이해 당사자 간 의사소통이 좋아진다. 옳은 설명이다."},{"verdict":"오답","why":"구조적 방법론은 자료 흐름도(DFD), 자료 사전(DD) 등으로 요구사항 분석 결과를 표현한다. 옳은 설명이다."}],"keywords":[{"term":"소프트웨어 모델링","desc":"개발할 소프트웨어의 구조와 동작을 표기법으로 미리 표현하는 작업"},{"term":"UML","desc":"객체지향 방법론에서 쓰는 표준 모델링 언어"},{"term":"DFD","desc":"구조적 방법론에서 자료의 흐름과 처리를 그림으로 표현하는 도구"}],"memo":"모델링 결과물은 서로 이어져 있다. '영향을 미칠 수 없다', '무관하다'처럼 단절을 말하는 보기는 틀린 설명일 가능성이 크다."}},{"id":"written-2025-2-10","no":10,"unit":"소프트웨어 설계","q":"소프트웨어 설계에서 각 모듈의 세분화된 역할이나 모듈 간 인터페이스처럼 코드를 작성하는 수준의 세부적인 구현 방안을 설계할 때 참조할 수 있는 전형적인 해결 방식 또는 예제를 뜻하는 것은?","choices":["클래스 도출","모듈 분해","연관 관계","디자인 패턴"],"ans":4,"exp":{"concept":"디자인 패턴은 모듈의 세부 역할이나 모듈 간 인터페이스처럼 코드 수준의 설계를 할 때, 자주 나타나는 문제에 대해 이미 검증된 전형적인 해결 방법을 정리해 둔 것이다. 요리로 치면 자주 만드는 음식의 표준 레시피와 같다. GoF(Gang of Four)가 정리한 생성·구조·행위 패턴 23가지가 대표적이다.","choices":[{"verdict":"오답","why":"클래스 도출은 요구사항에서 필요한 클래스를 찾아내는 분석 활동이지, 참조할 해결 방식 모음이 아니다."},{"verdict":"오답","why":"모듈 분해는 시스템을 기능 단위의 모듈로 나누는 설계 활동이다."},{"verdict":"오답","why":"연관 관계는 클래스나 객체 사이의 관계 종류 중 하나로, 해결 방식이나 예제를 뜻하지 않는다."},{"verdict":"정답","why":"디자인 패턴은 코드 작성 수준의 세부 구현 방안을 설계할 때 참조하는 전형적인 해결 방식(예제)으로, 문제의 설명과 일치한다."}],"keywords":[{"term":"디자인 패턴","desc":"자주 나타나는 설계 문제에 대한 검증된 전형적 해결 방법"},{"term":"GoF 디자인 패턴","desc":"생성 패턴, 구조 패턴, 행위 패턴으로 나뉘는 23가지 패턴"},{"term":"아키텍처 패턴","desc":"시스템 전체 구조 수준의 전형적 해결 방법(레이어, MVC 등)"}],"memo":"시스템 전체 뼈대 수준이면 아키텍처 패턴, 모듈·인터페이스처럼 코드 수준이면 디자인 패턴."}},{"id":"written-2025-2-11","no":11,"unit":"소프트웨어 설계","q":"파이프 필터 형태의 소프트웨어 아키텍처에 관한 설명으로 옳은 것은?","choices":["서브시스템이 입력 데이터를 받아 처리한 뒤 결과를 다음 서브시스템에 넘겨주는 과정을 반복한다.","노드와 간선으로 이루어진다.","3개의 서브시스템(모델, 뷰, 제어)으로 이루어져 있다.","계층 모델이라고도 불린다."],"ans":1,"exp":{"concept":"파이프-필터(Pipe-Filter) 패턴은 데이터가 필터(처리 단계)를 하나씩 통과하며 가공되고, 각 필터의 결과가 파이프를 통해 다음 필터로 넘어가는 구조다. 공장의 컨베이어 벨트처럼 각 공정이 자기 일을 하고 다음 공정으로 넘긴다. 유닉스 셸의 파이프(|)가 대표적인 예다.","choices":[{"verdict":"정답","why":"서브시스템(필터)이 입력 데이터를 받아 처리한 뒤 결과를 다음 서브시스템에 넘기는 과정을 반복하는 것이 파이프-필터 패턴이다. 옳은 설명이다."},{"verdict":"오답","why":"노드와 간선은 그래프 구조 일반을 가리키는 표현으로, 데이터를 단계별로 처리해 넘기는 파이프-필터 패턴의 특징을 설명하지 못한다."},{"verdict":"오답","why":"모델(Model), 뷰(View), 컨트롤러(Controller) 세 서브시스템으로 이루어진 것은 MVC 패턴이다."},{"verdict":"오답","why":"계층 모델이라고 불리는 것은 시스템을 계층으로 나누는 레이어(Layer) 패턴이다."}],"keywords":[{"term":"파이프-필터 패턴","desc":"데이터가 필터를 거쳐 처리되고 파이프로 다음 필터에 전달되는 구조"},{"term":"MVC 패턴","desc":"모델·뷰·컨트롤러로 나누어 데이터, 화면, 제어를 분리하는 구조"},{"term":"레이어 패턴","desc":"시스템을 계층으로 나누고 각 계층이 바로 위·아래 계층과만 상호작용하는 구조"}],"memo":"파이프-필터는 '처리하고 다음으로 넘긴다', MVC는 '셋으로 나눈다', 레이어는 '층으로 쌓는다'로 구분한다."}},{"id":"written-2025-2-12","no":12,"unit":"소프트웨어 설계","q":"설계 기법 가운데 하향식 설계 방법과 상향식 설계 방법을 비교한 설명으로 가장 옳지 않은 것은?","choices":["하향식 설계에서 레벨이 낮은 데이터 구조의 세부 사항은 설계를 단계적으로 구체화해 가면서 결정한다.","상향식 설계는 인터페이스가 이미 성립되어 있지 않아도 기능 추가가 쉽다.","하향식 설계는 통합 검사 시 인터페이스가 이미 정의되어 있으므로 통합이 간단하다.","상향식 설계는 최하위 수준에서 각각의 모듈들을 설계하고, 이러한 모듈이 완성되면 이들을 결합하여 검사한다."],"ans":2,"exp":{"concept":"하향식 설계는 최상위 모듈부터 설계하고 점점 아래로 내려가며 구체화하는 방법이고, 상향식 설계는 최하위 모듈부터 설계해 완성된 모듈을 결합해 올라가는 방법이다. 하향식은 위에서 정한 인터페이스대로 아래를 끼워 넣으니 통합이 간단하고, 상향식은 인터페이스가 미리 성립되어 있어야 기능을 추가하기 쉽다.","choices":[{"verdict":"오답","why":"하향식 설계는 위에서부터 단계적으로 구체화해 가는 방식이므로, 하위 수준의 세부 사항이 설계가 내려가면서 정해진다는 설명은 하향식의 일반적인 진행과 맞는다."},{"verdict":"정답","why":"교재 설명은 '상향식 설계는 인터페이스가 이미 성립되어 있어야 기능 추가가 쉽다'이다. 인터페이스가 없어도 기능 추가가 쉽다는 것은 반대로 말한 것이므로 가장 옳지 않다."},{"verdict":"오답","why":"하향식 설계는 상위에서 인터페이스가 이미 정의되므로 통합 검사 때 통합이 간단하다. 옳은 설명이다."},{"verdict":"오답","why":"상향식 설계는 최하위 수준의 모듈을 먼저 설계하고, 완성되면 결합해 검사한다. 옳은 설명이다."}],"keywords":[{"term":"하향식 설계","desc":"최상위 컴포넌트부터 설계하고 아래로 내려가며 세분화하는 방식"},{"term":"상향식 설계","desc":"최하위 모듈부터 설계해 결합하며 위로 올라가는 방식"},{"term":"단계적 구체화","desc":"큰 기능을 한 단계씩 작은 기능으로 나누어 구체화하는 방법"}],"memo":"상향식은 '인터페이스가 먼저 성립되어 있어야' 기능 추가가 쉽다. '성립되어 있지 않아도'로 바꾼 함정을 기억한다.","doubt":"교재(원 기출)의 하향식 문장은 '레벨이 낮은 데이터 구조의 세부 사항은 설계 초기 단계에서 필요하다'인데, 이 보기 1은 '단계적으로 구체화해 가면서 결정한다'로 바뀌어 있다. 교재 문장 기준으로 채점하면 보기 1도 틀린 설명으로 볼 여지가 있다. 원 기출 정답과 같이 가장 확실히 틀린 2를 정답으로 둔다."}},{"id":"written-2025-2-13","no":13,"unit":"소프트웨어 설계","q":"디자인 패턴을 사용할 때의 장단점에 관한 설명으로 가장 거리가 먼 것은?","choices":["초기 투자 비용과 개발 시간이 절약된다.","객체지향 설계와 구현의 생산성을 높이는 데 적합하다.","소프트웨어의 구조를 파악하기 쉽다.","재사용을 위한 개발 시간이 줄어든다."],"ans":1,"exp":{"concept":"디자인 패턴은 검증된 설계 방법을 재사용하는 것이라 구조를 이해하기 쉽고 개발 시간을 줄여 준다. 하지만 패턴을 익히고 도입하는 데 처음에는 시간과 비용이 든다. 그래서 교재는 단점으로 '객체지향 설계·구현 위주로 사용된다'와 '초기 투자 비용이 부담된다'를 든다.","choices":[{"verdict":"정답","why":"디자인 패턴은 처음 도입할 때 학습과 적용에 비용이 들어 초기 투자 비용이 부담된다는 것이 단점이다. 초기 비용이 절약된다는 것은 반대로 말한 것이다."},{"verdict":"오답","why":"디자인 패턴은 객체지향 설계와 구현에 맞춰 정리되어 있어 그 생산성을 높이는 데 적합하다. 옳은 설명이다."},{"verdict":"오답","why":"패턴 이름만으로 구조를 짐작할 수 있어 소프트웨어 구조를 파악하기 쉽다. 장점에 해당한다."},{"verdict":"오답","why":"검증된 설계를 재사용하므로 개발 시간이 줄어든다. 장점에 해당한다."}],"keywords":[{"term":"디자인 패턴 장점","desc":"의사소통 원활, 구조 파악 용이, 재사용으로 개발 시간 단축, 설계 변경에 유연한 대처"},{"term":"디자인 패턴 단점","desc":"객체지향 설계·구현 위주로 사용, 초기 투자 비용 부담"}],"memo":"재사용 덕분에 '나중'이 편해지는 것이지 '처음'은 비용이 든다. 초기 비용 절약은 함정이다."}},{"id":"written-2025-2-14","no":14,"unit":"소프트웨어 설계","q":"소프트웨어 공학에서 워크스루(Walkthrough)에 관한 설명 중 틀린 것은?","choices":["단순한 테스트 케이스를 이용해 프로덕트를 수작업으로 수행해 보는 것을 말한다.","복잡한 알고리즘이나 반복, 실시간 동작, 병행 처리 같은 기능이나 동작을 이해하고자 할 때 유용하다.","사용사례를 확장하여 명세하거나 설계 다이어그램, 원시코드, 테스트 케이스 등에 적용이 가능하다.","인스펙션(Inspection)과 같은 의미를 지닌다."],"ans":4,"exp":{"concept":"워크스루(Walkthrough)는 검토 회의 전에 자료를 미리 나눠 주고, 짧은 회의에서 사례를 손으로 따라가며 오류를 일찍 찾는 비공식적 검토 방법이다. 인스펙션(Inspection)은 훈련된 검토자들이 정해진 절차와 체크리스트로 결함을 찾는 공식적 검토 방법이다. 둘 다 정적 검토지만 형식성과 진행 방식이 다르다.","choices":[{"verdict":"오답","why":"워크스루는 단순한 테스트 케이스를 이용해 산출물을 손으로 직접 따라가 보는 방식이다. 옳은 설명이다."},{"verdict":"오답","why":"복잡한 알고리즘, 반복, 실시간 동작, 병행 처리처럼 머릿속으로 이해하기 어려운 동작을 따라가 볼 때 유용하다. 옳은 설명이다."},{"verdict":"오답","why":"사용사례를 확장한 명세, 설계 다이어그램, 원시코드, 테스트 케이스 등 다양한 산출물에 적용할 수 있다. 옳은 설명이다."},{"verdict":"정답","why":"인스펙션은 워크스루보다 더 공식적이고 절차가 정해진 검토 방법으로, 둘은 같은 의미가 아니다."}],"keywords":[{"term":"워크스루(Walkthrough)","desc":"자료를 미리 배포하고 짧은 회의로 사례를 따라가며 오류를 찾는 비공식 검토"},{"term":"인스펙션(Inspection)","desc":"전문가가 정해진 절차와 체크리스트로 결함을 찾는 공식 검토"},{"term":"정적 테스트","desc":"프로그램을 실행하지 않고 명세서나 코드를 검토하는 테스트"}],"memo":"워크스루는 '걸어서 따라가 보기'(비공식), 인스펙션은 '검사'(공식). 같은 의미라는 보기는 틀린 것이다."}},{"id":"written-2025-2-15","no":15,"unit":"소프트웨어 설계","q":"익스트림 프로그래밍에 관한 설명 중 틀린 것은?","choices":["익스트림 프로그래밍을 구동시키는 원리는 상식적인 원리와 경험을 최대한 끌어올리는 것이다.","대표적인 구조적 방법론의 하나이다.","소규모 개발 조직이 불확실하고 변경이 잦은 요구를 접했을 때 적절한 방법이다.","구체적인 실천 방법을 정의하고 있으며, 개발 문서보다는 소스코드에 중점을 둔다."],"ans":2,"exp":{"concept":"익스트림 프로그래밍(XP, eXtreme Programming)은 대표적인 애자일 방법론이다. 고객 참여와 짧은 개발 주기 반복으로 변화에 빠르게 대응하며, 문서보다 동작하는 소스코드를 중시한다. 의사소통, 단순성, 용기, 존중, 피드백 다섯 가지 핵심 가치를 둔다.","choices":[{"verdict":"오답","why":"XP는 상식적인 원리와 경험을 극한(extreme)까지 끌어올려 적용하는 것을 기본 원리로 한다. 옳은 설명이다."},{"verdict":"정답","why":"XP는 애자일 방법론의 대표 주자이며 구조적 방법론이 아니다. 구조적 방법론은 DFD, DD 등으로 기능 중심 분석·설계를 하는 전통적 방법론이다."},{"verdict":"오답","why":"XP는 소규모 개발 조직이 불확실하고 자주 바뀌는 요구에 대응하기에 적절하다. 옳은 설명이다."},{"verdict":"오답","why":"XP는 짝 프로그래밍, 테스트 주도 개발 등 구체적인 실천 방법을 정의하며 문서보다 소스코드를 중시한다. 옳은 설명이다."}],"keywords":[{"term":"익스트림 프로그래밍(XP)","desc":"고객 참여와 짧은 반복으로 변화에 대응하는 대표적 애자일 방법론"},{"term":"XP 핵심 가치","desc":"의사소통, 단순성, 용기, 존중, 피드백"},{"term":"구조적 방법론","desc":"DFD, DD 등으로 기능 중심 분석·설계를 하는 전통적 방법론"}],"memo":"XP, 스크럼, 칸반, 린, FDD는 모두 애자일. '구조적 방법론'에 넣은 보기는 틀린 것이다."}},{"id":"written-2025-2-16","no":16,"unit":"소프트웨어 설계","q":"데이터 흐름도(DFD)의 구성 요소에 해당되지 않는 것은?","choices":["Data Flow","Process","Data Dictionary","Data Store"],"ans":3,"exp":{"concept":"자료 흐름도(DFD, Data Flow Diagram)는 자료가 어디서 들어와 어떻게 처리되어 어디로 나가는지를 그림으로 그린 것이다. 구성 요소는 처리(Process, 원), 자료 흐름(Data Flow, 화살표), 자료 저장소(Data Store, 평행선), 단말(Terminator, 사각형) 네 가지다. 자료 사전은 DFD에 나온 자료를 따로 정의하는 별도 문서다.","choices":[{"verdict":"오답","why":"자료 흐름(Data Flow)은 자료의 이동을 화살표로 나타내는 DFD의 구성 요소다."},{"verdict":"오답","why":"처리(Process)는 자료를 변환하는 과정을 원으로 나타내는 DFD의 구성 요소다."},{"verdict":"정답","why":"자료 사전(Data Dictionary)은 DFD에 나오는 자료를 정의한 별도의 문서로, DFD 그림을 이루는 구성 요소가 아니다."},{"verdict":"오답","why":"자료 저장소(Data Store)는 자료가 저장되는 곳을 평행선으로 나타내는 DFD의 구성 요소다."}],"keywords":[{"term":"처리(Process)","desc":"자료를 변환하는 과정, 원으로 표시"},{"term":"자료 흐름(Data Flow)","desc":"자료의 이동, 화살표로 표시"},{"term":"자료 저장소(Data Store)","desc":"자료가 저장되는 곳, 평행선으로 표시"},{"term":"단말(Terminator)","desc":"시스템과 자료를 주고받는 외부 개체, 사각형으로 표시"},{"term":"자료 사전(DD)","desc":"DFD에 나오는 자료를 정의한 별도 문서"}],"memo":"DFD 구성 요소는 프로세스·흐름·저장소·단말 넷. 자료 사전과 소단위 명세서는 DFD를 보완하는 별도 도구다."}},{"id":"written-2025-2-17","no":17,"unit":"소프트웨어 설계","q":"UML의 시퀀스 다이어그램을 구성하는 항목에 해당되지 않는 것은?","choices":["생명선","실행","메시지","확장"],"ans":4,"exp":{"concept":"시퀀스 다이어그램은 객체들이 시간 순서에 따라 메시지를 주고받는 모습을 그린 행위 다이어그램이다. 구성 요소는 액터, 객체, 생명선, 실행(활성 상자), 메시지 등이다. 확장(Extend)은 유스케이스 다이어그램에서 유스케이스 사이의 관계를 나타내는 말이다.","choices":[{"verdict":"오답","why":"생명선(Lifeline)은 객체가 메모리에 존재하는 기간을 객체 아래 점선으로 나타내는 시퀀스 다이어그램의 구성 요소다."},{"verdict":"오답","why":"실행(실행 상자, 활성 상자)은 객체가 메시지를 받아 동작하고 있는 구간을 생명선 위 직사각형으로 나타내는 구성 요소다."},{"verdict":"오답","why":"메시지(Message)는 객체 간에 주고받는 요청이나 응답을 화살표로 나타내는 구성 요소다."},{"verdict":"정답","why":"확장(Extend)은 유스케이스 다이어그램에서 기본 유스케이스에 조건부로 추가 기능을 붙이는 관계로, 시퀀스 다이어그램의 구성 항목이 아니다."}],"keywords":[{"term":"생명선","desc":"객체가 존재하는 기간을 나타내는 점선"},{"term":"실행 상자(활성 상자)","desc":"객체가 메시지를 받아 동작 중인 구간"},{"term":"메시지","desc":"객체 간에 주고받는 요청·응답, 화살표로 표시"},{"term":"확장(Extend) 관계","desc":"유스케이스 다이어그램에서 조건에 따라 추가로 수행되는 기능과의 관계"}],"memo":"확장(Extend)과 포함(Include)은 유스케이스 다이어그램의 관계 이름이다. 시퀀스 다이어그램 보기에 섞여 나오면 바로 골라낸다."}},{"id":"written-2025-2-18","no":18,"unit":"소프트웨어 설계","q":"객체 지향 개념 가운데 하나 이상의 유사한 객체들을 묶어서 공통된 특성을 표현하는 데이터 추상화를 뜻하는 것은?","choices":["Field","Message","Class","Method"],"ans":3,"exp":{"concept":"클래스(Class)는 공통된 속성과 연산을 가진 유사한 객체들을 묶어 하나의 틀로 표현한 것이다. 붕어빵 틀이 클래스, 틀로 찍어 낸 붕어빵 하나하나가 객체(인스턴스)라고 생각하면 된다. 공통된 특성을 뽑아 묶었으므로 데이터 추상화를 표현한 것이다.","choices":[{"verdict":"오답","why":"필드(Field)는 객체가 가지는 데이터 값, 즉 속성을 저장하는 변수를 말한다."},{"verdict":"오답","why":"메시지(Message)는 객체에게 어떤 행위를 하도록 보내는 요청이다."},{"verdict":"정답","why":"클래스는 유사한 객체들을 묶어 공통된 특성을 표현한 데이터 추상화의 단위다. 문제의 설명과 일치한다."},{"verdict":"오답","why":"메소드(Method)는 객체가 수행하는 동작, 즉 연산을 구현한 함수다."}],"keywords":[{"term":"클래스(Class)","desc":"공통 속성과 연산을 가진 객체들의 집합, 객체를 만드는 틀"},{"term":"객체(Object)","desc":"클래스로부터 만들어진 실체, 인스턴스"},{"term":"메소드(Method)","desc":"객체가 수행하는 연산을 구현한 것"},{"term":"메시지(Message)","desc":"객체에게 동작을 요청하는 것"}],"memo":"'유사한 객체들을 묶어'라는 말이 나오면 클래스다. 묶음 = 틀 = 클래스."}},{"id":"written-2025-2-19","no":19,"unit":"소프트웨어 설계","q":"사용자 인터페이스의 설계 지침에 관한 설명 중 옳지 않은 것은?","choices":["버튼이나 조작 방법 등은 일관성 있게 제공해야 한다.","조작 방법을 가능한 한 다양화하여 많은 기능을 담을 수 있도록 구성해야 한다.","사용자가 쉽게 이해하고 편리하게 사용할 수 있도록 환경을 제공해야 한다.","작동시킬 기능만 보고도 결과를 미리 예측할 수 있도록 설계해야 한다."],"ans":2,"exp":{"concept":"사용자 인터페이스(UI) 설계 지침은 사용자가 쉽고 편하게, 실수 없이 쓰게 하는 것이 목표다. 그래서 조작 방법은 일관되고 단순해야 하며, 결과를 예측할 수 있어야 한다. 조작 방법이 제각각이면 사용자가 헷갈려 실수가 늘어난다.","choices":[{"verdict":"오답","why":"버튼과 조작 방법을 일관성 있게 제공하는 것은 UI 설계 지침의 일관성에 해당한다. 옳은 설명이다."},{"verdict":"정답","why":"조작 방법을 다양하게 만들면 사용자가 익히기 어렵고 실수가 늘어난다. UI 지침은 조작 방법을 단순하고 일관되게 하라고 하므로 옳지 않다."},{"verdict":"오답","why":"사용자가 쉽게 이해하고 편리하게 쓸 수 있게 하는 것은 사용자 중심 지침이다. 옳은 설명이다."},{"verdict":"오답","why":"기능을 보고 결과를 미리 예측할 수 있게 설계하는 것은 결과 예측 가능 지침이다. 옳은 설명이다."}],"keywords":[{"term":"사용자 중심","desc":"사용자가 쉽게 이해하고 편리하게 사용할 수 있게 설계"},{"term":"일관성","desc":"버튼이나 조작 방법을 일관되게 제공"},{"term":"단순성","desc":"조작 방법을 단순화해 인지적 부담을 줄임"},{"term":"결과 예측 가능","desc":"작동시킬 기능만 보고도 결과를 예측할 수 있게 설계"}],"memo":"UI 지침은 '단순하게, 일관되게'. '다양화', '많은 기능'은 함정이다."}},{"id":"written-2025-2-20","no":20,"unit":"소프트웨어 설계","q":"다음 중 애자일 방법론에 속하지 않는 것은?","choices":["칸반","개발 및 검증","익스트림 프로그래밍","기능 중심 개발"],"ans":2,"exp":{"concept":"애자일(Agile) 방법론은 고객과의 협업과 짧은 반복 개발로 변화에 빠르게 대응하는 개발 방법론들을 묶어 부르는 말이다. 대표적으로 익스트림 프로그래밍(XP), 스크럼(Scrum), 린(Lean), 칸반(Kanban), 기능 중심 개발(FDD), 크리스탈(Crystal), ASD, DSDM이 있다.","choices":[{"verdict":"오답","why":"칸반(Kanban)은 작업을 보드에 시각화해 진행 상황을 관리하는 애자일 방법론이다."},{"verdict":"정답","why":"'개발 및 검증'은 애자일 방법론의 이름이 아니다."},{"verdict":"오답","why":"익스트림 프로그래밍(XP)은 대표적인 애자일 방법론이다."},{"verdict":"오답","why":"기능 중심 개발(FDD, Feature Driven Development)은 기능 단위로 짧게 반복해 개발하는 애자일 방법론이다."}],"keywords":[{"term":"애자일 방법론","desc":"고객 협업과 짧은 반복으로 변화에 빠르게 대응하는 개발 방법론"},{"term":"스크럼(Scrum)","desc":"스프린트 단위로 반복 개발하는 팀 중심 애자일 방법론"},{"term":"칸반(Kanban)","desc":"작업을 보드에 시각화해 흐름을 관리하는 방법"},{"term":"기능 중심 개발(FDD)","desc":"기능 단위로 반복 개발하는 애자일 방법론"}],"memo":"애자일 대표 목록 XP, 스크럼, 린, 칸반, FDD, 크리스탈을 통째로 외워 두면 낯선 이름을 바로 골라낼 수 있다."}},{"id":"written-2025-2-21","no":21,"unit":"소프트웨어 개발","q":"소프트웨어 형상 관리의 관리 항목에 해당하지 않는 것은?","choices":["소스 코드","프로젝트 요구 분석서","운영 및 설치 지침서","프로젝트 개발 비용"],"ans":4,"exp":{"concept":"소프트웨어 형상 관리(SCM)는 개발 과정에서 만들어지는 산출물의 변경을 추적·통제하는 활동이다. 관리 대상(형상 항목)은 소스 코드, 요구 분석서, 설계서, 테스트 문서, 운영 및 설치 지침서처럼 개발 과정에서 만들어지는 산출물이다. 개발 비용은 산출물이 아니라 프로젝트 관리 정보다.","choices":[{"verdict":"오답","why":"소스 코드는 가장 대표적인 형상 관리 항목이다."},{"verdict":"오답","why":"프로젝트 요구 분석서는 개발 산출물이므로 형상 관리 항목이다."},{"verdict":"오답","why":"운영 및 설치 지침서도 개발 과정에서 만들어지는 문서이므로 형상 관리 항목이다."},{"verdict":"정답","why":"프로젝트 개발 비용은 개발 산출물이 아니라 비용 관리 대상이므로 형상 관리 항목에 해당하지 않는다."}],"keywords":[{"term":"형상 관리(SCM)","desc":"소프트웨어 산출물의 변경을 추적하고 통제하는 활동"},{"term":"형상 항목(SCI)","desc":"형상 관리의 대상이 되는 산출물(소스 코드, 문서 등)"},{"term":"형상 관리 절차","desc":"형상 식별 → 형상 통제 → 형상 감사 → 형상 기록(보고)"}],"memo":"형상 관리 대상은 '만들어진 결과물'이다. 비용, 인력, 일정 같은 관리 수치는 대상이 아니다."}},{"id":"written-2025-2-22","no":22,"unit":"소프트웨어 개발","q":"아래 트리의 차수(degree)는 얼마인가?<img class=\"q-img\" src=\"data/img/8dd792fc7e63ccc951beaa8fb7eab199.png\" width=\"494\" alt=\"문항 원본 자료\">","choices":["2","3","4","5"],"ans":2,"exp":{"concept":"트리에서 한 노드의 차수(degree)는 그 노드가 가진 자식(가지) 수이고, 트리의 차수는 모든 노드의 차수 중 가장 큰 값이다. 그림에서 A는 B, C 두 자식, B는 D, E, F 세 자식, C는 G 한 자식, F는 H, I 두 자식을 가진다. 가장 많은 자식을 가진 B의 차수 3이 트리의 차수다.","choices":[{"verdict":"오답","why":"2는 A나 F의 차수다. 트리의 차수는 가장 큰 노드 차수인 3이다."},{"verdict":"정답","why":"B가 D, E, F 세 자식을 가져 노드 차수 중 최댓값이 3이므로 트리의 차수는 3이다."},{"verdict":"오답","why":"자식이 4개인 노드는 그림에 없다."},{"verdict":"오답","why":"자식이 5개인 노드는 그림에 없다. 단말 노드(D, E, G, H, I)의 개수 5와 헷갈리지 않도록 주의한다."}],"keywords":[{"term":"노드의 차수","desc":"한 노드가 가진 자식(가지)의 수"},{"term":"트리의 차수","desc":"트리에 있는 노드 차수 중 가장 큰 값"},{"term":"단말 노드(Leaf)","desc":"자식이 없는 노드, 차수가 0"},{"term":"트리의 깊이(Depth)","desc":"루트부터 가장 깊은 노드까지의 레벨 수"}],"memo":"트리의 차수 = 자식이 가장 많은 노드의 자식 수. 노드 수나 단말 노드 수, 깊이와 헷갈리지 않는다."}},{"id":"written-2025-2-23","no":23,"unit":"소프트웨어 개발","q":"다음 중 소프트웨어 공학의 기본 원칙으로 볼 수 없는 것은?","choices":["인력을 최대한 많이 투입함","지속적으로 검증을 시행함","품질이 높은 소프트웨어 상품의 개발","결과에 대해 명확한 기록을 유지함"],"ans":1,"exp":{"concept":"소프트웨어 공학은 좋은 품질의 소프트웨어를 경제적으로 만들기 위한 학문이다. 기본 원칙은 현대적인 프로그래밍 기술을 계속 적용하고, 품질이 유지되도록 지속적으로 검증하며, 개발 관련 사항과 결과를 명확히 기록하는 것이다. 사람을 많이 넣는다고 좋은 소프트웨어가 나오지는 않는다.","choices":[{"verdict":"정답","why":"인력을 최대한 많이 투입하는 것은 원칙이 아니다. 오히려 늦어지는 프로젝트에 인력을 더 넣으면 의사소통 비용이 늘어 더 늦어진다(브룩스의 법칙)."},{"verdict":"오답","why":"개발된 소프트웨어의 품질이 유지되도록 지속적으로 검증하는 것은 소프트웨어 공학의 기본 원칙이다."},{"verdict":"오답","why":"품질이 높은 소프트웨어를 개발하는 것은 소프트웨어 공학이 추구하는 목표이자 원칙이다."},{"verdict":"오답","why":"개발 관련 사항과 결과에 대해 명확한 기록을 유지하는 것은 소프트웨어 공학의 기본 원칙이다."}],"keywords":[{"term":"소프트웨어 공학 기본 원칙","desc":"현대적 프로그래밍 기술 적용, 지속적 검증, 명확한 기록 유지"},{"term":"브룩스의 법칙","desc":"진행 중인 프로젝트에 인력을 추가하면 오히려 더 늦어진다는 법칙"}],"memo":"소프트웨어 공학은 '사람 수'가 아니라 '방법과 품질'. 인력을 최대한 투입한다는 보기는 브룩스의 법칙을 떠올려 거른다."}},{"id":"written-2025-2-24","no":24,"unit":"소프트웨어 개발","q":"프로그램 설계도 중 하나인 NS Chart에 관한 설명으로 가장 거리가 먼 것은?","choices":["화살표나 GOTO를 사용하므로 이해하기 쉽다.","이해하기 쉬우며 코드 변환이 용이하다.","논리의 기술에 중점을 두어 도형으로 표현하는 방법이다.","연속, 선택, 반복 등의 제어 논리 구조를 나타낸다."],"ans":1,"exp":{"concept":"NS 차트(Nassi-Schneiderman Chart)는 순서도 대신 상자 모양 도형으로 프로그램 논리를 그리는 구조적 설계 도구다. 순차, 선택, 다중 선택, 반복 같은 제어 구조를 상자 안에 넣어 표현하며, 화살표나 GOTO를 쓰지 않는다. 그래서 흐름이 엉키지 않고 코드로 옮기기 쉽다.","choices":[{"verdict":"정답","why":"NS 차트는 화살표나 GOTO를 사용하지 않는 것이 특징이다. 화살표와 GOTO를 쓴다는 설명은 틀렸다."},{"verdict":"오답","why":"구조가 상자로 정리되어 이해하기 쉽고 코드로 변환하기 쉽다. 옳은 설명이다."},{"verdict":"오답","why":"논리의 기술에 중점을 두고 도형으로 표현하는 방법이다. 옳은 설명이다."},{"verdict":"오답","why":"연속(순차), 선택, 반복 등의 제어 논리 구조를 표현한다. 옳은 설명이다."}],"keywords":[{"term":"NS 차트","desc":"논리 구조를 상자 도형으로 표현하는 구조적 설계 도구, 박스 다이어그램이라고도 함"},{"term":"구조적 프로그래밍","desc":"순차·선택·반복 구조만으로 프로그램을 작성하는 방법"},{"term":"GOTO문","desc":"지정한 위치로 무조건 이동하는 명령, 구조적 프로그래밍에서 지양"}],"memo":"NS 차트는 '상자 안에 다 넣어서' 표현하므로 화살표와 GOTO가 필요 없다."}},{"id":"written-2025-2-25","no":25,"unit":"소프트웨어 개발","q":"EAI(Enterprise Application Integration)의 구축 유형 가운데 Hybrid에 관한 설명으로 옳지 않은 것은?","choices":["필요에 따라 한 가지 방식만으로도 EAI 구현이 가능하다.","데이터 병목 현상을 최소화하는 것이 가능하다.","중간에 미들웨어를 두지 않은 채 각 애플리케이션을 point to point로 연결한다.","Hub &amp; Spoke 방식과 Message Bus 방식을 혼합한 형태이다."],"ans":3,"exp":{"concept":"EAI(Enterprise Application Integration)는 기업 안의 여러 애플리케이션을 연결해 데이터와 업무를 통합하는 솔루션이다. 구축 유형은 Point-to-Point, Hub & Spoke, Message Bus(ESB), Hybrid 네 가지다. Hybrid는 그룹 안에서는 Hub & Spoke, 그룹 사이에서는 Message Bus를 쓰는 혼합형으로, 필요하면 한 가지 방식만으로도 구현할 수 있고 데이터 병목을 최소화할 수 있다.","choices":[{"verdict":"오답","why":"Hybrid는 필요한 경우 한 가지 방식만으로도 EAI 구현이 가능하다. 옳은 설명이다."},{"verdict":"오답","why":"Hybrid는 그룹 내외를 다른 방식으로 나눠 처리하므로 데이터 병목 현상을 최소화할 수 있다. 옳은 설명이다."},{"verdict":"정답","why":"미들웨어 없이 애플리케이션을 1:1로 직접 연결하는 것은 Point-to-Point 방식의 설명이다. Hybrid에 대한 설명이 아니다."},{"verdict":"오답","why":"Hybrid는 Hub & Spoke 방식과 Message Bus 방식을 혼합한 형태다. 옳은 설명이다."}],"keywords":[{"term":"Point-to-Point","desc":"미들웨어 없이 애플리케이션을 1:1로 직접 연결, 변경과 재사용이 어려움"},{"term":"Hub & Spoke","desc":"중앙 허브를 거쳐 연결하는 중앙 집중형, 허브 장애 시 전체에 영향"},{"term":"Message Bus(ESB)","desc":"애플리케이션 사이에 미들웨어(버스)를 두는 방식, 확장성이 좋음"},{"term":"Hybrid","desc":"그룹 내는 Hub & Spoke, 그룹 간은 Message Bus를 쓰는 혼합형"}],"memo":"'미들웨어 없이 직접 연결'은 무조건 Point-to-Point. Hybrid는 '혼합, 병목 최소화'."}},{"id":"written-2025-2-26","no":26,"unit":"소프트웨어 개발","q":"소프트웨어 패키징에 관한 설명 중 틀린 것은?","choices":["신규 및 변경 개발소스를 식별한 뒤 이를 모듈화하여 상용제품으로 패키징 한다.","범용 환경에서 사용할 수 있도록 일반적인 배포 형태로 패키징을 진행한다.","패키징은 개발자를 중심으로 진행한다.","고객의 편의성을 위하여 매뉴얼 및 버전관리를 지속적으로 수행한다."],"ans":3,"exp":{"concept":"소프트웨어 패키징은 개발이 끝난 소프트웨어를 고객에게 전달할 수 있는 형태로 묶는 작업이다. 실제로 설치하고 쓰는 사람은 사용자이므로, 패키징은 개발자가 아니라 사용자 중심으로 진행한다. 신규·변경 소스를 식별해 모듈화하고, 범용 환경에서 쓸 수 있는 형태로 만들며, 매뉴얼과 버전을 꾸준히 관리한다.","choices":[{"verdict":"오답","why":"신규 및 변경 개발소스를 식별하고 모듈화해 상용제품으로 패키징한다. 옳은 설명이다."},{"verdict":"오답","why":"다양한 환경에서 쓸 수 있도록 일반적인 배포 형태로 패키징한다. 옳은 설명이다."},{"verdict":"정답","why":"패키징은 개발자가 아니라 사용자 중심으로 진행한다. 개발자 중심이라는 설명은 틀렸다."},{"verdict":"오답","why":"고객 편의를 위해 매뉴얼과 버전 관리를 지속적으로 수행한다. 옳은 설명이다."}],"keywords":[{"term":"소프트웨어 패키징","desc":"개발된 소프트웨어를 고객에게 전달할 형태로 묶는 작업"},{"term":"사용자 중심","desc":"패키징은 사용자의 실행 환경과 편의를 기준으로 진행"},{"term":"버전 관리","desc":"변경 이력을 기록하고 각 버전을 관리하는 활동"}],"memo":"패키징의 주인공은 사용자다. '개발자 중심'이 보이면 틀린 보기."}},{"id":"written-2025-2-27","no":27,"unit":"소프트웨어 개발","q":"노드(Node)와 선분(Branch)으로 이루어진 그래프의 특수한 형태로서, 정점 사이에 사이클(Cycle)이 형성되지 않고 자료 사이의 관계성이 계층 형식으로 나타나는 비선형 구조는?","choices":["stack","network","distributed","tree"],"ans":4,"exp":{"concept":"트리(Tree)는 노드와 선분(가지)으로 이루어진 그래프의 특수한 형태로, 사이클이 없고 부모-자식의 계층 관계를 이룬다. 회사 조직도나 컴퓨터의 폴더 구조처럼 한 노드 아래 여러 노드가 달리는 비선형 구조다.","choices":[{"verdict":"오답","why":"스택(stack)은 한쪽 끝에서만 삽입·삭제가 일어나는 후입선출(LIFO)의 선형 구조다."},{"verdict":"오답","why":"네트워크(network)는 노드들이 연결된 망 구조를 뜻하며, 사이클이 없는 계층 구조라는 조건을 만족하지 않는다."},{"verdict":"오답","why":"distributed(분산)는 자료 구조의 이름이 아니라 여러 곳에 나뉘어 있다는 뜻이다."},{"verdict":"정답","why":"트리는 사이클이 없고 계층 관계를 나타내는 비선형 구조다. 문제의 설명과 일치한다."}],"keywords":[{"term":"트리(Tree)","desc":"사이클이 없고 계층 관계를 갖는 비선형 자료 구조"},{"term":"그래프(Graph)","desc":"정점과 간선으로 이루어진 비선형 자료 구조, 사이클이 있을 수 있음"},{"term":"비선형 구조","desc":"트리, 그래프"},{"term":"선형 구조","desc":"배열, 스택, 큐, 데크, 연결 리스트"}],"memo":"'사이클 없음'과 '계층'이 함께 나오면 트리다."}},{"id":"written-2025-2-28","no":28,"unit":"소프트웨어 개발","q":"테스트를 목적에 따라 분류할 때, 강도(Stress) 테스트에 관한 설명으로 옳은 것은?","choices":["시스템에 고의로 실패를 유도한 뒤 시스템이 정상적으로 복귀하는지를 테스트한다.","사용자의 이벤트에 시스템이 응답하는 시간, 특정 시간 내에 처리하는 업무량, 사용자 요구에 시스템이 반응하는 속도 등을 테스트한다.","시스템에 과다 정보량을 부과해 과부하 시에도 시스템이 정상적으로 작동하는지 테스트한다.","부당하고 불법적인 침입을 시도해 보안시스템이 불법적인 침투를 잘 막아내는지를 테스트한다."],"ans":3,"exp":{"concept":"강도 테스트(Stress Test)는 시스템에 평소보다 훨씬 많은 데이터나 사용자 요청을 몰아 넣어, 과부하 상황에서도 시스템이 제대로 버티는지 확인하는 테스트다. 다리에 허용 하중보다 무거운 짐을 올려 보는 것과 같다. 목적에 따른 테스트에는 회복, 안전, 강도, 성능, 구조, 회귀, 병행 테스트가 있다.","choices":[{"verdict":"오답","why":"고의로 실패를 유도한 뒤 정상 복귀하는지 확인하는 것은 회복 테스트(Recovery Test)다."},{"verdict":"오답","why":"응답 시간, 처리 업무량, 반응 속도를 측정하는 것은 성능 테스트(Performance Test)다."},{"verdict":"정답","why":"과다한 정보량을 부과해 과부하 시에도 정상 작동하는지 확인하는 것이 강도 테스트다. 옳은 설명이다."},{"verdict":"오답","why":"불법적인 침입을 시도해 보안 시스템이 막아내는지 확인하는 것은 안전 테스트(Security Test)다."}],"keywords":[{"term":"강도 테스트(Stress)","desc":"과부하 상황에서도 정상 작동하는지 확인"},{"term":"성능 테스트(Performance)","desc":"응답 시간, 처리량, 반응 속도를 측정"},{"term":"회복 테스트(Recovery)","desc":"고의로 실패를 유도한 뒤 정상 복귀하는지 확인"},{"term":"안전 테스트(Security)","desc":"불법 침입을 막아내는지 확인"}],"memo":"강도(Stress)는 '과부하', 성능은 '속도·시간', 회복은 '실패 후 복귀', 안전은 '침입'."}},{"id":"written-2025-2-29","no":29,"unit":"소프트웨어 개발","q":"빌드 자동화 도구에 관한 설명 중 틀린 것은?","choices":["Gradle은 실행할 처리 명령들을 모아 태스크로 구성한 뒤 태스크 단위로 실행한다.","빌드 자동화 도구로는 Ant, Gradle, Jenkins 등이 있다.","빌드 자동화 도구는 지속적인 통합 개발 환경에서 유용하게 사용된다.","Jenkins는 Groovy를 기반으로 하는 오픈 소스로서 안드로이드 앱 개발 환경에서 사용된다."],"ans":4,"exp":{"concept":"빌드 자동화 도구는 소스 코드 컴파일, 테스트, 패키징 같은 빌드 과정을 자동으로 처리해 주는 도구로, 지속적 통합(CI) 환경에서 특히 유용하다. 대표 도구는 Ant, Maven, Jenkins, Gradle이다. Jenkins는 자바 기반의 지속적 통합 도구이고, 그루비(Groovy) 기반으로 안드로이드 앱 개발에 쓰이는 것은 Gradle이다.","choices":[{"verdict":"오답","why":"Gradle은 실행할 처리 명령들을 모아 태스크(Task)로 만들고 태스크 단위로 실행한다. 옳은 설명이다."},{"verdict":"오답","why":"Ant, Gradle, Jenkins는 모두 교재에 나오는 빌드 자동화 도구다. 옳은 설명이다."},{"verdict":"오답","why":"빌드 자동화 도구는 코드가 자주 통합되는 지속적 통합 환경에서 유용하다. 옳은 설명이다."},{"verdict":"정답","why":"Groovy 기반 오픈 소스로 안드로이드 앱 개발 환경에서 쓰이는 것은 Gradle이다. Jenkins는 자바 기반의 오픈 소스 지속적 통합 도구다."}],"keywords":[{"term":"Jenkins","desc":"자바 기반 오픈 소스 지속적 통합(CI) 도구, 웹 브라우저로 관리"},{"term":"Gradle","desc":"Groovy 기반 빌드 도구, 안드로이드 스튜디오의 공식 빌드 도구, 태스크 단위 실행"},{"term":"Ant","desc":"아파치 재단의 자바 빌드 도구, XML 기반 빌드 스크립트"},{"term":"지속적 통합(CI)","desc":"개발자들의 코드 변경을 자주 통합하고 자동으로 빌드·테스트하는 방식"}],"memo":"Groovy와 안드로이드는 Gradle, Jenkins는 자바 기반 CI 서버. 둘을 바꿔 쓴 보기가 단골이다."}},{"id":"written-2025-2-30","no":30,"unit":"소프트웨어 개발","q":"소프트웨어 테스트에서 오류의 80%는 전체 모듈의 20% 내에서 발견된다는 법칙은 무엇인가?","choices":["Brooks의 법칙","Jackson의 법칙","Boehm의 법칙","Pareto의 법칙"],"ans":4,"exp":{"concept":"파레토(Pareto)의 법칙은 '결과의 80%는 원인의 20%에서 나온다'는 경험 법칙이다. 소프트웨어 테스트 원리에서는 오류의 80%가 전체 모듈의 20% 안에서 발견된다는 결함 집중을 설명할 때 쓴다. 그래서 오류가 많이 나온 모듈을 집중적으로 테스트하는 것이 효과적이다.","choices":[{"verdict":"오답","why":"브룩스(Brooks)의 법칙은 일정이 늦어진 프로젝트에 인력을 추가하면 오히려 더 늦어진다는 법칙이다."},{"verdict":"오답","why":"잭슨(Jackson)의 법칙은 이 문장을 가리키는 테스트 원리가 아니며, 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"보헴(Boehm)은 COCOMO 모형과 나선형 모형을 제안한 학자로, 80:20 결함 집중을 가리키는 법칙 이름이 아니다."},{"verdict":"정답","why":"파레토의 법칙은 오류의 80%가 전체 모듈의 20%에서 발견된다는 결함 집중 원리를 설명한다. 문제의 설명과 일치한다."}],"keywords":[{"term":"파레토의 법칙","desc":"오류의 80%는 전체 모듈의 20%에서 발견된다"},{"term":"결함 집중","desc":"결함이 소수의 특정 모듈에 몰려 있다는 테스트 원리"},{"term":"브룩스의 법칙","desc":"늦어진 프로젝트에 인력을 추가하면 더 늦어진다"},{"term":"살충제 패러독스","desc":"같은 테스트를 반복하면 새로운 결함을 찾지 못한다는 원리"}],"memo":"80:20이 나오면 파레토. 인력 추가는 브룩스."}},{"id":"written-2025-2-31","no":31,"unit":"소프트웨어 개발","q":"아래 자료를 “Selection Sort”로 오름차순 정렬할 때 PASS 3의 결과는?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><p>초기상태 : 8, 3, 4, 9, 7</p></div>","choices":["3, 4, 7, 9, 8","3, 4, 8, 9, 7","3, 8, 4, 9, 7","3, 4, 7, 8, 9"],"ans":1,"exp":{"concept":"선택 정렬(Selection Sort)은 남은 자료 중 가장 작은 값을 골라 맨 앞자리와 바꾸는 과정을 반복한다. 한 PASS가 끝날 때마다 앞에서부터 한 자리씩 확정된다. 8, 3, 4, 9, 7에서 PASS 1은 최솟값 3을 첫 자리 8과 바꿔 3, 8, 4, 9, 7, PASS 2는 남은 8, 4, 9, 7 중 4를 둘째 자리 8과 바꿔 3, 4, 8, 9, 7, PASS 3은 남은 8, 9, 7 중 7을 셋째 자리 8과 바꿔 3, 4, 7, 9, 8이 된다.","choices":[{"verdict":"정답","why":"PASS 3에서 셋째 자리부터 남은 8, 9, 7 중 최솟값 7을 셋째 자리의 8과 교환하므로 3, 4, 7, 9, 8이 된다. 정답이다."},{"verdict":"오답","why":"3, 4, 8, 9, 7은 PASS 2가 끝난 결과다."},{"verdict":"오답","why":"3, 8, 4, 9, 7은 PASS 1이 끝난 결과다."},{"verdict":"오답","why":"3, 4, 7, 8, 9는 PASS 4까지 끝나 정렬이 완료된 결과다."}],"keywords":[{"term":"선택 정렬","desc":"남은 자료 중 최솟값을 찾아 맨 앞자리와 교환하기를 반복하는 정렬"},{"term":"PASS","desc":"정렬에서 비교·교환을 한 바퀴 수행하는 단위"},{"term":"버블 정렬","desc":"인접한 두 값을 비교·교환해 큰 값을 뒤로 보내는 정렬"},{"term":"삽입 정렬","desc":"앞쪽의 정렬된 부분에 새 값을 알맞은 위치에 끼워 넣는 정렬"}],"memo":"선택 정렬은 PASS마다 앞에서 한 칸씩 확정된다. PASS n이면 앞 n칸이 확정되어 있어야 한다."}},{"id":"written-2025-2-32","no":32,"unit":"소프트웨어 개발","q":"소프트웨어 품질 목표 가운데, 하나 이상의 하드웨어 환경에서 운용될 수 있도록 쉽게 수정 가능한 시스템의 능력을 뜻하는 것은?","choices":["Usability","Efficiency","Correctness","Portability"],"ans":4,"exp":{"concept":"소프트웨어 품질 목표는 좋은 소프트웨어가 갖춰야 할 특성들이다. 이식성(Portability)은 다른 하드웨어나 운영체제 환경으로 옮겨도 쉽게 수정해 쓸 수 있는 능력이다. 같은 게임을 PC, 콘솔, 휴대폰으로 쉽게 옮길 수 있다면 이식성이 높은 것이다.","choices":[{"verdict":"오답","why":"사용 용이성(Usability)은 사용자가 쉽게 배우고 사용할 수 있는 정도다."},{"verdict":"오답","why":"효율성(Efficiency)은 최소한의 자원(시간, 메모리 등)으로 요구 기능을 수행하는 정도다."},{"verdict":"오답","why":"정확성(Correctness)은 사용자의 요구 기능을 정확하게 충족시키는 정도다."},{"verdict":"정답","why":"이식성(Portability)은 하나 이상의 하드웨어 환경에서 운용될 수 있도록 쉽게 수정할 수 있는 능력이다. 문제의 설명과 일치한다."}],"keywords":[{"term":"이식성(Portability)","desc":"다른 하드웨어·소프트웨어 환경에서도 쉽게 수정해 운용할 수 있는 능력"},{"term":"정확성(Correctness)","desc":"요구 기능을 정확하게 충족시키는 정도"},{"term":"효율성(Efficiency)","desc":"최소한의 자원으로 기능을 수행하는 정도"},{"term":"사용 용이성(Usability)","desc":"사용자가 쉽게 배우고 사용할 수 있는 정도"}],"memo":"'다른 환경에서도 운용'이 나오면 이식성(Portability, 옮기다 port)."}},{"id":"written-2025-2-33","no":33,"unit":"소프트웨어 개발","q":"다음 중 인터페이스 구현 검증 도구에 해당하지 않는 것은?","choices":["xUnit","watir","STAF","Foxbase"],"ans":4,"exp":{"concept":"인터페이스 구현 검증 도구는 모듈이나 시스템 사이의 인터페이스가 제대로 동작하는지 테스트하는 도구다. 교재에 나오는 도구는 xUnit, STAF, FitNesse, NTAF, Selenium, watir이다. 목록에 없는 이름이 나오면 정답 후보로 의심한다.","choices":[{"verdict":"오답","why":"xUnit은 JUnit, CppUnit 등 다양한 언어를 지원하는 단위 테스트 프레임워크로, 인터페이스 구현 검증 도구다."},{"verdict":"오답","why":"watir는 루비(Ruby) 기반의 웹 애플리케이션 테스트 프레임워크로, 인터페이스 구현 검증 도구다."},{"verdict":"오답","why":"STAF는 서비스 호출과 컴포넌트 재사용 등 다양한 환경을 지원하는 테스트 프레임워크로, 인터페이스 구현 검증 도구다."},{"verdict":"정답","why":"Foxbase는 예전 PC용 데이터베이스 관리 프로그램(dBASE 계열)으로, 인터페이스 구현 검증 도구가 아니다."}],"keywords":[{"term":"xUnit","desc":"Java(JUnit), C++(CppUnit) 등 여러 언어를 지원하는 단위 테스트 프레임워크"},{"term":"STAF","desc":"서비스 호출, 컴포넌트 재사용 등을 지원하는 테스트 프레임워크"},{"term":"FitNesse","desc":"웹 기반 테스트 케이스 설계·실행·결과 확인을 지원하는 프레임워크"},{"term":"Selenium","desc":"다양한 브라우저와 개발 언어를 지원하는 웹 애플리케이션 테스트 프레임워크"},{"term":"watir","desc":"Ruby 기반 웹 애플리케이션 테스트 프레임워크"}],"memo":"인터페이스 검증 도구 여섯: xUnit, STAF, FitNesse, NTAF, Selenium, watir. 이 밖의 이름은 오답 후보."}},{"id":"written-2025-2-34","no":34,"unit":"소프트웨어 개발","q":"개별 모듈을 대상으로 시험하는 것으로, 모듈이 정확하게 구현되었는지와 예정된 기능이 제대로 수행되는지를 점검하는 것을 주목적으로 하는 테스트는?","choices":["인수 테스트(Acceptance Test)","통합 테스트(Integration Test)","시스템 테스트(System Test)","단위 테스트(Unit Test)"],"ans":4,"exp":{"concept":"테스트는 범위가 작은 것부터 단위 테스트 → 통합 테스트 → 시스템 테스트 → 인수 테스트 순으로 진행한다. 단위 테스트(Unit Test)는 가장 작은 단위인 개별 모듈을 대상으로, 모듈이 정확히 구현되었고 기능을 제대로 수행하는지 확인한다. 자동차로 치면 엔진, 브레이크 같은 부품을 하나씩 검사하는 단계다.","choices":[{"verdict":"오답","why":"인수 테스트는 개발이 끝난 뒤 사용자가 요구사항을 충족하는지 확인하고 인수 여부를 결정하는 테스트다."},{"verdict":"오답","why":"통합 테스트는 단위 테스트를 마친 모듈들을 결합하면서 모듈 간 인터페이스 오류를 찾는 테스트다."},{"verdict":"오답","why":"시스템 테스트는 통합된 전체 시스템이 실제 환경에서 기능·비기능 요구사항을 만족하는지 확인하는 테스트다."},{"verdict":"정답","why":"단위 테스트는 개별 모듈을 대상으로 정확한 구현과 기능 수행 여부를 점검하는 테스트다. 문제의 설명과 일치한다."}],"keywords":[{"term":"단위 테스트","desc":"개별 모듈의 구현과 기능을 점검"},{"term":"통합 테스트","desc":"모듈을 결합하며 인터페이스 오류를 점검"},{"term":"시스템 테스트","desc":"전체 시스템이 실제 환경에서 요구사항을 만족하는지 점검"},{"term":"인수 테스트","desc":"사용자가 요구 충족 여부를 확인하고 인수를 결정"}],"memo":"'개별 모듈'은 단위, '결합·인터페이스'는 통합, '전체 시스템'은 시스템, '사용자 인수'는 인수 테스트."}},{"id":"written-2025-2-35","no":35,"unit":"소프트웨어 개발","q":"테스트와 디버그의 목적에 대한 설명으로 옳은 것은?","choices":["둘 다 소프트웨어 오류의 발견 및 수정과는 무관하다.","테스트는 오류를 찾는 작업이며 디버깅은 오류를 수정하는 작업이다.","테스트는 오류를 수정하는 작업이며 디버깅은 오류를 찾는 작업이다.","둘 다 소프트웨어의 오류를 찾는 작업이며 오류 수정은 하지 않는다."],"ans":2,"exp":{"concept":"테스트와 디버깅은 비슷해 보이지만 하는 일이 다르다. 테스트는 프로그램을 실행해 오류가 있는지 찾아내는 작업이고, 디버깅은 찾은 오류의 원인을 추적해 고치는 작업이다. 건강 검진(테스트)으로 병을 찾고 치료(디버깅)로 고치는 것과 같다.","choices":[{"verdict":"오답","why":"테스트와 디버깅 모두 소프트웨어 오류의 발견·수정과 직접 관련된 작업이므로 틀렸다."},{"verdict":"정답","why":"테스트는 오류를 찾는 작업이고 디버깅은 오류를 수정하는 작업이다. 옳은 설명이다."},{"verdict":"오답","why":"테스트와 디버깅의 역할을 서로 바꿔 말한 설명이다."},{"verdict":"오답","why":"디버깅은 오류의 원인을 찾아 수정하는 작업이므로, 둘 다 수정하지 않는다는 설명은 틀렸다."}],"keywords":[{"term":"테스트(Test)","desc":"프로그램을 실행해 오류를 찾아내는 작업"},{"term":"디버깅(Debugging)","desc":"발견된 오류의 원인을 찾아 수정하는 작업"}],"memo":"테스트는 '찾기', 디버깅은 '고치기'(버그를 없앤다 de-bug)."}},{"id":"written-2025-2-36","no":36,"unit":"소프트웨어 개발","q":"소프트웨어 테스트의 검증(Verification)과 확인(Validation)에 관한 설명 중 틀린 것은?","choices":["검증은 작업 제품이 요구 명세의 기능, 비기능 요구사항을 얼마나 잘 준수하는지를 측정하는 작업이다.","검증은 소프트웨어 개발 과정을 테스트하는 것이며, 확인은 소프트웨어 결과를 테스트하는 것이다.","검증은 작업 제품이 사용자의 요구에 적합한지를 측정하고, 확인은 작업 제품이 개발자의 기대를 충족하는지를 측정한다.","소프트웨어 테스트에서 검증과 확인을 구별하면 찾으려는 결함 유형을 명확히 하는 데 도움이 된다."],"ans":3,"exp":{"concept":"검증(Verification)은 '제품을 올바르게 만들고 있는가', 즉 명세서대로 만들어지는지를 개발 과정에서 확인하는 것이다. 확인(Validation)은 '올바른 제품을 만들었는가', 즉 결과물이 사용자의 요구에 맞는지를 확인하는 것이다. 검증은 개발자 관점, 확인은 사용자 관점이라고 기억하면 된다.","choices":[{"verdict":"오답","why":"검증은 작업 제품이 요구 명세의 기능·비기능 요구사항을 얼마나 잘 지키는지 측정한다. 옳은 설명이다."},{"verdict":"오답","why":"검증은 개발 과정을, 확인은 결과물을 테스트한다. 옳은 설명이다."},{"verdict":"정답","why":"설명이 서로 바뀌었다. 사용자의 요구에 적합한지 측정하는 것은 확인(Validation)이고, 명세와 개발자의 기대대로 만들어졌는지 측정하는 것은 검증(Verification)이다."},{"verdict":"오답","why":"검증과 확인을 구별하면 찾으려는 결함의 유형을 명확히 할 수 있다. 옳은 설명이다."}],"keywords":[{"term":"검증(Verification)","desc":"개발 과정 테스트, 명세서대로 만들어졌는지 확인, 개발자 관점"},{"term":"확인(Validation)","desc":"결과 테스트, 사용자 요구를 충족하는지 확인, 사용자 관점"}],"memo":"Verification은 '명세대로?'(개발자), Validation은 '사용자 마음에?'(사용자). 둘을 바꾼 보기가 단골이다."}},{"id":"written-2025-2-37","no":37,"unit":"소프트웨어 개발","q":"디지털 저작권 관리(DRM) 기술에 해당하지 않는 것은?","choices":["라이센스 발급 및 관리","콘텐츠 식별체계 표현","콘텐츠 암호화 및 키 관리","콘텐츠 오류 감지 및 복구"],"ans":4,"exp":{"concept":"디지털 저작권 관리(DRM)는 디지털 콘텐츠를 허가받은 사용자만 정해진 권한대로 쓰도록 보호하는 기술이다. 주요 기술 요소는 암호화, 키 관리, 암호화 파일 생성(패키저), 식별 기술, 저작권 표현, 정책 관리, 크랙 방지, 인증이고, 라이선스 발급·관리는 클리어링 하우스가 맡는다. 콘텐츠의 오류를 고치는 기능은 DRM의 목적과 관계가 없다.","choices":[{"verdict":"오답","why":"라이선스 발급 및 관리는 클리어링 하우스(Clearing House)가 담당하는 DRM의 구성 요소다."},{"verdict":"오답","why":"콘텐츠를 구별하기 위한 식별 체계 표현(식별 기술)은 DRM 기술 요소다."},{"verdict":"오답","why":"콘텐츠 암호화와 키 관리는 DRM의 핵심 기술 요소다."},{"verdict":"정답","why":"콘텐츠 오류 감지 및 복구는 데이터 전송·저장의 신뢰성 기술이지 저작권 보호를 위한 DRM 기술이 아니다."}],"keywords":[{"term":"DRM","desc":"디지털 콘텐츠의 사용 권한을 관리하고 보호하는 기술"},{"term":"클리어링 하우스","desc":"저작권 사용 권한, 라이선스 발급, 결제를 관리하는 곳"},{"term":"패키저(Packager)","desc":"콘텐츠를 메타 데이터와 함께 배포 가능한 형태로 묶어 암호화하는 프로그램"},{"term":"크랙 방지(Tamper Resistance)","desc":"크랙에 의한 콘텐츠 불법 사용을 막는 기술"}],"memo":"DRM은 '권한과 보호'(암호화, 키, 식별, 인증, 라이선스). '오류 복구'는 엉뚱한 보기다."}},{"id":"written-2025-2-38","no":38,"unit":"소프트웨어 개발","q":"White Box Testing에 관한 설명 중 옳지 않은 것은?","choices":["모듈 안의 작동을 직접 관찰하는 것이 가능하다.","산출물의 각 기능별로 적절한 프로그램의 제어 구조에 따라 선택, 반복 등의 부분들을 수행하여 논리적 경로를 점검한다.","대표적인 기법으로 Base Path Testing, Boundary Value Analysis가 있다.","Source Code의 모든 문장을 한 번 이상 수행하는 방식으로 진행된다."],"ans":3,"exp":{"concept":"화이트박스 테스트는 프로그램 내부 구조와 소스 코드를 보면서 모든 경로와 문장이 제대로 동작하는지 확인하는 테스트다. 대표 기법은 기초 경로 검사(Base Path Testing), 제어 구조 검사(조건, 루프, 데이터 흐름 검사)다. 경곗값 분석은 내부를 보지 않고 입력과 출력만 보는 블랙박스 테스트 기법이다.","choices":[{"verdict":"오답","why":"화이트박스 테스트는 모듈 안의 동작을 직접 관찰할 수 있다. 옳은 설명이다."},{"verdict":"오답","why":"선택, 반복 같은 제어 구조를 수행하며 논리적 경로를 점검한다. 옳은 설명이다."},{"verdict":"정답","why":"기초 경로 검사는 화이트박스 기법이지만 경곗값 분석(Boundary Value Analysis)은 블랙박스 기법이므로 틀렸다."},{"verdict":"오답","why":"소스 코드의 모든 문장을 한 번 이상 수행하도록 테스트를 진행한다. 옳은 설명이다."}],"keywords":[{"term":"화이트박스 테스트","desc":"내부 구조와 소스 코드를 보며 논리 경로를 검사"},{"term":"기초 경로 검사","desc":"제어 흐름의 독립 경로를 모두 수행하는 화이트박스 기법"},{"term":"블랙박스 테스트","desc":"내부를 보지 않고 명세된 기능과 입출력을 검사"},{"term":"경곗값 분석","desc":"입력 범위의 경계 값에서 오류를 찾는 블랙박스 기법"}],"memo":"동치 분할, 경곗값 분석, 원인-효과 그래프, 오류 예측, 비교 검사는 블랙박스 기법이다. 이 이름이 화이트박스 보기에 섞이면 틀린 것이다."}},{"id":"written-2025-2-39","no":39,"unit":"소프트웨어 개발","q":"자료 구조에 관한 설명 중 틀린 것은?","choices":["스택은 서브루틴 호출, 인터럽트 처리, 수식 계산 및 수식 표기법 등에 응용된다.","큐는 First In - First Out 방식으로 처리를 수행한다.","스택은 Last In - First Out 방식으로 처리를 수행한다.","큐는 비선형 구조에 속한다."],"ans":4,"exp":{"concept":"자료 구조는 자료가 한 줄로 늘어선 선형 구조(배열, 스택, 큐, 데크, 연결 리스트)와 한 자료에 여러 자료가 이어지는 비선형 구조(트리, 그래프)로 나뉜다. 스택은 나중에 넣은 것이 먼저 나오는 LIFO, 큐는 먼저 넣은 것이 먼저 나오는 FIFO다. 큐는 줄 서기처럼 한 줄로 늘어서므로 선형 구조다.","choices":[{"verdict":"오답","why":"스택은 서브루틴 호출, 인터럽트 처리, 수식 계산과 표기법 변환 등에 응용된다. 옳은 설명이다."},{"verdict":"오답","why":"큐는 먼저 들어온 것이 먼저 나가는 FIFO 방식이다. 옳은 설명이다."},{"verdict":"오답","why":"스택은 나중에 들어온 것이 먼저 나가는 LIFO 방식이다. 옳은 설명이다."},{"verdict":"정답","why":"큐는 선형 구조다. 비선형 구조는 트리와 그래프다."}],"keywords":[{"term":"스택(Stack)","desc":"한쪽 끝에서만 삽입·삭제하는 LIFO 구조"},{"term":"큐(Queue)","desc":"한쪽에서 삽입, 다른 쪽에서 삭제하는 FIFO 구조"},{"term":"선형 구조","desc":"배열, 스택, 큐, 데크, 연결 리스트"},{"term":"비선형 구조","desc":"트리, 그래프"}],"memo":"비선형 구조는 트리와 그래프 둘뿐이라고 외우면 나머지는 모두 선형이다."}},{"id":"written-2025-2-40","no":40,"unit":"소프트웨어 개발","q":"소스 코드 품질 분석 도구 가운데 정적 분석 도구에 해당하지 않는 것은?","choices":["Valgrind","cppcheck","pmd","checkstyle"],"ans":1,"exp":{"concept":"소스 코드 품질 분석 도구는 프로그램을 실행하지 않고 코드를 분석하는 정적 분석 도구와, 프로그램을 실행하면서 메모리 누수나 스레드 결함을 찾는 동적 분석 도구로 나뉜다. 대표적인 정적 분석 도구는 pmd, cppcheck, SonarQube, checkstyle이고, 동적 분석 도구는 Avalanche, Valgrind다.","choices":[{"verdict":"정답","why":"Valgrind는 프로그램을 실행하면서 메모리 누수와 스레드 결함 등을 찾는 동적 분석 도구이므로 정적 분석 도구가 아니다."},{"verdict":"오답","why":"cppcheck는 C/C++ 코드의 메모리 누수, 오버플로 등을 실행 없이 분석하는 정적 분석 도구다."},{"verdict":"오답","why":"pmd는 자바 등의 소스 코드에서 미사용 변수, 중복 코드 같은 결함을 찾는 정적 분석 도구다."},{"verdict":"오답","why":"checkstyle은 자바 코드가 코딩 표준을 지키는지 검사하는 정적 분석 도구다."}],"keywords":[{"term":"정적 분석 도구","desc":"실행 없이 코드를 분석: pmd, cppcheck, SonarQube, checkstyle 등"},{"term":"동적 분석 도구","desc":"실행하면서 분석: Avalanche, Valgrind"},{"term":"Valgrind","desc":"프로그램 실행 중 메모리 누수와 스레드 결함을 분석하는 도구"}],"memo":"동적 분석 도구는 Avalanche와 Valgrind 두 개만 외워 두면, 나머지 보기는 정적 분석 도구로 거를 수 있다."}},{"id":"written-2025-2-41","no":41,"unit":"데이터베이스 구축","q":"데이터베이스의 무결성 규정(Integrity Rule)에 관한 설명으로 옳지 않은 것은?","choices":["무결성 규정의 대상에는 도메인, 키, 종속성 등이 있다.","무결성 규정에는 데이터가 만족해야 하는 제약 조건, 규정을 참조할 때 쓰이는 식별자 등의 요소가 포함될 수 있다.","릴레이션 무결성 규정(Relation Integrity Rules)은 릴레이션을 조작하는 과정에서 나타나는 의미적 관계(Semantic Relationship)를 명세한 것이다.","정식으로 허가받지 않은 불법적인 사용자에 의한 갱신으로부터 데이터베이스를 보호하기 위한 규정이다."],"ans":4,"exp":{"concept":"무결성(Integrity)은 데이터베이스에 저장된 값이 실제 의미와 맞고 정확하게 유지되는 성질이다. 무결성 규정은 데이터가 지켜야 할 제약 조건을 정한 것으로, 허가받은 사용자가 실수로 잘못된 값을 넣는 것을 막는다. 허가받지 않은 사용자의 접근을 막는 것은 무결성이 아니라 보안(Security)의 역할이다.","choices":[{"verdict":"오답","why":"무결성 규정의 대상에는 도메인, 키, 종속성 등이 있다. 옳은 설명이다."},{"verdict":"오답","why":"무결성 규정에는 데이터가 만족해야 할 제약 조건, 규정을 참조할 때 쓰는 식별자 등의 요소가 포함될 수 있다. 옳은 설명이다."},{"verdict":"오답","why":"릴레이션 무결성 규정은 릴레이션을 조작하는 과정에서 나타나는 의미적 관계를 명세한 것이다. 옳은 설명이다."},{"verdict":"정답","why":"허가받지 않은 불법 사용자의 갱신으로부터 데이터베이스를 보호하는 것은 보안의 개념이다. 무결성은 허가받은 사용자의 잘못된 갱신으로부터 데이터의 정확성을 지키는 것이다."}],"keywords":[{"term":"무결성(Integrity)","desc":"데이터베이스의 데이터가 정확하고 의미에 맞게 유지되는 성질"},{"term":"보안(Security)","desc":"허가받지 않은 사용자의 접근·변경으로부터 데이터를 보호"},{"term":"개체 무결성","desc":"기본키는 NULL이나 중복 값을 가질 수 없다는 제약"},{"term":"참조 무결성","desc":"외래키 값은 NULL이거나 참조하는 릴레이션의 기본키 값이어야 한다는 제약"}],"memo":"'불법적인 사용자', '허가받지 않은'은 보안. 무결성은 '정확성'이다."}},{"id":"written-2025-2-42","no":42,"unit":"데이터베이스 구축","q":"뷰(VIEW)에 관한 설명 중 옳지 않은 것은?","choices":["DBA는 보안 측면에서 뷰를 이용할 수 있다.","하나의 뷰 위에 또 다른 뷰를 정의하는 것이 가능하다.","뷰에 대해 삽입, 갱신, 삭제 연산을 수행할 때 제약사항이 따르지 않는다.","독립적인 인덱스를 가질 수 없다."],"ans":3,"exp":{"concept":"뷰(View)는 기본 테이블에서 필요한 부분만 골라 보여 주는 가상 테이블이다. 실제 데이터를 따로 저장하지 않으므로 독립적인 인덱스를 가질 수 없고, 뷰를 통한 삽입·갱신·삭제에는 제약이 따른다. 사용자에게 필요한 데이터만 보여 줄 수 있어 보안에 유리하다.","choices":[{"verdict":"오답","why":"뷰로 사용자가 볼 수 있는 데이터를 제한할 수 있어, DBA는 보안 목적으로 뷰를 활용한다. 옳은 설명이다."},{"verdict":"오답","why":"뷰 위에 또 다른 뷰를 정의할 수 있다. 옳은 설명이다."},{"verdict":"정답","why":"뷰는 가상 테이블이라 삽입, 갱신, 삭제 연산에 제약이 따른다. 예를 들어 기본키가 빠진 뷰나 집계 함수로 만든 뷰는 변경할 수 없다. 제약이 없다는 설명은 틀렸다."},{"verdict":"오답","why":"뷰는 물리적으로 저장되지 않으므로 독립적인 인덱스를 가질 수 없다. 옳은 설명이다."}],"keywords":[{"term":"뷰(View)","desc":"기본 테이블에서 유도된 가상 테이블"},{"term":"뷰의 장점","desc":"논리적 데이터 독립성 제공, 데이터 보안, 사용자 데이터 관리 단순화"},{"term":"뷰의 단점","desc":"독립적인 인덱스 불가, ALTER VIEW로 정의 변경 불가, 삽입·갱신·삭제에 제약"}],"memo":"뷰는 '가상'이다. 가상이라 인덱스도 없고 변경도 자유롭지 않다."}},{"id":"written-2025-2-43","no":43,"unit":"데이터베이스 구축","q":"이행적 함수 종속 관계에 해당하는 것은?","choices":["A → B이고 B → C일 때, A → C가 성립하는 관계","A → B이고 B → C일 때, B → A가 성립하는 관계","A → B이고 B → C일 때, C → A가 성립하는 관계","A → B이고 B → C일 때, C → B가 성립하는 관계"],"ans":1,"exp":{"concept":"함수 종속 A → B는 A 값을 알면 B 값이 하나로 정해진다는 뜻이다. 이행적 함수 종속은 A → B이고 B → C일 때 A → C가 성립하는 관계로, A가 B를 거쳐 간접적으로 C를 결정한다. 학번 → 학과, 학과 → 학과사무실이면 학번 → 학과사무실이 이행적 종속이다.","choices":[{"verdict":"정답","why":"A → B, B → C에서 A → C가 성립하는 것이 이행적 함수 종속이다. 옳은 설명이다."},{"verdict":"오답","why":"B → A는 역방향 종속으로, 이행적 함수 종속의 정의가 아니다."},{"verdict":"오답","why":"C → A는 이행 관계에서 도출되지 않으며 이행적 함수 종속의 정의가 아니다."},{"verdict":"오답","why":"C → B도 역방향 종속으로, 이행적 함수 종속의 정의가 아니다."}],"keywords":[{"term":"함수 종속","desc":"X 값에 따라 Y 값이 하나로 결정되는 관계(X → Y)"},{"term":"이행적 함수 종속","desc":"A → B, B → C이면 A → C가 성립하는 관계"},{"term":"제3정규형(3NF)","desc":"2NF에서 이행적 함수 종속을 제거한 정규형"}],"memo":"이행(移行)은 '건너가다'. A에서 B를 건너 C로 간다(A → C)."}},{"id":"written-2025-2-44","no":44,"unit":"데이터베이스 구축","q":"회복 기법 중 데이터베이스 로그(log)가 필요한 것은?","choices":["즉각 갱신 기법","타임 스탬프 기법","폴딩 기법","대수적 코딩 방법"],"ans":1,"exp":{"concept":"회복은 장애가 난 데이터베이스를 장애 이전의 정상 상태로 되돌리는 것이다. 즉각 갱신 기법은 트랜잭션이 끝나기 전이라도 변경 내용을 바로 데이터베이스에 반영하므로, 장애 시 로그(log)에 기록된 이전 값과 이후 값으로 Undo와 Redo를 수행한다. 로그는 일종의 작업 일지다.","choices":[{"verdict":"정답","why":"즉각 갱신(Immediate Update) 기법은 변경 내용을 즉시 반영하고 모든 변경을 로그에 기록해 두었다가 장애 시 로그로 Redo와 Undo를 수행한다. 로그가 필요한 회복 기법이다."},{"verdict":"오답","why":"타임 스탬프 기법은 트랜잭션에 시간표를 붙여 실행 순서를 정하는 병행 제어 기법이다."},{"verdict":"오답","why":"폴딩(Folding) 기법은 레코드 키를 여러 부분으로 나누어 더하거나 XOR해 주소를 구하는 해싱 함수 기법이다."},{"verdict":"오답","why":"대수적 코딩 방법도 키 값의 각 자리를 이용해 해시 주소를 구하는 해싱 함수 기법이다."}],"keywords":[{"term":"즉각 갱신 기법","desc":"변경을 즉시 반영하고 로그로 Redo·Undo를 수행하는 회복 기법"},{"term":"지연 갱신 기법","desc":"트랜잭션이 완료될 때까지 반영을 미루는 기법, Undo가 필요 없음"},{"term":"로그(Log)","desc":"트랜잭션이 바꾼 데이터의 이전 값과 이후 값을 기록한 파일"},{"term":"검사점 기법","desc":"검사점(Checkpoint)을 두어 그 이후 작업만 회복하는 기법"}],"memo":"회복 기법(즉각 갱신, 지연 갱신, 검사점, 그림자 페이징)과 해싱 함수(제산, 폴딩, 숫자 분석, 대수적 코딩 등)를 섞어 내는 문제다. 소속부터 구분한다."}},{"id":"written-2025-2-45","no":45,"unit":"데이터베이스 구축","q":"병행제어의 로킹(Locking) 단위에 관한 설명 중 옳지 않은 것은?","choices":["로킹 단위가 작아질수록 데이터베이스 공유도는 증가한다.","한꺼번에 로킹할 수 있는 객체의 크기를 로킹 단위라 한다.","로킹 단위가 작아질수록 로킹 오버헤드는 감소한다.","데이터베이스, 파일, 레코드 등이 로킹 단위가 될 수 있다."],"ans":3,"exp":{"concept":"로킹(Locking)은 트랜잭션이 데이터를 쓰는 동안 자물쇠를 걸어 다른 트랜잭션이 끼어들지 못하게 하는 병행 제어 기법이다. 자물쇠를 거는 대상의 크기를 로킹 단위라고 한다. 단위가 작으면 여러 트랜잭션이 동시에 쓸 수 있어 공유도(병행성)는 높아지지만, 관리할 자물쇠 수가 많아져 오버헤드가 커진다.","choices":[{"verdict":"오답","why":"로킹 단위가 작을수록 잠기는 범위가 좁아 여러 트랜잭션이 동시에 데이터를 쓸 수 있으므로 공유도가 증가한다. 옳은 설명이다."},{"verdict":"오답","why":"한꺼번에 로킹할 수 있는 객체의 크기를 로킹 단위라고 한다. 옳은 설명이다."},{"verdict":"정답","why":"로킹 단위가 작아지면 걸어야 할 로크의 수가 많아져 로킹 오버헤드는 증가한다. 감소한다는 설명은 틀렸다."},{"verdict":"오답","why":"데이터베이스, 파일, 레코드, 필드 등이 모두 로킹 단위가 될 수 있다. 옳은 설명이다."}],"keywords":[{"term":"로킹(Locking)","desc":"데이터에 잠금을 걸어 다른 트랜잭션의 접근을 막는 병행 제어 기법"},{"term":"로킹 단위 작음","desc":"병행성(공유도) 높음, 로크 수 많음, 오버헤드 큼"},{"term":"로킹 단위 큼","desc":"병행성 낮음, 로크 수 적음, 관리 쉬움"}],"memo":"단위가 작으면 '공유도↑ 오버헤드↑', 크면 '공유도↓ 오버헤드↓'. 두 값이 같은 방향으로 움직인다."}},{"id":"written-2025-2-46","no":46,"unit":"데이터베이스 구축","q":"개체-관계 모델의 E-R 다이어그램에 쓰이는 기호와 그 의미가 잘못 연결된 것은?","choices":["사각형 - 개체 타입","마름모 - 관계 타입","선 - 개체 타입과 속성을 서로 연결","삼각형 - 속성"],"ans":4,"exp":{"concept":"E-R 다이어그램은 개체와 그 관계를 도형으로 그린 그림이다. 사각형은 개체 타입, 마름모는 관계 타입, 타원은 속성, 선은 개체와 속성 또는 개체와 관계를 연결한다. 삼각형은 E-R 다이어그램의 기본 기호가 아니다.","choices":[{"verdict":"오답","why":"사각형은 개체 타입(Entity Type)을 나타낸다. 옳은 연결이다."},{"verdict":"오답","why":"마름모는 관계 타입(Relationship Type)을 나타낸다. 옳은 연결이다."},{"verdict":"오답","why":"선은 개체 타입과 속성을 연결하거나 개체와 관계를 연결한다. 옳은 연결이다."},{"verdict":"정답","why":"속성은 타원으로 나타낸다. 삼각형은 E-R 다이어그램의 기본 기호가 아니므로 잘못된 연결이다."}],"keywords":[{"term":"사각형","desc":"개체 타입"},{"term":"마름모","desc":"관계 타입"},{"term":"타원","desc":"속성"},{"term":"밑줄 타원","desc":"기본키 속성"},{"term":"이중 타원","desc":"다중값 속성"}],"memo":"E-R 기호는 '사각 개체, 마름 관계, 타원 속성'. 삼각형은 없다."}},{"id":"written-2025-2-47","no":47,"unit":"데이터베이스 구축","q":"Commit 명령어와 Rollback 명령어를 통해 보장되는 트랜잭션의 특성은?","choices":["원자성","병행성","보안성","로그"],"ans":1,"exp":{"concept":"트랜잭션은 데이터베이스에서 한 번에 처리되어야 하는 작업 묶음이다. 원자성(Atomicity)은 트랜잭션의 연산이 모두 반영되거나(Commit) 하나도 반영되지 않아야(Rollback) 한다는 성질이다. 계좌 이체에서 출금만 되고 입금이 안 되는 일이 없게 해 주는 것이 원자성이다.","choices":[{"verdict":"정답","why":"Commit은 모든 연산을 반영하고 Rollback은 모든 연산을 취소하므로, '전부 아니면 전무'인 원자성을 보장한다."},{"verdict":"오답","why":"병행성은 여러 트랜잭션을 동시에 수행하는 성질로, 트랜잭션의 ACID 특성이 아니다."},{"verdict":"오답","why":"보안성은 트랜잭션의 ACID 특성이 아니다."},{"verdict":"오답","why":"로그는 회복을 위한 기록 파일이지 트랜잭션의 특성이 아니다."}],"keywords":[{"term":"원자성(Atomicity)","desc":"트랜잭션 연산이 모두 반영되거나 전혀 반영되지 않아야 함, Commit·Rollback으로 보장"},{"term":"일관성(Consistency)","desc":"트랜잭션 실행 후에도 데이터베이스가 일관된 상태를 유지"},{"term":"독립성(Isolation)","desc":"실행 중인 트랜잭션에 다른 트랜잭션이 끼어들 수 없음"},{"term":"지속성(Durability)","desc":"완료된 트랜잭션의 결과는 영구히 반영됨"}],"memo":"ACID(원자성·일관성·독립성·지속성). Commit/Rollback은 '전부 또는 전무'인 원자성과 짝지어 외운다."}},{"id":"written-2025-2-48","no":48,"unit":"데이터베이스 구축","q":"department 테이블에 대한 검색 연산을 사용자 X1로부터 회수하는 명령은?","choices":["revoke select on department from X1;","remove select on department from X1;","grant select on department from X1;","delete select on department to X1;"],"ans":1,"exp":{"concept":"DCL(데이터 제어어)의 GRANT는 권한을 주고, REVOKE는 준 권한을 회수한다. 형식은 'GRANT 권한 ON 테이블 TO 사용자;', 'REVOKE 권한 ON 테이블 FROM 사용자;'이다. 줄 때는 TO(누구에게), 뺏을 때는 FROM(누구로부터)을 쓴다.","choices":[{"verdict":"정답","why":"REVOKE 권한 ON 테이블 FROM 사용자 형식에 맞는 올바른 회수 명령이다."},{"verdict":"오답","why":"REMOVE는 SQL의 권한 회수 명령어가 아니다."},{"verdict":"오답","why":"GRANT는 권한을 부여하는 명령이고, 부여할 때는 FROM이 아니라 TO를 쓴다."},{"verdict":"오답","why":"DELETE는 테이블의 튜플을 삭제하는 DML 명령으로, 권한 회수에 쓰지 않는다."}],"keywords":[{"term":"GRANT","desc":"권한 부여: GRANT 권한 ON 테이블 TO 사용자"},{"term":"REVOKE","desc":"권한 회수: REVOKE 권한 ON 테이블 FROM 사용자"},{"term":"WITH GRANT OPTION","desc":"받은 권한을 다른 사용자에게 다시 부여할 수 있게 함"},{"term":"CASCADE","desc":"REVOKE 시 연쇄적으로 부여된 권한까지 함께 회수"}],"memo":"GRANT ... TO, REVOKE ... FROM. 주는 건 '에게(TO)', 뺏는 건 '로부터(FROM)'."}},{"id":"written-2025-2-49","no":49,"unit":"데이터베이스 구축","q":"CREATE TABLE문에서 지원하지 않는 기능은 무엇인가?","choices":["CHECK 제약조건 정의","기본키를 구성하는 속성의 지정","속성에 대한 NOT NULL 여부 지정","속성 타입 변경"],"ans":4,"exp":{"concept":"CREATE TABLE은 새 테이블을 만들면서 속성 이름과 타입, NOT NULL, 기본키, 외래키, CHECK 같은 제약조건을 정의하는 DDL 명령이다. 이미 만든 테이블의 속성 타입을 바꾸는 것은 테이블 구조를 변경하는 ALTER TABLE의 역할이다.","choices":[{"verdict":"오답","why":"CREATE TABLE에서 CHECK 제약조건을 정의할 수 있다."},{"verdict":"오답","why":"CREATE TABLE에서 PRIMARY KEY로 기본키 속성을 지정할 수 있다."},{"verdict":"오답","why":"CREATE TABLE에서 속성마다 NOT NULL 여부를 지정할 수 있다."},{"verdict":"정답","why":"이미 정의된 속성의 타입을 바꾸는 것은 ALTER TABLE로 한다. CREATE TABLE은 새로 정의할 뿐 변경하지 않는다."}],"keywords":[{"term":"CREATE TABLE","desc":"테이블과 속성, 제약조건을 새로 정의"},{"term":"ALTER TABLE","desc":"기존 테이블의 속성 추가(ADD)·변경(ALTER/MODIFY)·삭제(DROP)"},{"term":"DROP TABLE","desc":"테이블을 삭제"},{"term":"CHECK","desc":"속성 값이 만족해야 할 조건을 지정하는 제약"}],"memo":"만들 때는 CREATE, 고칠 때는 ALTER. '변경'이 보이면 ALTER의 몫이다."}},{"id":"written-2025-2-50","no":50,"unit":"데이터베이스 구축","q":"다음 중 SQL의 논리 연산자에 해당하지 않는 것은?","choices":["OR","NOT","AND","OTHER"],"ans":4,"exp":{"concept":"SQL의 논리 연산자는 조건을 조합할 때 쓰는 NOT, AND, OR 세 가지다. 우선순위는 NOT → AND → OR 순이다. OTHER는 SQL 연산자가 아니다.","choices":[{"verdict":"오답","why":"OR는 조건 중 하나라도 참이면 참이 되는 논리 연산자다."},{"verdict":"오답","why":"NOT은 조건의 결과를 반대로 바꾸는 논리 연산자다."},{"verdict":"오답","why":"AND는 모든 조건이 참일 때만 참이 되는 논리 연산자다."},{"verdict":"정답","why":"OTHER는 SQL의 논리 연산자가 아니다."}],"keywords":[{"term":"NOT","desc":"조건의 참·거짓을 반대로 바꿈"},{"term":"AND","desc":"모든 조건이 참이어야 참"},{"term":"OR","desc":"하나의 조건만 참이어도 참"},{"term":"논리 연산자 우선순위","desc":"NOT → AND → OR"}],"memo":"SQL 논리 연산자는 NOT, AND, OR 세 개뿐이고 우선순위도 이 순서다."}},{"id":"written-2025-2-51","no":51,"unit":"데이터베이스 구축","q":"다음 중 병행제어 기법에 해당하지 않는 것은?","choices":["로킹 기법","타임 스탬프 기법","시분할 기법","다중 버전 기법"],"ans":3,"exp":{"concept":"병행 제어는 여러 트랜잭션이 동시에 실행될 때 서로 꼬이지 않고 데이터베이스의 일관성을 지키도록 실행 순서를 조절하는 것이다. 대표 기법은 로킹, 타임 스탬프 순서, 최적 병행 수행(검증·확인 기법), 다중 버전 기법이다. 시분할은 운영체제가 CPU 시간을 잘게 나눠 여러 사용자에게 돌아가며 주는 방식이다.","choices":[{"verdict":"오답","why":"로킹 기법은 데이터에 잠금을 걸어 다른 트랜잭션의 접근을 막는 병행 제어 기법이다."},{"verdict":"오답","why":"타임 스탬프 기법은 트랜잭션이 시작된 시간 순서로 실행 순서를 정하는 병행 제어 기법이다."},{"verdict":"정답","why":"시분할(Time Sharing)은 운영체제가 CPU 시간을 나누어 여러 사용자에게 번갈아 할당하는 방식으로, 데이터베이스 병행 제어 기법이 아니다."},{"verdict":"오답","why":"다중 버전 기법은 데이터의 여러 버전을 두고 트랜잭션의 타임스탬프에 맞는 버전을 읽게 하는 병행 제어 기법이다."}],"keywords":[{"term":"병행 제어","desc":"동시에 실행되는 트랜잭션이 일관성을 해치지 않도록 제어하는 것"},{"term":"로킹","desc":"데이터에 잠금을 걸어 접근을 통제"},{"term":"타임 스탬프 순서","desc":"트랜잭션 시작 시간 순으로 실행 순서를 정함"},{"term":"최적 병행 수행","desc":"트랜잭션을 먼저 실행하고 끝날 때 검증하는 기법"},{"term":"다중 버전 기법","desc":"여러 버전의 데이터를 두고 알맞은 버전을 읽게 하는 기법"}],"memo":"병행 제어 넷: 로킹, 타임 스탬프, 최적 병행 수행, 다중 버전. 시분할은 운영체제 용어다."}},{"id":"written-2025-2-52","no":52,"unit":"데이터베이스 구축","q":"관계대수에 관한 설명 중 틀린 것은?","choices":["원하는 릴레이션을 정의하는 방법을 제공하는 비절차적 언어이다.","일반 집합 연산과 순수 관계 연산으로 나뉜다.","릴레이션을 조작하기 위한 연산의 집합이며, 피연산자와 결과가 모두 릴레이션이다.","질의에 대한 해를 구하기 위해 수행해야 하는 연산의 순서를 명시한다."],"ans":1,"exp":{"concept":"관계대수는 원하는 결과를 얻기 위해 어떤 연산을 어떤 순서로 할지 적는 절차적 언어다. 반대로 관계해석은 원하는 결과가 무엇인지만 정의하는 비절차적 언어다. 관계대수는 요리 순서를 적은 레시피, 관계해석은 완성된 요리 사진을 보여 주는 주문서에 비유할 수 있다.","choices":[{"verdict":"정답","why":"원하는 릴레이션을 '정의'만 하는 비절차적 언어는 관계해석이다. 관계대수는 연산 순서를 명시하는 절차적 언어이므로 틀렸다."},{"verdict":"오답","why":"관계대수는 일반 집합 연산(합집합, 교집합, 차집합, 교차곱)과 순수 관계 연산(Select, Project, Join, Division)으로 나뉜다. 옳은 설명이다."},{"verdict":"오답","why":"관계대수는 릴레이션을 조작하는 연산의 집합이며, 피연산자와 결과가 모두 릴레이션이다. 옳은 설명이다."},{"verdict":"오답","why":"질의의 해를 구하기 위해 수행할 연산의 순서를 명시한다. 관계대수가 절차적 언어인 이유다."}],"keywords":[{"term":"관계대수","desc":"연산 순서를 명시하는 절차적 언어"},{"term":"관계해석","desc":"원하는 정보가 무엇인지만 정의하는 비절차적 언어"},{"term":"순수 관계 연산자","desc":"Select(σ), Project(π), Join(⋈), Division(÷)"},{"term":"일반 집합 연산자","desc":"합집합(∪), 교집합(∩), 차집합(−), 교차곱(×)"}],"memo":"대수는 '절차(어떻게)', 해석은 '비절차(무엇을)'. 둘을 바꿔 쓴 보기가 단골이다."}},{"id":"written-2025-2-53","no":53,"unit":"데이터베이스 구축","q":"3NF에서 BCNF로 되기 위한 조건은 무엇인가?","choices":["이행적 함수 종속 제거","다치 종속 제거","결정자이면서 후보키가 아닌 것을 제거","부분적 함수 종속 제거"],"ans":3,"exp":{"concept":"정규화는 이상 현상을 없애기 위해 릴레이션을 단계적으로 쪼개는 과정이다. 1NF → 2NF는 부분 함수 종속 제거, 2NF → 3NF는 이행 함수 종속 제거, 3NF → BCNF는 결정자이면서 후보키가 아닌 것을 제거, BCNF → 4NF는 다치 종속 제거, 4NF → 5NF는 조인 종속 제거다. BCNF는 '모든 결정자가 후보키'인 상태다.","choices":[{"verdict":"오답","why":"이행적 함수 종속 제거는 2NF에서 3NF로 가는 조건이다."},{"verdict":"오답","why":"다치(다중값) 종속 제거는 BCNF에서 4NF로 가는 조건이다."},{"verdict":"정답","why":"결정자이면서 후보키가 아닌 것을 제거하면 모든 결정자가 후보키가 되어 BCNF가 된다. 옳은 조건이다."},{"verdict":"오답","why":"부분적 함수 종속 제거는 1NF에서 2NF로 가는 조건이다."}],"keywords":[{"term":"2NF","desc":"1NF에서 부분 함수 종속을 제거"},{"term":"3NF","desc":"2NF에서 이행 함수 종속을 제거"},{"term":"BCNF","desc":"3NF에서 결정자이면서 후보키가 아닌 것을 제거, 모든 결정자가 후보키"},{"term":"4NF","desc":"BCNF에서 다치 종속을 제거"},{"term":"5NF","desc":"4NF에서 조인 종속을 제거"}],"memo":"'도부이결다조'(도메인 원자값 → 부분 → 이행 → 결정자 → 다치 → 조인) 순서로 외운다."}},{"id":"written-2025-2-54","no":54,"unit":"데이터베이스 구축","q":"분산 데이터베이스 시스템(Distributed Database System)에 관한 설명 중 틀린 것은?","choices":["분산 데이터베이스 시스템의 주요 구성 요소로는 분산 처리기, P2P 시스템, 단일 데이터베이스 등이 있다.","분산 데이터베이스는 논리적으로는 하나의 시스템에 속하지만, 물리적으로는 여러 개의 컴퓨터 사이트에 분산되어 있다.","데이터베이스 설계가 비교적 어렵고, 개발 비용과 처리 비용이 늘어난다는 단점이 있다.","위치 투명성, 중복 투명성, 병행 투명성, 장애 투명성을 목표로 삼는다."],"ans":1,"exp":{"concept":"분산 데이터베이스는 논리적으로는 하나의 데이터베이스지만 물리적으로는 네트워크로 연결된 여러 사이트에 나뉘어 저장된 데이터베이스다. 구성 요소는 분산 처리기, 분산 데이터베이스, 통신 네트워크다. 사용자가 분산 사실을 의식하지 않게 위치, 중복, 병행, 장애 투명성을 목표로 한다.","choices":[{"verdict":"정답","why":"분산 데이터베이스 시스템의 구성 요소는 분산 처리기, 분산 데이터베이스, 통신 네트워크다. P2P 시스템과 단일 데이터베이스는 구성 요소가 아니며, 특히 '단일' 데이터베이스는 분산이라는 개념과 맞지 않는다."},{"verdict":"오답","why":"논리적으로는 하나의 시스템이지만 물리적으로는 여러 사이트에 분산되어 있다. 옳은 설명이다."},{"verdict":"오답","why":"설계가 어렵고 개발 비용과 처리 비용이 늘어나는 것은 분산 데이터베이스의 단점이다. 옳은 설명이다."},{"verdict":"오답","why":"위치, 중복, 병행, 장애 투명성은 분산 데이터베이스의 목표다. 옳은 설명이다."}],"keywords":[{"term":"분산 데이터베이스 구성 요소","desc":"분산 처리기, 분산 데이터베이스, 통신 네트워크"},{"term":"위치 투명성","desc":"데이터의 물리적 위치를 몰라도 접근 가능"},{"term":"중복(복제) 투명성","desc":"데이터가 여러 곳에 중복되어 있어도 하나처럼 사용"},{"term":"병행 투명성","desc":"여러 트랜잭션이 동시에 실행돼도 결과가 이상 없음"},{"term":"장애 투명성","desc":"일부 장애가 생겨도 트랜잭션을 정확히 처리"}],"memo":"분산 DB 구성 요소는 '처리기, 데이터베이스, 네트워크'. 투명성은 '위치·중복·병행·장애'."}},{"id":"written-2025-2-55","no":55,"unit":"데이터베이스 구축","q":"SQL문에서 HAVING을 사용할 수 있는 절은 무엇인가?","choices":["ORDER BY 절","GROUP BY 절","LIKE 절","WHERE 절"],"ans":2,"exp":{"concept":"HAVING은 GROUP BY로 묶은 그룹에 조건을 걸 때 쓰는 절이다. WHERE가 개별 행을 거른다면, HAVING은 그룹으로 묶은 뒤 그룹 단위로 거른다. 예를 들어 'GROUP BY 학과 HAVING COUNT(*) >= 3'은 학생이 3명 이상인 학과만 남긴다.","choices":[{"verdict":"오답","why":"ORDER BY는 결과를 정렬하는 절로, HAVING과 함께 쓰는 절이 아니다."},{"verdict":"정답","why":"HAVING은 GROUP BY 절로 그룹을 만든 뒤 그 그룹에 조건을 지정할 때 사용한다. 옳다."},{"verdict":"오답","why":"LIKE는 문자 패턴을 비교하는 연산자로, 절이 아니다."},{"verdict":"오답","why":"WHERE는 그룹으로 묶기 전 개별 행의 조건을 지정하는 절이며, 그룹 조건은 HAVING에 쓴다."}],"keywords":[{"term":"GROUP BY","desc":"지정한 속성 값이 같은 행끼리 그룹으로 묶음"},{"term":"HAVING","desc":"GROUP BY로 묶은 그룹에 조건을 지정"},{"term":"WHERE","desc":"그룹화 전에 개별 행의 조건을 지정"},{"term":"ORDER BY","desc":"결과를 정렬, ASC 오름차순·DESC 내림차순"}],"memo":"그룹 조건은 HAVING, 행 조건은 WHERE. HAVING은 GROUP BY의 짝꿍이다."}},{"id":"written-2025-2-56","no":56,"unit":"데이터베이스 구축","q":"다음 중 데이터 제어 언어(DCL)의 기능에 해당하지 않는 것은?","choices":["무결성 유지","논리적, 물리적 데이터 구조 정의","병행수행 제어","데이터 보안"],"ans":2,"exp":{"concept":"데이터베이스 언어는 정의어(DDL), 조작어(DML), 제어어(DCL)로 나뉜다. 제어어(DCL)는 데이터를 정확하고 안전하게 지키기 위한 언어로, 무결성 유지, 보안, 병행 수행 제어, 회복 기능을 맡는다. 데이터 구조를 정의하는 것은 정의어(DDL)의 기능이다.","choices":[{"verdict":"오답","why":"데이터의 정확성을 지키는 무결성 유지는 DCL의 기능이다."},{"verdict":"정답","why":"논리적·물리적 데이터 구조를 정의하는 것은 데이터 정의어(DDL)의 기능이므로 DCL의 기능이 아니다."},{"verdict":"오답","why":"여러 사용자가 동시에 접근할 때의 병행 수행 제어는 DCL의 기능이다."},{"verdict":"오답","why":"불법적인 사용자로부터 데이터를 보호하는 보안은 DCL의 기능이다."}],"keywords":[{"term":"DDL(데이터 정의어)","desc":"데이터 구조를 정의·변경·삭제: CREATE, ALTER, DROP"},{"term":"DML(데이터 조작어)","desc":"데이터 검색·삽입·삭제·갱신: SELECT, INSERT, DELETE, UPDATE"},{"term":"DCL(데이터 제어어)","desc":"무결성, 보안, 병행 제어, 회복: GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"DCL은 '지키는' 언어(무결성·보안·병행 제어·회복), DDL은 '만드는' 언어(구조 정의)."}},{"id":"written-2025-2-57","no":57,"unit":"데이터베이스 구축","q":"SQL 명령어의 분류에서 DDL에 속하지 않는 것은?","choices":["DROP","CREATE","UPDATE","ALTER"],"ans":3,"exp":{"concept":"SQL 명령어는 DDL, DML, DCL로 분류한다. DDL(데이터 정의어)은 테이블 같은 구조를 다루는 CREATE, ALTER, DROP이다. UPDATE는 테이블에 들어 있는 데이터 값을 바꾸는 명령이므로 DML(데이터 조작어)이다.","choices":[{"verdict":"오답","why":"DROP은 스키마, 테이블, 뷰 등을 삭제하는 DDL 명령이다."},{"verdict":"오답","why":"CREATE는 스키마, 테이블, 뷰 등을 정의하는 DDL 명령이다."},{"verdict":"정답","why":"UPDATE는 테이블의 튜플 값을 변경하는 DML 명령이므로 DDL에 속하지 않는다."},{"verdict":"오답","why":"ALTER는 테이블 정의를 변경하는 DDL 명령이다."}],"keywords":[{"term":"DDL","desc":"CREATE, ALTER, DROP"},{"term":"DML","desc":"SELECT, INSERT, DELETE, UPDATE"},{"term":"DCL","desc":"GRANT, REVOKE, COMMIT, ROLLBACK"}],"memo":"구조를 바꾸면 ALTER(DDL), 값을 바꾸면 UPDATE(DML). 둘 다 '변경'이라 헷갈리기 쉽다."}},{"id":"written-2025-2-58","no":58,"unit":"데이터베이스 구축","q":"다음 릴레이션의 카디널리티와 차수를 옳게 나타낸 것은?<div class=\"q-spec\"><span class=\"q-spec__label\">보기</span><table class=\"q-tbl is-data\"><thead><tr><th>아이디</th><th>성명</th><th>나이</th><th>등급</th><th>적립금</th><th>가입년도</th></tr></thead><tbody><tr><td>yuyu01</td><td>원유철</td><td>36</td><td>3</td><td>2000</td><td>2008</td></tr><tr><td>sykim10</td><td>김성일</td><td>29</td><td>2</td><td>3300</td><td>2014</td></tr><tr><td>kshan4</td><td>한경선</td><td>45</td><td>3</td><td>2800</td><td>2009</td></tr><tr><td>namsu52</td><td>이남수</td><td>33</td><td>5</td><td>1000</td><td>2016</td></tr></tbody></table></div>","choices":["카디널리티 : 4, 차수 : 4","카디널리티 : 4, 차수 : 6","카디널리티 : 6, 차수 : 4","카디널리티 : 6, 차수 : 6"],"ans":2,"exp":{"concept":"릴레이션(테이블)에서 카디널리티(Cardinality)는 튜플(행)의 개수이고, 차수(Degree)는 속성(열)의 개수다. 표에는 아이디, 성명, 나이, 등급, 적립금, 가입년도 6개의 속성이 있고, yuyu01, sykim10, kshan4, namsu52 4개의 튜플이 있다. 따라서 카디널리티는 4, 차수는 6이다.","choices":[{"verdict":"오답","why":"튜플은 4개지만 속성은 6개이므로 차수 4는 틀렸다."},{"verdict":"정답","why":"튜플 4개로 카디널리티 4, 속성 6개로 차수 6이다. 옳다."},{"verdict":"오답","why":"카디널리티와 차수를 서로 바꾼 값이다."},{"verdict":"오답","why":"튜플은 4개이므로 카디널리티 6은 틀렸다."}],"keywords":[{"term":"카디널리티(Cardinality)","desc":"릴레이션의 튜플(행) 수"},{"term":"차수(Degree)","desc":"릴레이션의 속성(열) 수"},{"term":"튜플(Tuple)","desc":"릴레이션의 각 행"},{"term":"속성(Attribute)","desc":"릴레이션의 각 열, 데이터의 가장 작은 논리적 단위"}],"memo":"카디널리티는 '카드 장수'처럼 행(튜플) 개수, 차수는 열(속성) 개수."}},{"id":"written-2025-2-59","no":59,"unit":"데이터베이스 구축","q":"다음 SQL 문의 ( ) 안에 들어갈 내용으로 알맞은 것은?<pre class=\"q-sql\"><code class=\"language-sql\">UPDATE 인사급여 (   ) 호봉 = 15\nWHERE 성명 = '홍길동';</code></pre>","choices":["FROM","INTO","IN","SET"],"ans":4,"exp":{"concept":"UPDATE 문은 테이블의 데이터 값을 바꾸는 DML 명령으로, 형식은 'UPDATE 테이블명 SET 속성명 = 값 WHERE 조건;'이다. SET 뒤에 바꿀 속성과 새 값을, WHERE 뒤에 바꿀 행의 조건을 쓴다. 문제의 문장은 인사급여 테이블에서 성명이 '홍길동'인 행의 호봉을 15로 바꾼다.","choices":[{"verdict":"오답","why":"FROM은 SELECT나 DELETE에서 대상 테이블을 지정할 때 쓴다."},{"verdict":"오답","why":"INTO는 INSERT INTO처럼 삽입할 테이블을 지정할 때 쓴다."},{"verdict":"오답","why":"IN은 WHERE 절에서 값이 목록에 포함되는지 비교하는 연산자다."},{"verdict":"정답","why":"UPDATE 테이블명 SET 속성명 = 값 형식이므로 빈칸에는 SET이 들어간다."}],"keywords":[{"term":"UPDATE","desc":"UPDATE 테이블 SET 속성 = 값 WHERE 조건"},{"term":"INSERT","desc":"INSERT INTO 테이블(속성) VALUES (값)"},{"term":"DELETE","desc":"DELETE FROM 테이블 WHERE 조건"}],"memo":"UPDATE-SET, INSERT-INTO-VALUES, DELETE-FROM으로 짝을 외운다."}},{"id":"written-2025-2-60","no":60,"unit":"데이터베이스 구축","q":"어떤 릴레이션 스키마가 속성 4개와 후보키 2개를 가지며, 해당 스키마에 대응하는 릴레이션 인스턴스가 튜플 7개를 갖는다고 할 때, 이 릴레이션의 차수(Degree)는?","choices":["1","2","4","7"],"ans":3,"exp":{"concept":"릴레이션의 차수(Degree)는 속성의 개수다. 문제에서 속성이 4개이므로 차수는 4다. 후보키 2개는 키의 개수일 뿐이고, 튜플 7개는 카디널리티이므로 차수와 관계없다.","choices":[{"verdict":"오답","why":"1은 문제의 어떤 수와도 맞지 않는다. 차수는 속성 수인 4다."},{"verdict":"오답","why":"2는 후보키의 개수다. 후보키 수는 차수와 관계없다."},{"verdict":"정답","why":"속성이 4개이므로 차수는 4다. 옳다."},{"verdict":"오답","why":"7은 튜플의 개수, 즉 카디널리티다."}],"keywords":[{"term":"차수(Degree)","desc":"속성(열)의 개수"},{"term":"카디널리티(Cardinality)","desc":"튜플(행)의 개수"},{"term":"후보키(Candidate Key)","desc":"튜플을 유일하게 식별할 수 있는 최소한의 속성 집합"}],"memo":"차수는 속성, 카디널리티는 튜플. 후보키 개수는 섞어 놓은 미끼다."}},{"id":"written-2025-2-61","no":61,"unit":"프로그래밍 언어 활용","q":"어떤 모듈이 다른 모듈의 내부 기능과 그 내부 자료를 직접 참조할 때의 결합도는?","choices":["공통 결합도(Common Coupling)","내용 결합도(Content Coupling)","제어 결합도(Control Coupling)","스탬프 결합도(Stamp Coupling)"],"ans":2,"exp":{"concept":"결합도는 모듈끼리 얼마나 얽혀 있는지를 나타내며, 약한 순서대로 자료 < 스탬프 < 제어 < 외부 < 공통 < 내용 결합도다. 내용 결합도는 한 모듈이 다른 모듈의 내부 기능과 내부 자료를 직접 참조하거나 수정하는 가장 강한 결합이다. 남의 집에 허락 없이 들어가 물건을 쓰는 것과 같아서 가장 나쁜 결합이다.","choices":[{"verdict":"오답","why":"공통 결합도는 여러 모듈이 공유하는 공통 데이터 영역(전역 변수 등)을 함께 참조하는 결합이다."},{"verdict":"정답","why":"내용 결합도는 한 모듈이 다른 모듈의 내부 기능과 내부 자료를 직접 참조하는 결합이다. 문제의 설명과 일치한다."},{"verdict":"오답","why":"제어 결합도는 한 모듈이 다른 모듈의 처리 흐름을 바꾸려고 제어 신호(플래그 등)를 넘기는 결합이다."},{"verdict":"오답","why":"스탬프 결합도는 배열이나 레코드 같은 자료 구조를 통째로 넘기는 결합이다."}],"keywords":[{"term":"자료 결합도","desc":"필요한 데이터 값만 인수로 주고받음, 가장 약한 결합"},{"term":"스탬프 결합도","desc":"배열·레코드 같은 자료 구조를 통째로 전달"},{"term":"제어 결합도","desc":"처리 흐름을 바꾸는 제어 신호를 전달"},{"term":"공통 결합도","desc":"공유 데이터 영역(전역 변수)을 함께 참조"},{"term":"내용 결합도","desc":"다른 모듈의 내부 기능·자료를 직접 참조, 가장 강한 결합"}],"memo":"결합도 약 → 강 순서는 '자스제외공내'(자료, 스탬프, 제어, 외부, 공통, 내용)."}},{"id":"written-2025-2-62","no":62,"unit":"프로그래밍 언어 활용","q":"다음 중 시간 구역성(Temporal Locality)과 관련이 가장 적은 것은?","choices":["스택","배열 순회","루프","서브루틴"],"ans":2,"exp":{"concept":"구역성(Locality)은 프로그램이 실행 중에 일부 영역만 집중적으로 참조하는 성질이다. 시간 구역성은 방금 참조한 곳을 곧 다시 참조하는 성질로 반복문(루프), 스택, 서브루틴, 카운팅·집계 변수가 예다. 공간 구역성은 참조한 곳의 근처를 이어서 참조하는 성질로 배열 순회, 순차적 코드 실행이 예다.","choices":[{"verdict":"오답","why":"스택은 가장 위(top) 부분을 반복해 참조하므로 시간 구역성의 예다."},{"verdict":"정답","why":"배열 순회는 메모리에 연속으로 놓인 원소를 차례로 참조하므로 공간 구역성의 예다. 시간 구역성과 관련이 가장 적다."},{"verdict":"오답","why":"루프는 같은 명령과 변수를 반복해서 참조하므로 시간 구역성의 대표적인 예다."},{"verdict":"오답","why":"서브루틴은 같은 코드를 여러 번 호출해 실행하므로 시간 구역성의 예다."}],"keywords":[{"term":"구역성(Locality)","desc":"프로세스가 실행 중 일부 페이지를 집중적으로 참조하는 성질, 데닝(Denning)이 제시"},{"term":"시간 구역성","desc":"최근 참조한 곳을 가까운 시간 안에 다시 참조: 루프, 스택, 서브루틴, 카운팅·집계"},{"term":"공간 구역성","desc":"참조한 곳 근처를 이어서 참조: 배열 순회, 순차적 코드 실행"},{"term":"워킹 셋(Working Set)","desc":"프로세스가 일정 시간 동안 자주 참조하는 페이지들의 집합"}],"memo":"'같은 곳 다시'는 시간, '옆으로 쭉'은 공간. 배열 순회는 옆으로 쭉 가므로 공간 구역성이다."}},{"id":"written-2025-2-63","no":63,"unit":"프로그래밍 언어 활용","q":"리눅스에서 커널 버전을 확인하고자 할 때 사용하는 명령어는?","choices":["chmod","ls","uname","rm"],"ans":3,"exp":{"concept":"리눅스에서 uname 명령은 운영체제 이름, 커널 버전, 하드웨어 정보 등 시스템 정보를 출력한다. 커널 릴리스 버전만 보려면 'uname -r', 전체 정보를 보려면 'uname -a'를 쓴다.","choices":[{"verdict":"오답","why":"chmod는 파일의 접근 권한(읽기, 쓰기, 실행)을 변경하는 명령이다."},{"verdict":"오답","why":"ls는 현재 디렉터리의 파일 목록을 보여 주는 명령이다."},{"verdict":"정답","why":"uname은 커널 이름과 버전 등 시스템 정보를 출력하는 명령으로, 커널 버전 확인에 쓴다."},{"verdict":"오답","why":"rm은 파일을 삭제하는 명령이다."}],"keywords":[{"term":"uname","desc":"커널 이름·버전 등 시스템 정보 출력, -r 커널 릴리스, -a 전체 정보"},{"term":"chmod","desc":"파일의 접근 권한 변경"},{"term":"ls","desc":"디렉터리 안의 파일 목록 표시"},{"term":"rm","desc":"파일 삭제"}],"memo":"커널 버전은 uname -r, 전체 시스템 정보는 uname -a로 기억한다."}},{"id":"written-2025-2-64","no":64,"unit":"프로그래밍 언어 활용","q":"파일 디스크립터(File Descriptor)에 관한 설명 중 옳지 않은 것은?","choices":["파일 관리를 위해 시스템에서 필요로 하는 정보를 담고 있다.","사용자는 파일 디스크립터를 직접 참조할 수 없다.","주기억장치에 저장되어 있다가 파일이 개방(open)되면 보조기억장치로 옮겨진다.","파일 제어 블록(File Control Block)이라고 부르기도 한다."],"ans":3,"exp":{"concept":"파일 디스크립터(File Descriptor)는 운영체제가 파일을 관리하는 데 필요한 정보(파일 이름, 위치, 크기, 접근 권한 등)를 담은 자료 구조로, 파일 제어 블록(FCB)이라고도 한다. 평소에는 보조기억장치에 저장되어 있다가 파일을 열면(open) 주기억장치로 옮겨진다. 운영체제가 관리하므로 사용자가 직접 참조할 수 없다.","choices":[{"verdict":"오답","why":"파일 디스크립터는 파일 관리에 필요한 정보를 담고 있다. 옳은 설명이다."},{"verdict":"오답","why":"파일 디스크립터는 운영체제가 관리하며 사용자가 직접 참조할 수 없다. 옳은 설명이다."},{"verdict":"정답","why":"방향이 반대다. 파일 디스크립터는 보조기억장치에 저장되어 있다가 파일이 개방되면 주기억장치로 옮겨진다."},{"verdict":"오답","why":"파일 디스크립터는 파일 제어 블록(FCB, File Control Block)이라고도 한다. 옳은 설명이다."}],"keywords":[{"term":"파일 디스크립터","desc":"파일 관리에 필요한 정보를 담은 자료 구조"},{"term":"파일 제어 블록(FCB)","desc":"파일 디스크립터의 다른 이름"},{"term":"파일 개방(open)","desc":"보조기억장치의 파일 디스크립터를 주기억장치로 옮겨 사용 준비"}],"memo":"파일을 '열면' 정보가 일하는 곳(주기억장치)으로 올라온다. 보조 → 주 방향을 기억한다."}},{"id":"written-2025-2-65","no":65,"unit":"프로그래밍 언어 활용","q":"다음 C 언어로 작성된 프로그램을 실행했을 때의 출력 결과는?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nstruct st {\n    int a;\n    int c[10];\n};\nint main(int argc, char* argv[]) {\n    int i = 0;\n    struct st ob1;\n    struct st ob2;\n    ob1.a = 0;\n    ob2.a = 0;\n    for (i = 0; i &lt; 10; i++) {\n        ob1.c[i] = i;\n        ob2.c[i] = ob1.c[i] + i;\n    }\n    for (i = 0; i &lt; 10; i = i + 2) {\n        ob1.a = ob1.a + ob1.c[i];\n        ob2.a = ob2.a + ob2.c[i];\n    }\n    printf(\"%d\", ob1.a + ob2.a);\n    return 0;\n}</code></pre>","choices":["30","60","80","120"],"ans":2,"exp":{"concept":"구조체 st는 정수 a와 정수 배열 c[10]을 가진다. 첫 반복문에서 ob1.c[i] = i, ob2.c[i] = ob1.c[i] + i = 2i가 된다. 둘째 반복문은 i = 0, 2, 4, 6, 8 짝수 인덱스만 더하므로 ob1.a = 0+2+4+6+8 = 20, ob2.a = 0+4+8+12+16 = 40이다. 출력은 20 + 40 = 60이다.","choices":[{"verdict":"오답","why":"30은 출력되지 않는다. ob1.a는 20, ob2.a는 40이고 둘의 합은 60이다."},{"verdict":"정답","why":"ob1.a = 20, ob2.a = 40이므로 ob1.a + ob2.a = 60이 출력된다. 정답이다."},{"verdict":"오답","why":"80은 출력되지 않는다. ob2.c[i]는 2i이므로 짝수 인덱스 합 ob2.a는 40이다."},{"verdict":"오답","why":"120은 출력되지 않는다. 둘째 반복문은 i = i + 2로 짝수 인덱스 0, 2, 4, 6, 8만 더한다."}],"keywords":[{"term":"구조체(struct)","desc":"서로 다른 자료형의 변수를 하나로 묶은 사용자 정의 자료형"},{"term":"멤버 접근 연산자(.)","desc":"구조체 변수의 멤버에 접근, ob1.a처럼 사용"},{"term":"증감식 i = i + 2","desc":"반복할 때마다 2씩 증가해 짝수 인덱스만 방문"}],"memo":"반복문의 증감식(i = i + 2)을 먼저 확인한다. 짝수 인덱스만 더하는지 전부 더하는지가 갈림길이다."}},{"id":"written-2025-2-66","no":66,"unit":"프로그래밍 언어 활용","q":"UNIX에서 새 프로세스를 생성할 때 사용하는 시스템 호출은?","choices":["cat","chmod","ls","fork"],"ans":4,"exp":{"concept":"UNIX에서 fork() 시스템 호출은 현재 실행 중인 프로세스(부모)를 복제해 새 프로세스(자식)를 만든다. 세포 분열처럼 자기와 똑같은 프로세스를 하나 더 만드는 것이다. cat, chmod, ls는 셸에서 쓰는 명령어다.","choices":[{"verdict":"오답","why":"cat은 파일 내용을 화면에 출력하는 명령이다."},{"verdict":"오답","why":"chmod는 파일의 접근 권한을 변경하는 명령이다."},{"verdict":"오답","why":"ls는 디렉터리의 파일 목록을 보여 주는 명령이다."},{"verdict":"정답","why":"fork는 기존 프로세스를 복제해 새 프로세스를 생성하는 시스템 호출이다. 정답이다."}],"keywords":[{"term":"fork","desc":"현재 프로세스를 복제해 새 자식 프로세스를 생성"},{"term":"exec","desc":"현재 프로세스를 새 프로그램으로 바꾸어 실행"},{"term":"cat","desc":"파일 내용을 화면에 출력"},{"term":"chmod","desc":"파일 접근 권한 변경"}],"memo":"fork는 '포크처럼 갈라진다'. 프로세스가 둘로 갈라지는 시스템 호출이다."}},{"id":"written-2025-2-67","no":67,"unit":"프로그래밍 언어 활용","q":"아래 파이썬 코드에 ‘53t44’를 입력하면 출력되는 결과는?<pre class=\"qcode\"><code class=\"language-python\">a, b = map(int, input().split(\"t\"));\nprint(a, b)</code></pre>","choices":["53 t 44","53t44","53 44","53, 44"],"ans":3,"exp":{"concept":"input()은 키보드 입력을 문자열로 받는다. '53t44'.split(\"t\")는 문자 t를 기준으로 잘라 ['53', '44'] 리스트를 만들고, map(int, ...)로 각각 정수 53, 44로 바꾸어 a, b에 넣는다. print(a, b)는 여러 값을 기본 구분자인 공백으로 이어 출력하므로 '53 44'가 된다.","choices":[{"verdict":"오답","why":"split(\"t\")로 구분 문자 t는 제거되므로 출력에 t가 남지 않는다."},{"verdict":"오답","why":"입력 문자열을 그대로 출력하는 것이 아니라 나눈 두 정수를 출력한다."},{"verdict":"정답","why":"a = 53, b = 44를 print가 공백으로 구분해 출력하므로 53 44가 된다. 정답이다."},{"verdict":"오답","why":"print의 기본 구분자(sep)는 공백이므로 쉼표가 출력되지 않는다."}],"keywords":[{"term":"split(구분자)","desc":"문자열을 구분자 기준으로 나누어 리스트로 반환"},{"term":"map(함수, 반복 가능 객체)","desc":"각 요소에 함수를 적용, map(int, ...)은 모두 정수로 변환"},{"term":"print의 sep","desc":"여러 값을 출력할 때 사이에 넣는 구분자, 기본값은 공백"}],"memo":"print(a, b)는 공백으로 이어 출력한다. 쉼표는 코드에만 있고 출력에는 없다."}},{"id":"written-2025-2-68","no":68,"unit":"프로그래밍 언어 활용","q":"효과적인 모듈 설계를 위해 유의해야 할 사항과 거리가 먼 것은?","choices":["유지보수가 용이하도록 해야 한다.","모듈의 기능은 예측 가능해야 한다.","복잡도와 중복성을 줄이며 일관성을 유지시킨다.","모듈 간의 결합도를 강하게 할수록 모듈 독립성이 향상된다."],"ans":4,"exp":{"concept":"효과적인 모듈 설계의 핵심은 모듈 독립성을 높이는 것이다. 모듈 독립성은 결합도를 약하게, 응집도를 강하게 할수록 높아진다. 또한 유지보수가 쉬워야 하고, 기능은 예측 가능해야 하며, 복잡도와 중복성을 줄이고 일관성을 유지해야 한다.","choices":[{"verdict":"오답","why":"유지보수가 용이하도록 설계해야 한다는 것은 모듈 설계 유의사항이다."},{"verdict":"오답","why":"모듈의 기능은 예측 가능하도록 정의해야 한다는 것은 모듈 설계 유의사항이다."},{"verdict":"오답","why":"복잡도와 중복성을 줄이고 일관성을 유지하는 것은 모듈 설계 유의사항이다."},{"verdict":"정답","why":"결합도를 강하게 하면 모듈 간 의존이 커져 독립성이 떨어진다. 결합도는 약하게 해야 독립성이 향상된다."}],"keywords":[{"term":"모듈 독립성","desc":"결합도는 약하게, 응집도는 강하게 할수록 높아짐"},{"term":"결합도","desc":"모듈 간 의존 정도, 약할수록 좋음"},{"term":"응집도","desc":"모듈 내부 요소의 관련 정도, 강할수록 좋음"}],"memo":"결합은 '약하게', 응집은 '강하게'. 결합도가 강해야 좋다는 보기는 틀린 것이다."}},{"id":"written-2025-2-69","no":69,"unit":"프로그래밍 언어 활용","q":"C 언어 라이브러리 가운데 stdlib.h에 관한 설명으로 옳은 것은?","choices":["표준 입출력을 위한 라이브러리이다.","문자열 처리 함수인 strlen()이 포함되어 있다.","삼각 함수, 제곱근, 지수 등의 수학 함수를 내장하고 있다.","문자열을 수치 데이터로 변환하는 함수와 동적 메모리 할당 및 해제 함수 등을 포함한다."],"ans":4,"exp":{"concept":"C 언어는 기능별로 헤더 파일에 함수를 나누어 둔다. stdio.h는 표준 입출력(printf, scanf), string.h는 문자열 처리(strlen, strcpy, strcat), math.h는 수학 함수(sqrt, pow, sin), stdlib.h는 자료형 변환(atoi, atof), 동적 메모리 할당·해제(malloc, free), 난수(rand) 등 여러 유용한 함수를 담고 있다.","choices":[{"verdict":"오답","why":"표준 입출력 라이브러리는 stdio.h다."},{"verdict":"오답","why":"strlen()은 문자열 처리 함수로 string.h에 들어 있다."},{"verdict":"오답","why":"삼각 함수, 제곱근, 지수 같은 수학 함수는 math.h에 들어 있다."},{"verdict":"정답","why":"stdlib.h는 문자열을 수치로 바꾸는 atoi, atof와 동적 메모리 할당·해제 함수 malloc, free 등을 포함한다. 옳은 설명이다."}],"keywords":[{"term":"stdio.h","desc":"표준 입출력: printf, scanf, getchar"},{"term":"stdlib.h","desc":"자료형 변환·동적 메모리·난수: atoi, atof, malloc, free, rand"},{"term":"string.h","desc":"문자열 처리: strlen, strcpy, strcmp, strcat"},{"term":"math.h","desc":"수학 함수: sqrt, pow, sin, exp"}],"memo":"stdlib.h는 범용 함수 모음이다. 문자열을 숫자로 바꾸는 atoi와 malloc/free가 여기 있다는 점이 단골로 나온다."}},{"id":"written-2025-2-70","no":70,"unit":"프로그래밍 언어 활용","q":"128.107.176.0/22 네트워크에서 호스트가 사용할 수 있는 서브넷 마스크는?","choices":["255.0.0.0","255.248.0.0","255.255.252.0","255.255.255.255"],"ans":3,"exp":{"concept":"'/22'는 서브넷 마스크 32비트 중 앞의 22비트가 1이라는 뜻이다(CIDR 표기). 22비트를 8비트씩 나누면 8 + 8 + 6이므로 마스크는 11111111.11111111.11111100.00000000이다. 셋째 옥텟 11111100은 128+64+32+16+8+4 = 252이므로 서브넷 마스크는 255.255.252.0이다.","choices":[{"verdict":"오답","why":"255.0.0.0은 앞의 8비트만 1인 /8 마스크다."},{"verdict":"오답","why":"255.248.0.0은 앞의 13비트가 1인 /13 마스크다."},{"verdict":"정답","why":"/22는 앞 22비트가 1이므로 255.255.252.0이다. 정답이다."},{"verdict":"오답","why":"255.255.255.255는 32비트가 모두 1인 /32로, 호스트 부분이 없어 네트워크의 호스트용 마스크가 될 수 없다."}],"keywords":[{"term":"CIDR 표기","desc":"IP 주소 뒤에 /n으로 서브넷 마스크의 1인 비트 수를 표시"},{"term":"서브넷 마스크","desc":"IP 주소에서 네트워크 부분과 호스트 부분을 구분하는 32비트 값"},{"term":"/22","desc":"255.255.252.0, 호스트 비트 10개로 주소 1024개(사용 가능 호스트 1022개)"}],"memo":"옥텟 안 1의 개수별 값 128, 192, 224, 240, 248, 252, 254, 255를 외워 두면 바로 변환된다."}},{"id":"written-2025-2-71","no":71,"unit":"프로그래밍 언어 활용","q":"다음 중 스크립트(Script) 언어에 해당하지 않는 것은?","choices":["Python","PHP","Fortran","Basic"],"ans":3,"exp":{"concept":"스크립트 언어는 컴파일 없이 인터프리터가 소스를 바로 읽어 실행하는 언어로, 웹 페이지나 작업 자동화에 많이 쓰인다. 교재의 스크립트 언어로는 자바스크립트, VB스크립트, ASP, JSP, PHP, 파이썬, 쉘 스크립트, Basic 등이 있다. Fortran은 과학·기술 계산용으로 만들어진 대표적인 컴파일 언어다.","choices":[{"verdict":"오답","why":"Python은 인터프리터로 실행되는 대표적인 스크립트 언어다."},{"verdict":"오답","why":"PHP는 서버에서 동작하는 웹 스크립트 언어다."},{"verdict":"정답","why":"Fortran은 과학 기술 계산용으로 개발된 컴파일 언어로, 스크립트 언어가 아니다."},{"verdict":"오답","why":"Basic은 교재에서 스크립트 언어로 분류된다."}],"keywords":[{"term":"스크립트 언어","desc":"인터프리터로 바로 실행되는 언어, 서버용과 클라이언트용으로 나뉨"},{"term":"PHP","desc":"서버 측 웹 스크립트 언어"},{"term":"Fortran","desc":"과학 기술 계산용 고급 언어, 컴파일 방식"}],"memo":"Fortran은 FORmula TRANslation(수식 번역)의 줄임말로, 계산용 컴파일 언어다."}},{"id":"written-2025-2-72","no":72,"unit":"프로그래밍 언어 활용","q":"다음 자바 코드의 실행 결과로 옳은 것은?<pre class=\"qcode\"><code class=\"language-java\">int x=1, y=6;\nwhile (y--) {\n    x++;\n}\nSystem.out.println(\"x=\" x+ \"y=\" y);</code></pre>","choices":["x＝6 y＝-1","Unresolved compilation problem 오류가 발생한다","x＝7 y＝0","x＝7 y＝-1"],"ans":2,"exp":{"concept":"자바에서 while의 조건식은 반드시 boolean(true/false) 값이어야 한다. while (y--)에서 y--는 int 값이므로 'int를 boolean으로 바꿀 수 없다'는 컴파일 오류가 난다. 또 println(\"x=\" x+ \"y=\" y)도 문자열과 변수 사이에 + 연산자가 빠져 문법 오류다. 컴파일 오류가 있는 코드를 실행하면 이클립스 등에서는 'Unresolved compilation problem' 오류가 발생한다.","choices":[{"verdict":"오답","why":"x=6 y=-1은 실행 결과가 아니다. 이 코드는 컴파일 단계에서 오류가 나므로 아무 값도 출력되지 않는다."},{"verdict":"정답","why":"while 조건에 int 값(y--)을 쓰고 println 인수에 + 연산자가 빠져 컴파일 오류가 나므로, 실행하면 Unresolved compilation problem 오류가 발생한다. 정답이다."},{"verdict":"오답","why":"x=7 y=0도 출력되지 않는다. 코드가 컴파일되지 않기 때문이다."},{"verdict":"오답","why":"x=7 y=-1은 C 언어처럼 0이 아닌 값을 참으로 보고 6번 반복했을 때의 결과다. 자바는 정수를 조건으로 쓸 수 없어 이 값이 출력되지 않는다."}],"keywords":[{"term":"boolean 조건식","desc":"자바의 if, while 조건은 반드시 true/false인 boolean이어야 함"},{"term":"후위 감소 y--","desc":"현재 값을 먼저 사용한 뒤 1 감소"},{"term":"Unresolved compilation problem","desc":"컴파일 오류가 남은 코드를 실행할 때 이클립스에서 나타나는 오류 메시지"}],"memo":"C는 0이 아니면 참이지만 자바는 boolean만 조건이 된다. while(y--)는 C에서는 되고 자바에서는 오류."}},{"id":"written-2025-2-73","no":73,"unit":"프로그래밍 언어 활용","q":"IP 주소체계에 관한 설명 중 틀린 것은?","choices":["IPv6의 패킷 헤더는 32 octet의 고정 길이를 갖는다.","IPv6는 주소 자동설정(Auto Configuration) 기능을 이용해 이용자의 단말을 손쉽게 네트워크에 접속시킬 수 있다.","IPv4는 DHCP를 이용하여 호스트 주소를 자동으로 설정할 수 있고 유니캐스트(Unicast)를 지원한다.","IPv4는 클래스에 따라 네트워크와 호스트 주소의 길이가 다르다."],"ans":1,"exp":{"concept":"IPv4는 32비트 주소를 쓰고 A~E 클래스로 나누며, 헤더 길이는 옵션에 따라 20~60바이트로 바뀐다. IPv6는 128비트 주소를 쓰고, 기본 헤더는 40옥텟(40바이트) 고정 길이다. IPv6는 주소 자동 설정 기능이 있어 단말을 쉽게 네트워크에 연결할 수 있다.","choices":[{"verdict":"정답","why":"IPv6의 기본 패킷 헤더는 32옥텟이 아니라 40옥텟(40바이트) 고정 길이다."},{"verdict":"오답","why":"IPv6는 주소 자동 설정(Auto Configuration) 기능으로 단말을 손쉽게 네트워크에 접속시킨다. 옳은 설명이다."},{"verdict":"오답","why":"IPv4는 DHCP로 호스트 주소를 자동 설정할 수 있고 유니캐스트를 지원한다. 옳은 설명이다."},{"verdict":"오답","why":"IPv4는 A, B, C 클래스에 따라 네트워크 부분과 호스트 부분의 길이가 다르다. 옳은 설명이다."}],"keywords":[{"term":"IPv4","desc":"32비트 주소, 8비트씩 4부분 10진수 표기, 헤더 20~60바이트"},{"term":"IPv6","desc":"128비트 주소, 16비트씩 8부분 16진수 표기, 기본 헤더 40바이트 고정"},{"term":"IPv6 주소 유형","desc":"유니캐스트, 멀티캐스트, 애니캐스트(브로드캐스트 없음)"},{"term":"DHCP","desc":"호스트에 IP 주소를 자동으로 할당하는 프로토콜"}],"memo":"IPv6 헤더는 40바이트 고정. 주소 길이 128비트, IPv4 주소 32비트와 숫자를 섞지 않는다."}},{"id":"written-2025-2-74","no":74,"unit":"프로그래밍 언어 활용","q":"다음 C 언어 프로그램을 실행했을 때 출력되는 결과는?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nint main(void) {\n    int n = 4;\n    int* pt = NULL;\n    pt = &amp;n;\n    printf(\"%d\", &amp;n + *pt - *&amp;pt + n);\n    return 0;\n}</code></pre>","choices":["0","4","8","12"],"ans":3,"exp":{"concept":"pt = &n이므로 pt는 n의 주소를 가리키고 *pt는 n의 값 4다. *&pt는 '&pt가 가리키는 값'이므로 pt 자신, 즉 &n과 같다. 식은 왼쪽부터 (&n + 4) - &n + 4로 계산된다. 포인터에 4를 더하면 int 4칸 뒤의 주소가 되고, 같은 배열 기준의 두 포인터를 빼면 주소 차이가 아니라 '원소 칸 수' 4가 나온다. 따라서 4 + 4 = 8이 출력된다.","choices":[{"verdict":"오답","why":"0은 출력되지 않는다. (&n + 4) - pt는 4이고 여기에 n(4)을 더하므로 0이 될 수 없다."},{"verdict":"오답","why":"4는 마지막 + n을 빠뜨렸을 때의 값이다."},{"verdict":"정답","why":"(&n + 4) - pt는 칸 수 차이 4이고 여기에 n(4)을 더해 8이 출력된다. 정답이다."},{"verdict":"오답","why":"12는 출력되지 않는다. *&pt는 정수 4가 아니라 포인터 pt(=&n)이므로 &n과 상쇄되어 칸 수 차이 4만 남는다."}],"keywords":[{"term":"&(주소 연산자)","desc":"변수의 메모리 주소를 구함"},{"term":"*(간접 참조 연산자)","desc":"포인터가 가리키는 곳의 값을 구함"},{"term":"*&pt","desc":"&와 *가 서로 상쇄되어 pt 자신과 같음"},{"term":"포인터 뺄셈","desc":"두 포인터의 차는 바이트 수가 아니라 가리키는 자료형의 칸 수"}],"memo":"*&는 서로 지워진다. 포인터 + 정수는 '칸 이동', 포인터 - 포인터는 '칸 수'."}},{"id":"written-2025-2-75","no":75,"unit":"프로그래밍 언어 활용","q":"C 언어의 연산자 중에서 우선 순위가 가장 높은 것은 다음 중 어느 것인가?","choices":["산술 연산자","관계 연산자","비트 연산자","시프트 연산자"],"ans":1,"exp":{"concept":"C 언어 연산자 우선순위는 단항 연산자 → 산술 연산자(*, /, % 다음 +, -) → 시프트 연산자(<<, >>) → 관계 연산자(<, >, ==, !=) → 비트 연산자(&, ^, |) → 논리 연산자(&&, ||) → 조건 연산자 → 대입 연산자 → 순서 연산자(,) 순이다. 보기 중에서는 산술 연산자가 가장 높다.","choices":[{"verdict":"정답","why":"산술 연산자는 보기 중 우선순위가 가장 높다. 단항 연산자 바로 다음이다."},{"verdict":"오답","why":"관계 연산자는 산술·시프트 연산자보다 우선순위가 낮다."},{"verdict":"오답","why":"비트 연산자(&, ^, |)는 관계 연산자보다도 우선순위가 낮다."},{"verdict":"오답","why":"시프트 연산자는 산술 연산자 바로 다음 순위로, 산술 연산자보다 낮다."}],"keywords":[{"term":"단항 연산자","desc":"!, ~, ++, --, sizeof 등, 우선순위 가장 높음"},{"term":"산술 연산자","desc":"*, /, % 다음 +, -"},{"term":"시프트 연산자","desc":"<<, >>"},{"term":"관계 연산자","desc":"<, <=, >, >=, ==, !="},{"term":"비트 연산자","desc":"&, ^, | 순"}],"memo":"'단산시관비논조대순'(단항, 산술, 시프트, 관계, 비트, 논리, 조건, 대입, 순서)으로 외운다."}},{"id":"written-2025-2-76","no":76,"unit":"프로그래밍 언어 활용","q":"다음 C 언어 프로그램을 실행했을 때의 실행 결과는?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\nint main(int argc, char* argv[]) {\n    char str1[20] = \"KOREA\";\n    char str2[20] = \"LOVE\";\n    char* p1 = NULL;\n    char* p2 = NULL;\n    p1 = str1;\n    p2 = str2;\n    str1[1] = p2[2];\n    str2[3] = p1[4];\n    strcat(str1, str2);\n    printf(\"%c\", *(p1 + 2));\n    return 0;\n}</code></pre>","choices":["V","E","O","R"],"ans":4,"exp":{"concept":"p1은 str1, p2는 str2의 첫 칸을 가리킨다. str1[1] = p2[2]는 \"LOVE\"의 2번 칸 'V'를 str1의 1번 칸에 넣어 str1이 \"KVREA\"가 된다. str2[3] = p1[4]는 \"KVREA\"의 4번 칸 'A'를 str2의 3번 칸에 넣어 str2가 \"LOVA\"가 된다. strcat(str1, str2)로 str1은 \"KVREALOVA\"가 되고, *(p1 + 2)는 str1[2]인 'R'이다.","choices":[{"verdict":"오답","why":"V는 str1[1]의 값이다. 출력하는 것은 str1[2]다."},{"verdict":"오답","why":"E는 원래 str2[3]에 있던 문자인데 'A'로 바뀌었고, 출력 위치인 str1[2]와도 관계없다."},{"verdict":"오답","why":"O는 str2[1]의 문자로, str1[2]가 아니다."},{"verdict":"정답","why":"최종 str1은 \"KVREALOVA\"이고 *(p1 + 2)는 인덱스 2의 'R'이다. 정답이다."}],"keywords":[{"term":"배열 인덱스","desc":"C 배열은 0번부터 시작, str[2]는 세 번째 문자"},{"term":"*(p + i)","desc":"포인터 p에서 i칸 뒤의 값, p[i]와 같음"},{"term":"strcat(a, b)","desc":"문자열 a 뒤에 b를 이어 붙임, string.h에 선언"}],"memo":"인덱스는 0부터 센다. 대입이 일어날 때마다 문자열을 다시 적어 두면 실수가 줄어든다."}},{"id":"written-2025-2-77","no":77,"unit":"프로그래밍 언어 활용","q":"다음 C언어 프로그램을 실행했을 때 출력되는 결과는?<pre class=\"qcode\"><code class=\"language-c\">#include &lt;stdio.h&gt;\nmain() {\n    char* s = \"Sinagong\";\n    for (int i = 5; i &gt; 0; i--)\n        printf(\"%c\", *(s + i));\n}</code></pre>","choices":["gnoganis","sinagong","inago","ogani"],"ans":4,"exp":{"concept":"s는 문자열 \"Sinagong\"의 시작 주소를 가리키며, 인덱스는 S(0) i(1) n(2) a(3) g(4) o(5) n(6) g(7)이다. *(s + i)는 s[i]와 같다. 반복문은 i = 5부터 1까지 줄어들며 s[5]='o', s[4]='g', s[3]='a', s[2]='n', s[1]='i'를 차례로 출력하므로 결과는 ogani다. i가 0일 때는 조건 i > 0이 거짓이라 S는 출력되지 않는다.","choices":[{"verdict":"오답","why":"gnoganis는 문자열 전체를 거꾸로 출력하고 소문자로 바꾼 형태로, 이 코드의 결과가 아니다."},{"verdict":"오답","why":"sinagong은 문자열을 앞에서부터 출력한 형태이며 대소문자도 다르다."},{"verdict":"오답","why":"inago는 인덱스 1~5를 정방향으로 출력한 것이다. 반복문은 i를 감소시키므로 역방향이다."},{"verdict":"정답","why":"i = 5, 4, 3, 2, 1 순으로 o, g, a, n, i를 출력해 ogani가 된다. 정답이다."}],"keywords":[{"term":"*(s + i)","desc":"포인터 s에서 i칸 뒤의 문자, s[i]와 같음"},{"term":"문자열 인덱스","desc":"0부터 시작하며 마지막 다음 칸에 널 문자('\\0')가 있음"},{"term":"감소 반복문","desc":"for (i = 5; i > 0; i--)는 5, 4, 3, 2, 1을 차례로 반복"}],"memo":"반복 범위의 시작값과 끝 조건(i > 0이면 0은 제외)을 먼저 확인한 뒤 인덱스 표를 적어 읽는다."}},{"id":"written-2025-2-78","no":78,"unit":"프로그래밍 언어 활용","q":"OSI 7계층 모델에서 전송에 필요한 장치 간의 실제 접속 및 절단 등 기계적, 전기적, 기능적, 절차적 특성을 정의하는 계층은?","choices":["네트워크 계층","데이터 링크 계층","물리 계층","전송 계층"],"ans":3,"exp":{"concept":"OSI 7계층은 아래부터 물리, 데이터 링크, 네트워크, 전송, 세션, 표현, 응용 계층이다. 가장 아래의 물리 계층은 케이블, 커넥터처럼 실제 장치를 연결하고 끊기 위한 기계적, 전기적, 기능적, 절차적 특성을 정의하고 비트를 전송한다.","choices":[{"verdict":"오답","why":"네트워크 계층은 개방 시스템 간의 네트워크 연결을 관리하고 경로를 설정(라우팅)한다."},{"verdict":"오답","why":"데이터 링크 계층은 인접한 두 노드 사이의 신뢰성 있는 전송을 위해 흐름 제어, 프레임 동기화, 오류 제어를 한다."},{"verdict":"정답","why":"물리 계층은 장치 간 실제 접속과 절단을 위한 기계적, 전기적, 기능적, 절차적 특성을 정의한다. 정답이다."},{"verdict":"오답","why":"전송 계층은 종단 간(End-to-End) 신뢰성 있고 투명한 데이터 전송을 제공한다."}],"keywords":[{"term":"물리 계층","desc":"기계적·전기적·기능적·절차적 특성 정의, 비트 전송"},{"term":"데이터 링크 계층","desc":"인접 노드 간 흐름 제어, 프레임 동기화, 오류 제어"},{"term":"네트워크 계층","desc":"경로 설정(라우팅), 패킷 전달"},{"term":"전송 계층","desc":"종단 간 신뢰성 있는 데이터 전송"}],"memo":"'기계적·전기적'이라는 하드웨어 냄새가 나는 말이 나오면 물리 계층이다."}},{"id":"written-2025-2-79","no":79,"unit":"프로그래밍 언어 활용","q":"흐름 제어(Flow Control)에 관한 설명 중 옳지 않은 것은?","choices":["윈도우 크기는 확인 신호 없이 보낼 수 있는 패킷의 최대치를 말한다.","확인 신호를 활용하여 송신 데이터의 양을 조절하는 방식이 슬라이딩 윈도우이다.","이전에 송신한 패킷에 대해 부정 수신 응답(NAK)이 전달되면 윈도우 크기가 증가한다.","정지-대기는 수신 측으로부터 확인 신호(ACK)를 받은 다음에 다음 패킷을 전송하는 방식이다."],"ans":3,"exp":{"concept":"흐름 제어는 수신 측이 처리할 수 있는 만큼만 송신하도록 데이터 양을 조절하는 기법이다. 정지-대기(Stop-and-Wait)는 패킷 하나를 보내고 확인 신호(ACK)를 받은 뒤 다음 패킷을 보내고, 슬라이딩 윈도우(Sliding Window)는 확인 신호 없이도 윈도우 크기만큼 연속으로 보낸다. 슬라이딩 윈도우에서 ACK가 오면 윈도우 크기가 늘고, NAK가 오면 줄어든다.","choices":[{"verdict":"오답","why":"윈도우 크기는 확인 신호를 받지 않고 연속으로 보낼 수 있는 패킷의 최대 수다. 옳은 설명이다."},{"verdict":"오답","why":"확인 신호를 이용해 송신 데이터 양을 조절하는 방식이 슬라이딩 윈도우다. 옳은 설명이다."},{"verdict":"정답","why":"부정 수신 응답(NAK)이 오면 수신 측에 문제가 있다는 뜻이므로 윈도우 크기가 감소한다. 증가한다는 설명은 틀렸다."},{"verdict":"오답","why":"정지-대기는 ACK를 받은 다음에야 다음 패킷을 전송하는 방식이다. 옳은 설명이다."}],"keywords":[{"term":"흐름 제어","desc":"수신 측 처리 능력에 맞게 송신 데이터 양을 조절"},{"term":"정지-대기","desc":"패킷 하나 전송 후 ACK를 받고 다음 패킷 전송"},{"term":"슬라이딩 윈도우","desc":"윈도우 크기만큼 연속 전송, ACK면 윈도우 증가·NAK면 감소"},{"term":"ACK / NAK","desc":"긍정 수신 응답 / 부정 수신 응답"}],"memo":"ACK(좋다)면 더 보내도록 늘리고, NAK(문제 있다)면 줄인다."}},{"id":"written-2025-2-80","no":80,"unit":"프로그래밍 언어 활용","q":"아래와 같은 세그먼트 테이블을 갖는 시스템에서 논리 주소(2, 176)에 해당하는 물리 주소는?<div class=\"q-spec\"><span class=\"q-spec__label\">보기</span><table class=\"q-tbl is-data\"><thead><tr><th>세그먼트번호</th><th>시작주소</th><th>길이(바이트)</th></tr></thead><tbody><tr><td>0</td><td>670</td><td>248</td></tr><tr><td>1</td><td>1752</td><td>422</td></tr><tr><td>2</td><td>222</td><td>198</td></tr><tr><td>3</td><td>996</td><td>604</td></tr></tbody></table></div>","choices":["398","400","1928","1930"],"ans":1,"exp":{"concept":"세그먼테이션 기법에서 논리 주소 (s, d)는 세그먼트 번호 s와 그 안의 변위(오프셋) d로 이루어진다. 물리 주소는 세그먼트 테이블에서 s번 세그먼트의 시작 주소를 찾아 d를 더해 구한다. 세그먼트 2는 시작 주소 222, 길이 198이고, 변위 176은 길이 198보다 작아 유효하므로 물리 주소는 222 + 176 = 398이다.","choices":[{"verdict":"정답","why":"세그먼트 2의 시작 주소 222에 변위 176을 더한 398이 물리 주소다. 변위 176 < 길이 198이므로 유효하다. 정답이다."},{"verdict":"오답","why":"400은 222 + 176 = 398과 다르므로 물리 주소가 아니다."},{"verdict":"오답","why":"1928은 세그먼트 1의 시작 주소 1752에 176을 더한 값으로, 세그먼트 번호를 잘못 읽은 것이다."},{"verdict":"오답","why":"1930은 세그먼트 2의 시작 주소 222와 관계없는 값으로, 물리 주소가 아니다."}],"keywords":[{"term":"세그먼테이션","desc":"프로그램을 크기가 다른 논리적 단위(세그먼트)로 나누어 적재하는 기법"},{"term":"논리 주소 (s, d)","desc":"세그먼트 번호 s와 세그먼트 안의 변위 d"},{"term":"물리 주소","desc":"세그먼트 시작 주소 + 변위"},{"term":"세그먼트 길이 검사","desc":"변위가 세그먼트 길이 이상이면 주소 오류(트랩) 발생"}],"memo":"물리 주소 = 시작 주소 + 변위. 계산 전에 변위가 길이보다 작은지 먼저 확인한다."}},{"id":"written-2025-2-81","no":81,"unit":"정보시스템 구축 관리","q":"강제 접근통제(MAC)의 보안 모델 가운데 서로 이해 충돌 관계에 있는 객체 사이의 정보 접근을 통제하는 모델은?","choices":["벨 라파듈라 모델(Bell-LaPadula Model)","클락-윌슨 무결성 모델(Clark-Wilson Integrity Model)","비바 무결성 모델(Biba Integrity Model)","만리장성 모델(Chinese Wall Model)"],"ans":4,"exp":{"concept":"강제 접근 통제(MAC)는 주체와 객체의 보안 등급에 따라 시스템이 접근을 강제로 통제하는 방식이다. 대표 보안 모델 중 만리장성 모델(Chinese Wall Model, 브루어-내시 모델)은 서로 이해 충돌 관계에 있는 객체 사이의 정보 흐름을 막는다. 같은 컨설턴트가 경쟁 관계인 두 은행의 자료를 동시에 보지 못하게 하는 것이 예다.","choices":[{"verdict":"오답","why":"벨 라파듈라 모델은 기밀성을 강조하는 모델로, 하위 등급 주체가 상위 문서를 읽지 못하고(No Read Up) 상위 주체가 하위로 쓰지 못한다(No Write Down)."},{"verdict":"오답","why":"클락-윌슨 모델은 무결성을 중심으로 하는 상업용 모델로, 정형화된 트랜잭션과 직무 분리로 데이터의 부당한 변경을 막는다."},{"verdict":"오답","why":"비바 무결성 모델은 벨 라파듈라를 보완해 무결성을 보장하는 모델로, 하위를 읽지 못하고(No Read Down) 상위로 쓰지 못한다(No Write Up)."},{"verdict":"정답","why":"만리장성 모델은 서로 이해 충돌 관계에 있는 객체 간의 정보 접근을 통제하는 모델이다. 정답이다."}],"keywords":[{"term":"벨 라파듈라 모델","desc":"기밀성 중심, No Read Up·No Write Down"},{"term":"비바 모델","desc":"무결성 중심, No Read Down·No Write Up"},{"term":"클락-윌슨 모델","desc":"무결성 중심 상업용 모델, 정형화된 트랜잭션과 직무 분리"},{"term":"만리장성 모델","desc":"이해 충돌 관계의 객체 간 정보 흐름 차단, 브루어-내시 모델"}],"memo":"'이해 충돌'이 나오면 만리장성(벽으로 갈라 놓는다). 기밀성은 벨 라파듈라, 무결성은 비바."}},{"id":"written-2025-2-82","no":82,"unit":"정보시스템 구축 관리","q":"COCOMO 모델의 프로젝트 유형에 해당하지 않는 것은?","choices":["Sequential","Semi-detached","Embedded","Organic"],"ans":1,"exp":{"concept":"COCOMO 모형은 보헴(Boehm)이 제안한 비용 산정 모형으로, 프로그램 규모(LOC)에 따라 비용을 산정한다. 프로젝트 유형은 조직형(Organic, 5만 라인 이하의 중소 규모), 반분리형(Semi-detached, 30만 라인 이하의 중간 규모), 내장형(Embedded, 30만 라인 이상의 대규모·초대형) 세 가지다.","choices":[{"verdict":"정답","why":"Sequential은 COCOMO의 프로젝트 유형이 아니다."},{"verdict":"오답","why":"반분리형(Semi-detached)은 운영체제나 DBMS 같은 30만 라인 이하 중간 규모 소프트웨어 유형이다."},{"verdict":"오답","why":"내장형(Embedded)은 신호기 제어, 미사일 유도처럼 하드웨어와 밀접한 30만 라인 이상의 대규모 소프트웨어 유형이다."},{"verdict":"오답","why":"조직형(Organic)은 사무 처리용 같은 5만 라인 이하의 중소 규모 소프트웨어 유형이다."}],"keywords":[{"term":"COCOMO","desc":"보헴이 제안한 LOC 기반 비용 산정 모형"},{"term":"조직형(Organic)","desc":"5만(50KDSI) 라인 이하, 사무 처리·업무용"},{"term":"반분리형(Semi-detached)","desc":"30만(300KDSI) 라인 이하, 운영체제·DBMS"},{"term":"내장형(Embedded)","desc":"30만 라인 이상, 하드웨어 밀접 시스템"}],"memo":"COCOMO 유형은 '조반내'(조직형, 반분리형, 내장형)."}},{"id":"written-2025-2-83","no":83,"unit":"정보시스템 구축 관리","q":"DoS(Denial of Service) 공격에 관한 설명으로 틀린 것은?","choices":["Ping of Death 공격은 정상 크기보다 큰 ICMP 패킷을 작은 조각(Fragment)으로 쪼개서 공격 대상이 조각화 된 패킷을 처리하도록 만드는 공격 방법이다.","SYN Flooding은 존재하지 않는 클라이언트가 서버별로 한정된 접속 가능 공간에 접속한 것처럼 속여서 다른 사용자가 서비스를 이용하지 못하도록 하는 것이다.","Land 공격은 패킷을 전송할 때 출발지 IP주소와 목적지 IP주소 값을 동일하게 만들어 공격 대상에게 보내는 공격 방법이다.","Smurf 공격은 멀티캐스트(Multicast)를 이용하여 공격 대상이 네트워크의 임의의 시스템에 패킷을 보내도록 만드는 공격이다."],"ans":4,"exp":{"concept":"서비스 거부(DoS) 공격은 대상 시스템의 자원을 고갈시켜 정상 사용자가 서비스를 쓰지 못하게 하는 공격이다. Ping of Death는 비정상적으로 큰 ICMP 패킷, SYN Flooding은 TCP 3-way handshake의 미완성 연결, Land는 출발지와 목적지 IP가 같은 패킷, Smurf는 출발지를 대상 IP로 위조한 ICMP 패킷을 브로드캐스트해 응답이 대상에게 몰리게 한다.","choices":[{"verdict":"오답","why":"Ping of Death는 ICMP 패킷을 정상 크기보다 아주 크게 만들어 보내, 조각화된 패킷을 처리하느라 대상이 과부하에 걸리게 한다. 옳은 설명이다."},{"verdict":"오답","why":"SYN Flooding은 존재하지 않는 클라이언트가 접속한 것처럼 SYN만 보내 서버의 접속 대기 공간을 가득 채운다. 옳은 설명이다."},{"verdict":"오답","why":"Land 공격은 출발지 IP와 목적지 IP를 같게 만든 패킷을 보내 대상이 자기 자신에게 응답하게 만든다. 옳은 설명이다."},{"verdict":"정답","why":"Smurf 공격은 멀티캐스트가 아니라 브로드캐스트를 이용한다. 출발지를 대상 IP로 위조한 ICMP 패킷을 네트워크 전체에 브로드캐스트해 수많은 응답이 대상에게 몰리게 한다."}],"keywords":[{"term":"Ping of Death","desc":"정상보다 큰 ICMP 패킷을 조각내 보내 과부하 유발"},{"term":"SYN Flooding","desc":"3-way handshake를 완료하지 않아 서버 접속 대기열을 고갈"},{"term":"Land 공격","desc":"출발지와 목적지 IP를 같게 위조한 패킷 전송"},{"term":"Smurf 공격","desc":"대상 IP로 위조한 ICMP 패킷을 브로드캐스트해 응답을 대상에 집중"}],"memo":"Smurf는 '브로드캐스트'. 멀티캐스트로 바꾼 보기가 함정이다."}},{"id":"written-2025-2-84","no":84,"unit":"정보시스템 구축 관리","q":"국내 IT 서비스 경쟁력 강화를 목표로 개발된 것으로, 인프라 제어 및 관리 환경, 실행 환경, 개발 환경, 서비스 환경, 운영 환경으로 구성된 개방형 클라우드 컴퓨팅 플랫폼은 무엇인가?","choices":["PaaS-TA","N2OS","Metaverse","KAWS"],"ans":1,"exp":{"concept":"PaaS-TA는 국내 IT 서비스 경쟁력 강화를 위해 개발된 개방형 클라우드 컴퓨팅 플랫폼이다. 이름 그대로 서비스형 플랫폼(PaaS) 계열이며, 인프라 제어 및 관리 환경, 실행 환경, 개발 환경, 서비스 환경, 운영 환경으로 구성된다.","choices":[{"verdict":"정답","why":"PaaS-TA는 인프라 제어·관리, 실행, 개발, 서비스, 운영 환경으로 구성된 국내 개방형 클라우드 플랫폼이다. 정답이다."},{"verdict":"오답","why":"N2OS는 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"메타버스(Metaverse)는 현실과 가상이 결합된 3차원 가상 세계를 뜻하는 말로, 클라우드 플랫폼이 아니다."},{"verdict":"오답","why":"KAWS는 출제 범위의 표준 용어가 아니다."}],"keywords":[{"term":"PaaS-TA","desc":"국내 IT 서비스 경쟁력 강화를 목표로 개발된 개방형 클라우드 플랫폼"},{"term":"PaaS","desc":"Platform as a Service, 개발·실행 플랫폼을 서비스로 제공"},{"term":"IaaS","desc":"Infrastructure as a Service, 서버·스토리지 등 인프라를 서비스로 제공"},{"term":"SaaS","desc":"Software as a Service, 소프트웨어를 서비스로 제공"}],"memo":"'국내 개방형 클라우드 플랫폼'은 PaaS-TA. 이름에 PaaS가 그대로 들어 있다."}},{"id":"written-2025-2-85","no":85,"unit":"정보시스템 구축 관리","q":"최대 홉 수를 15로 제한하는 라우팅 프로토콜은?","choices":["EIGRP","RIP","Static","OSPF"],"ans":2,"exp":{"concept":"RIP(Routing Information Protocol)는 거리 벡터 알고리즘을 쓰는 내부 라우팅 프로토콜로, 목적지까지 거쳐 가는 라우터 수(홉 수)로 최적 경로를 정한다. 최대 홉 수를 15로 제한하며 16은 도달할 수 없는 경로로 본다. 그래서 소규모 네트워크에 적합하다.","choices":[{"verdict":"오답","why":"EIGRP는 시스코가 개발한 라우팅 프로토콜로, 대역폭·지연 등을 종합한 메트릭을 사용하며 홉 수 15 제한이 없다."},{"verdict":"정답","why":"RIP는 최대 홉 수를 15로 제한하는 거리 벡터 라우팅 프로토콜이다. 정답이다."},{"verdict":"오답","why":"정적(Static) 라우팅은 관리자가 경로를 직접 지정하는 방식으로, 라우팅 프로토콜처럼 홉 수 제한을 두지 않는다."},{"verdict":"오답","why":"OSPF는 링크 상태 알고리즘을 쓰는 프로토콜로, 다익스트라 알고리즘으로 최단 경로를 구하며 홉 수 제한이 없어 대규모 네트워크에 적합하다."}],"keywords":[{"term":"RIP","desc":"거리 벡터 방식, 홉 수 기준, 최대 15홉, 소규모 네트워크용"},{"term":"OSPF","desc":"링크 상태 방식, 다익스트라 알고리즘, 대규모 네트워크용"},{"term":"BGP","desc":"자율 시스템(AS) 간 라우팅에 쓰는 외부 라우팅 프로토콜"},{"term":"홉(Hop)","desc":"패킷이 거쳐 가는 라우터 하나"}],"memo":"RIP = 15홉. 16이면 '죽었다(도달 불가)'로 기억한다."}},{"id":"written-2025-2-86","no":86,"unit":"정보시스템 구축 관리","q":"다음 중 소프트웨어 비용 산정에 관한 설명으로 옳지 않은 것은?","choices":["소프트웨어 비용 산정 기법으로는 상향식, 하향식, 혼합식 기법이 있다.","소프트웨어의 규모, 인력 등의 요소를 바탕으로 개발에 필요한 비용을 예측하는 것이다.","소프트웨어 비용 결정 요소로는 프로젝트 요소, 자원 요소, 생산성 요소가 있다.","소프트웨어 비용을 높게 산정하면 예산 낭비와 일의 효율성 저하를 초래할 수 있다."],"ans":1,"exp":{"concept":"소프트웨어 비용 산정은 규모, 인력 등을 바탕으로 개발에 필요한 비용을 미리 예측하는 것이다. 산정 기법은 하향식(전문가 감정, 델파이 기법)과 상향식(LOC 기법, 개발 단계별 인월수 기법, 수학적 산정 기법)으로 나뉜다. 비용을 너무 높게 잡으면 예산이 낭비되고, 너무 낮게 잡으면 개발자의 부담과 품질 문제가 생긴다.","choices":[{"verdict":"정답","why":"교재의 비용 산정 기법 분류는 하향식과 상향식 두 가지다. '혼합식 기법'은 이 분류에 없다."},{"verdict":"오답","why":"비용 산정은 소프트웨어 규모, 인력 등의 요소로 개발 비용을 예측하는 것이다. 옳은 설명이다."},{"verdict":"오답","why":"비용 결정 요소는 프로젝트 요소, 자원 요소, 생산성 요소다. 옳은 설명이다."},{"verdict":"오답","why":"비용을 너무 높게 산정하면 예산 낭비와 일의 효율성 저하를 초래할 수 있다. 옳은 설명이다."}],"keywords":[{"term":"하향식 비용 산정","desc":"전문가의 경험으로 전체 비용을 산정: 전문가 감정 기법, 델파이 기법"},{"term":"상향식 비용 산정","desc":"세부 작업 단위별로 산정해 합산: LOC, 개발 단계별 인월수, 수학적 산정(COCOMO 등)"},{"term":"비용 결정 요소","desc":"프로젝트 요소, 자원 요소, 생산성 요소"}],"memo":"비용 산정 기법은 '하향식 vs 상향식' 두 갈래뿐. 혼합식은 함정이다."}},{"id":"written-2025-2-87","no":87,"unit":"정보시스템 구축 관리","q":"데이터 송·수신 사실을 입증할 수 있게 송·수신 증거를 제공해야 한다는 보안 요소는 무엇인가?","choices":["기밀성","가용성","부인 방지","무결성"],"ans":3,"exp":{"concept":"정보 보안의 요소는 기밀성, 무결성, 가용성, 인증, 부인 방지다. 부인 방지는 데이터를 보내거나 받은 사람이 나중에 '안 보냈다', '안 받았다'고 잡아떼지 못하도록 송수신 증거를 남기는 것이다. 등기우편의 수령 확인처럼 증거를 남기는 것이 핵심이다.","choices":[{"verdict":"오답","why":"기밀성은 허락된 사용자만 정보에 접근할 수 있게 하는 요소다."},{"verdict":"오답","why":"가용성은 권한을 가진 사용자가 원할 때 언제든 정보를 사용할 수 있게 하는 요소다."},{"verdict":"정답","why":"부인 방지는 송수신 사실을 부인하지 못하도록 송수신 증거를 제공하는 요소다. 정답이다."},{"verdict":"오답","why":"무결성은 허락된 사용자만 정보를 수정할 수 있게 해 정보가 임의로 바뀌지 않도록 하는 요소다."}],"keywords":[{"term":"기밀성","desc":"인가된 사용자만 정보에 접근 가능"},{"term":"무결성","desc":"인가된 사용자만 정보를 수정 가능"},{"term":"가용성","desc":"인가된 사용자가 필요할 때 언제든 사용 가능"},{"term":"인증","desc":"사용자가 정당한 사용자인지 확인"},{"term":"부인 방지","desc":"송수신 사실을 부인하지 못하도록 증거 제공"}],"memo":"'증거', '입증'이 나오면 부인 방지."}},{"id":"written-2025-2-88","no":88,"unit":"정보시스템 구축 관리","q":"프로젝트에 내재된 위험 요소를 인식하고 그 영향을 분석함으로써 이를 관리하는 활동으로, 프로젝트의 성공을 위해 위험 요소를 사전에 예측하고 대비하는 모든 기술과 활동을 포함하는 것은?","choices":["Waterfall Model","Work Breakdown Structure","Risk Analysis","Critical Path Method"],"ans":3,"exp":{"concept":"위험 분석(Risk Analysis)은 프로젝트에 숨어 있는 위험 요소를 미리 찾아내고 그 영향을 분석해 관리하는 활동이다. 위험 관리는 위험 식별 → 위험 분석 및 평가 → 위험 관리 계획 → 위험 감시 및 조치 순으로 진행한다. 우산을 미리 챙기려면 일기 예보를 보는 것처럼, 미리 예측하고 대비하는 것이 핵심이다.","choices":[{"verdict":"오답","why":"폭포수 모형(Waterfall Model)은 각 단계를 순차적으로 진행하는 소프트웨어 생명주기 모형이다."},{"verdict":"오답","why":"작업 분류 구조(WBS)는 프로젝트 목표를 달성하기 위한 활동과 작업을 계층적으로 나눈 것이다."},{"verdict":"정답","why":"위험 분석은 프로젝트의 위험 요소를 인식하고 영향을 분석해 관리하는 활동이다. 정답이다."},{"verdict":"오답","why":"임계 경로 기법(CPM)은 노드와 간선으로 작업 일정을 표현하고 프로젝트 완료에 걸리는 가장 긴 경로를 찾는 일정 관리 기법이다."}],"keywords":[{"term":"위험 분석(Risk Analysis)","desc":"위험 요소를 인식하고 영향을 분석해 관리하는 활동"},{"term":"위험 관리 절차","desc":"위험 식별 → 위험 분석 및 평가 → 위험 관리 계획 → 위험 감시 및 조치"},{"term":"WBS","desc":"프로젝트 작업을 계층적으로 분해한 작업 분류 구조"},{"term":"CPM","desc":"작업 일정 네트워크에서 임계 경로를 찾는 일정 관리 기법"}],"memo":"'위험 요소', '사전에 예측·대비'가 나오면 Risk Analysis."}},{"id":"written-2025-2-89","no":89,"unit":"정보시스템 구축 관리","q":"다음 중 개인키 암호화 기법에 해당하지 않는 것은?","choices":["DES","SEED","ARIA","RSA"],"ans":4,"exp":{"concept":"개인키(대칭키) 암호화는 암호화와 복호화에 같은 키를 쓰는 방식으로, DES, AES, SEED, ARIA, IDEA 등이 있다. 공개키(비대칭키) 암호화는 공개키로 암호화하고 개인키로 복호화하는 방식으로, RSA, ECC 등이 있다. RSA는 큰 수를 소인수분해하기 어렵다는 점을 이용한다.","choices":[{"verdict":"오답","why":"DES는 미국 국립표준국(NBS)이 표준으로 채택한 64비트 블록의 대칭키(개인키) 암호 알고리즘이다."},{"verdict":"오답","why":"SEED는 한국인터넷진흥원(KISA)이 개발한 블록 대칭키 암호 알고리즘이다."},{"verdict":"오답","why":"ARIA는 국가정보원과 산학연협회가 개발한 블록 대칭키 암호 알고리즘이다."},{"verdict":"정답","why":"RSA는 공개키와 비밀키를 쓰는 대표적인 공개키(비대칭키) 암호 알고리즘이므로 개인키 암호화 기법이 아니다."}],"keywords":[{"term":"개인키(대칭키) 암호화","desc":"암·복호화에 같은 키 사용: DES, AES, SEED, ARIA, IDEA"},{"term":"공개키(비대칭키) 암호화","desc":"공개키로 암호화, 개인키로 복호화: RSA, ECC"},{"term":"RSA","desc":"큰 숫자의 소인수분해가 어렵다는 점을 이용한 공개키 암호 알고리즘"}],"memo":"공개키 대표는 RSA와 ECC. 나머지 블록 암호(DES, AES, SEED, ARIA, IDEA)는 모두 대칭키다."}},{"id":"written-2025-2-90","no":90,"unit":"정보시스템 구축 관리","q":"다음 중 나선형(Spiral) 모형의 주요 태스크에 속하지 않는 것은?","choices":["평가","버전 관리","위험 분석","개발"],"ans":2,"exp":{"concept":"나선형(Spiral) 모형은 보헴(Boehm)이 제안한 모형으로, 나선을 따라 돌듯이 여러 번 반복하며 점점 완성도를 높여 간다. 한 바퀴마다 계획 및 정의 → 위험 분석 → 공학적 개발 → 고객 평가의 네 가지 주요 태스크를 수행한다. 위험 분석이 들어 있는 것이 가장 큰 특징이다.","choices":[{"verdict":"오답","why":"고객 평가는 개발된 결과를 사용자가 평가하는 나선형 모형의 주요 태스크다."},{"verdict":"정답","why":"버전 관리는 형상 관리의 활동으로, 나선형 모형의 네 가지 주요 태스크에 속하지 않는다."},{"verdict":"오답","why":"위험 분석은 위험 요소를 찾아 분석하는 나선형 모형의 핵심 태스크다."},{"verdict":"오답","why":"공학적 개발은 시스템을 개발하는 나선형 모형의 주요 태스크다."}],"keywords":[{"term":"나선형 모형","desc":"보헴이 제안, 위험 분석을 포함해 반복적으로 개발하는 모형"},{"term":"나선형 모형 태스크","desc":"계획 및 정의 → 위험 분석 → 공학적 개발 → 고객 평가"},{"term":"버전 관리","desc":"형상 관리에서 변경 이력과 버전을 관리하는 활동"}],"memo":"나선형 4단계 '계위개평'(계획, 위험 분석, 개발, 평가)."}},{"id":"written-2025-2-91","no":91,"unit":"정보시스템 구축 관리","q":"다음의 암호 알고리즘 가운데 성격이 다른 것은?","choices":["MD5","MD4","SHA-1","AES"],"ans":4,"exp":{"concept":"암호 알고리즘은 원래대로 되돌릴 수 있는 양방향 암호(대칭키·공개키)와, 되돌릴 수 없는 단방향 해시 함수로 나뉜다. MD4, MD5, SHA-1은 임의 길이 입력을 고정 길이 해시값으로 바꾸는 해시 함수다. AES는 키로 암호화·복호화하는 대칭키 블록 암호다.","choices":[{"verdict":"오답","why":"MD5는 MD4를 개선한 128비트 해시 함수다."},{"verdict":"오답","why":"MD4는 로널드 리베스트가 만든 128비트 해시 함수로, MD5의 이전 버전이다."},{"verdict":"오답","why":"SHA-1은 미국 국가안보국(NSA)이 설계하고 미국 국립표준기술연구소(NIST)가 표준으로 발표한 160비트 해시 함수다."},{"verdict":"정답","why":"AES는 미국 NIST가 발표한 대칭키 블록 암호 알고리즘으로, 해시 함수인 나머지와 성격이 다르다."}],"keywords":[{"term":"해시 함수","desc":"임의 길이 입력을 고정 길이 값으로 바꾸는 단방향 함수: MD4, MD5, SHA 계열, HAVAL"},{"term":"AES","desc":"128비트 블록, 128·192·256비트 키를 쓰는 대칭키 블록 암호"},{"term":"양방향 암호","desc":"키로 복호화할 수 있는 암호: 대칭키, 공개키 방식"}],"memo":"MD와 SHA가 붙으면 해시, AES·DES·SEED·ARIA는 대칭키 암호."}},{"id":"written-2025-2-92","no":92,"unit":"정보시스템 구축 관리","q":"간트 차트(Gantt Chart)에 관한 설명 중 틀린 것은?","choices":["수평 막대의 길이는 각 작업(Task)에 필요한 인원수를 나타낸다.","프로젝트를 구성하는 소작업별로 언제 시작하고 언제 끝나야 하는지를 한눈에 볼 수 있게 도와준다.","자원 배치 계획에 유용하게 활용된다.","CPM 네트워크로부터 만들 수 있다."],"ans":1,"exp":{"concept":"간트 차트(Gantt Chart)는 프로젝트의 각 작업이 언제 시작하고 언제 끝나는지를 수평 막대로 보여 주는 일정표로, 시간선(Time-line) 차트라고도 한다. 막대의 길이는 작업 기간을 뜻한다. 이정표, 작업 일정, 작업 기간, 산출물로 구성되며 자원 배치 계획에 유용하다.","choices":[{"verdict":"정답","why":"간트 차트의 수평 막대 길이는 작업에 필요한 인원수가 아니라 작업 기간을 나타낸다."},{"verdict":"오답","why":"각 작업이 언제 시작하고 언제 끝나야 하는지를 한눈에 볼 수 있다. 옳은 설명이다."},{"verdict":"오답","why":"작업 일정을 보여 주므로 자원 배치 계획에 유용하다. 옳은 설명이다."},{"verdict":"오답","why":"CPM 네트워크에서 구한 작업 일정으로 간트 차트를 만들 수 있다. 옳은 설명이다."}],"keywords":[{"term":"간트 차트","desc":"작업 일정을 수평 막대로 표시한 시간선 차트, 막대 길이 = 작업 기간"},{"term":"PERT","desc":"작업 일정을 낙관치·기대치·비관치로 예측하는 네트워크 기법"},{"term":"CPM","desc":"임계 경로를 찾아 프로젝트 최소 완료 기간을 구하는 기법"}],"memo":"간트 차트의 막대 길이는 '시간(기간)'. 인원수, 비용이 나오면 틀린 보기."}},{"id":"written-2025-2-93","no":93,"unit":"정보시스템 구축 관리","q":"다음 설명에 해당하는 소프트웨어 정의 기술(SDx)은?<div class=\"q-spec\"><div class=\"q-spec__label\">보기</div><ul><li>가상화를 적용해 필요한 공간만큼 나누어 사용할 수 있도록 하며, 서버 가상화와 유사함</li><li>컴퓨팅 소프트웨어로 규정하는 데이터 스토리지 체계로, 일정 조직 내의 여러 스토리지를 하나처럼 관리하고 운용하는 컴퓨터 이용 환경</li><li>스토리지 자원을 효율적으로 나눠 쓰는 방법으로 이해할 수 있음</li></ul></div>","choices":["Systematic Network Storage","Software Defined Storage","Distribution Oriented Storage","Network Architected Storage"],"ans":2,"exp":{"concept":"SDx(Software-Defined Everything)는 하드웨어 자원을 소프트웨어로 가상화해 관리하는 기술들을 통틀어 부르는 말이다. 그중 SDS(Software Defined Storage)는 여러 스토리지를 가상화해 하나처럼 관리하고, 필요한 만큼 나눠 쓰게 하는 기술이다. 서버 가상화와 비슷한 방식으로 저장 공간을 다룬다.","choices":[{"verdict":"오답","why":"Systematic Network Storage는 출제 범위의 표준 용어가 아니다."},{"verdict":"정답","why":"SDS(Software Defined Storage)는 소프트웨어로 스토리지를 가상화해 여러 스토리지를 하나처럼 관리·운용하는 기술이다. 정답이다."},{"verdict":"오답","why":"Distribution Oriented Storage는 출제 범위의 표준 용어가 아니다."},{"verdict":"오답","why":"Network Architected Storage는 출제 범위의 표준 용어가 아니다."}],"keywords":[{"term":"SDx","desc":"하드웨어 자원을 소프트웨어로 정의·가상화해 관리하는 기술의 총칭"},{"term":"SDS","desc":"소프트웨어 정의 스토리지, 여러 스토리지를 하나처럼 관리"},{"term":"SDN","desc":"소프트웨어 정의 네트워크, 네트워크를 소프트웨어로 제어·관리"},{"term":"SDDC","desc":"소프트웨어 정의 데이터 센터, 데이터 센터 전체를 소프트웨어로 정의"}],"memo":"'스토리지를 소프트웨어로 정의' 그대로 Software Defined Storage."}},{"id":"written-2025-2-94","no":94,"unit":"정보시스템 구축 관리","q":"악성코드 유형 가운데, 다른 컴퓨터의 취약점을 이용해 스스로 전파되거나 메일을 통해 퍼지면서 자기 자신을 증식시키는 것은?","choices":["Rogue Ware","Adware","Worm","Reflection Attack"],"ans":3,"exp":{"concept":"웜(Worm)은 다른 프로그램에 기생하지 않고 스스로 복제해 네트워크나 이메일로 퍼지는 악성 코드다. 바이러스가 숙주 파일에 붙어야 퍼지는 것과 달리, 웜은 혼자서 다른 컴퓨터의 취약점을 이용해 전파되며 네트워크 부하를 일으킨다.","choices":[{"verdict":"오답","why":"로그웨어(Rogue Ware)는 가짜 백신 소프트웨어로, 컴퓨터가 감염된 것처럼 속여 설치나 결제를 유도하는 프로그램이다."},{"verdict":"오답","why":"애드웨어(Adware)는 사용자 동의 없이 광고를 띄우는 프로그램이다."},{"verdict":"정답","why":"웜은 다른 컴퓨터의 취약점을 이용하거나 메일을 통해 스스로 전파하며 자기 자신을 증식시킨다. 정답이다."},{"verdict":"오답","why":"반사 공격(Reflection Attack)은 출발지 주소를 대상 주소로 위조해 다른 시스템의 응답이 대상에게 몰리게 하는 공격 방식으로, 스스로 증식하는 악성 코드가 아니다."}],"keywords":[{"term":"웜(Worm)","desc":"스스로 복제·전파하며 네트워크를 통해 퍼지는 악성 코드"},{"term":"바이러스(Virus)","desc":"다른 프로그램(숙주)에 붙어 복제·감염되는 악성 코드"},{"term":"트로이 목마","desc":"정상 프로그램으로 위장했다가 실행되면 악성 행위를 하는 코드, 자기 복제 없음"},{"term":"애드웨어","desc":"광고를 띄우는 소프트웨어"}],"memo":"웜은 '스스로 기어 다니는 벌레'. 숙주 없이 혼자 퍼지면 웜, 숙주가 필요하면 바이러스."}},{"id":"written-2025-2-95","no":95,"unit":"정보시스템 구축 관리","q":"소프트웨어 개발 방법론의 테일러링(Tailoring)에 대한 설명으로 옳지 않은 것은?","choices":["관리 측면에서의 목적 중 하나는 최단 기간에 안정적인 프로젝트 진행을 위해 사전 위험을 식별하고 제거하는 것이다.","프로젝트에 최적화된 개발 방법론을 적용하기 위하여 절차, 산출물 등을 적절하게 변경하는 활동이다.","기술적 측면에서의 목적 중 하나는 프로젝트에 최적화된 기술 요소를 도입해 프로젝트 특성에 맞는 최적의 기법과 도구를 사용하는 것이다.","프로젝트를 수행할 때 예상되는 변화를 배제하고 신속하게 진행해야 한다."],"ans":4,"exp":{"concept":"테일러링(Tailoring)은 옷을 몸에 맞게 수선하듯, 표준 개발 방법론을 프로젝트의 특성에 맞게 절차, 산출물, 기법 등을 수정해 적용하는 것이다. 관리 측면에서는 최단 기간에 안정적으로 진행하도록 사전 위험을 식별·제거하고, 기술 측면에서는 프로젝트에 최적화된 기법과 도구를 쓰는 것이 목적이다. 따라서 예상되는 변화를 배제하는 것이 아니라 반영해야 한다.","choices":[{"verdict":"오답","why":"관리 측면의 목적은 최단 기간에 안정적인 프로젝트 진행을 위해 사전 위험을 식별하고 제거하는 것이다. 옳은 설명이다."},{"verdict":"오답","why":"테일러링은 프로젝트에 최적화된 방법론을 적용하기 위해 절차, 산출물 등을 적절히 변경하는 활동이다. 옳은 설명이다."},{"verdict":"오답","why":"기술적 측면의 목적은 프로젝트에 최적화된 기술 요소를 도입해 알맞은 기법과 도구를 쓰는 것이다. 옳은 설명이다."},{"verdict":"정답","why":"테일러링은 프로젝트 상황과 예상되는 변화를 고려해 방법론을 맞추는 활동이다. 변화를 배제한다는 것은 테일러링의 취지와 반대다."}],"keywords":[{"term":"테일러링","desc":"프로젝트 특성에 맞게 표준 개발 방법론을 수정·보완하는 것"},{"term":"내부적 기준","desc":"목표 환경, 요구사항, 프로젝트 규모, 보유 기술"},{"term":"외부적 기준","desc":"법적 제약사항, 표준 품질 기준"}],"memo":"테일러링은 '맞춤 수선'. 변화를 반영하지 배제하지 않는다."}},{"id":"written-2025-2-96","no":96,"unit":"정보시스템 구축 관리","q":"대칭 암호 알고리즘 및 비대칭 암호 알고리즘에 관한 설명 중 틀린 것은?","choices":["대칭 암호 알고리즘은 비밀키 전달을 위한 키 교환이 필요 없으므로 암호화와 복호화 속도가 빠르다.","대칭 암호 알고리즘은 실행 속도가 비교적 빠르므로 다양한 암호의 핵심 함수로 활용될 수 있다.","비대칭 암호 알고리즘은 자신만 보관하는 비밀키를 이용해 인증, 전자서명 등에 적용할 수 있다.","대표적인 대칭키 암호 알고리즘에는 AES, IDEA 등이 있다."],"ans":1,"exp":{"concept":"대칭 암호는 암호화와 복호화에 같은 비밀키를 쓰므로, 상대방에게 그 비밀키를 안전하게 전달(키 교환)해야 한다. 대신 알고리즘이 단순해 속도가 빠르다. 비대칭(공개키) 암호는 공개키와 개인키 한 쌍을 써서 키 전달 문제가 적지만 속도가 느리고, 개인키로 인증과 전자서명을 할 수 있다.","choices":[{"verdict":"정답","why":"대칭 암호는 같은 키를 양쪽이 가져야 하므로 비밀키 전달을 위한 키 교환이 반드시 필요하다. 키 교환이 필요 없다는 설명은 틀렸다. 속도가 빠른 이유는 알고리즘이 단순하기 때문이다."},{"verdict":"오답","why":"대칭 암호는 실행 속도가 빨라 다양한 암호의 핵심 함수로 활용된다. 옳은 설명이다."},{"verdict":"오답","why":"비대칭 암호는 자신만 보관하는 개인(비밀)키로 서명해 인증과 전자서명에 쓸 수 있다. 옳은 설명이다."},{"verdict":"오답","why":"AES와 IDEA는 대표적인 대칭키 암호 알고리즘이다. 옳은 설명이다."}],"keywords":[{"term":"대칭키 암호","desc":"같은 키로 암·복호화, 키 교환 필요, 속도 빠름, n명이면 키 n(n-1)/2개"},{"term":"비대칭키 암호","desc":"공개키·개인키 한 쌍 사용, 속도 느림, n명이면 키 2n개"},{"term":"전자서명","desc":"개인키로 서명하고 공개키로 검증해 송신자를 인증"}],"memo":"대칭키의 약점은 '키 교환', 비대칭키의 약점은 '속도'."}},{"id":"written-2025-2-97","no":97,"unit":"정보시스템 구축 관리","q":"소프트웨어 재공학의 주요 활동 가운데, 기존 소프트웨어를 다른 운영체제나 하드웨어 환경에서도 사용할 수 있게 변환하는 것은?","choices":["역공학","분석","이식","재구성"],"ans":3,"exp":{"concept":"소프트웨어 재공학은 기존 소프트웨어를 버리지 않고 고쳐서 다시 활용하는 것이다. 주요 활동은 분석(Analysis), 재구성(Restructuring), 역공학(Reverse Engineering), 이식(Migration)이다. 이식은 기존 소프트웨어를 다른 운영체제나 하드웨어 환경에서도 쓸 수 있게 변환하는 활동이다.","choices":[{"verdict":"오답","why":"역공학은 기존 소프트웨어를 분석해 설계 정보나 명세 같은 상위 수준의 정보를 다시 만들어 내는 활동이다."},{"verdict":"오답","why":"분석은 기존 소프트웨어의 명세서를 확인해 동작을 이해하고 재공학 대상을 선정하는 활동이다."},{"verdict":"정답","why":"이식은 기존 소프트웨어를 다른 운영체제나 하드웨어 환경에서 사용할 수 있도록 변환하는 활동이다. 정답이다."},{"verdict":"오답","why":"재구성은 기능과 외적 동작은 바꾸지 않고 같은 추상 수준에서 코드 구조를 재구성하는 활동이다."}],"keywords":[{"term":"분석","desc":"기존 소프트웨어를 이해하고 재공학 대상을 선정"},{"term":"재구성","desc":"같은 수준에서 코드 구조를 재구성, 기능은 그대로"},{"term":"역공학","desc":"기존 코드로부터 설계 정보를 다시 만들어 냄"},{"term":"이식(Migration)","desc":"다른 운영체제나 하드웨어 환경에서 쓸 수 있게 변환"}],"memo":"재공학 활동은 '분재역이'(분석, 재구성, 역공학, 이식). 다른 환경으로 옮기면 이식."}},{"id":"written-2025-2-98","no":98,"unit":"정보시스템 구축 관리","q":"해쉬(Hash) 기법에 관한 설명 중 틀린 것은?","choices":["해쉬 함수는 일방향 함수(One-way function)에 해당한다.","대표적인 해쉬 알고리즘에는 HAVAL, SHA-1 등이 있다.","임의 길이의 입력 데이터를 받아서 고정된 길이의 해쉬값으로 변환한다.","주로 공개키 암호화 방식에서 키를 생성하기 위해 사용한다."],"ans":4,"exp":{"concept":"해시(Hash)는 임의 길이의 데이터를 고정된 길이의 값(해시값)으로 바꾸는 일방향 함수다. 해시값으로 원래 데이터를 되돌릴 수 없어서, 데이터가 바뀌었는지 확인하는 무결성 검증, 전자서명, 비밀번호 저장 등에 쓰인다. 공개키 암호의 키 생성에 쓰는 기술이 아니다.","choices":[{"verdict":"오답","why":"해시 함수는 해시값에서 원래 입력을 복원할 수 없는 일방향 함수다. 옳은 설명이다."},{"verdict":"오답","why":"HAVAL, SHA-1은 대표적인 해시 알고리즘이다. 옳은 설명이다."},{"verdict":"오답","why":"임의 길이의 입력을 받아 고정 길이의 해시값으로 바꾼다. 옳은 설명이다."},{"verdict":"정답","why":"해시는 주로 무결성 검증과 전자서명 등에 쓰이며, 공개키 암호 방식에서 키를 생성하는 것이 주된 용도가 아니다."}],"keywords":[{"term":"해시 함수","desc":"임의 길이 입력을 고정 길이 해시값으로 바꾸는 일방향 함수"},{"term":"해시 알고리즘 종류","desc":"SHA 계열, MD5, N-NASH, SNEFRU, HAVAL"},{"term":"무결성 검증","desc":"해시값을 비교해 데이터가 바뀌지 않았는지 확인"}],"memo":"해시는 '지문'처럼 데이터의 요약값이다. 용도는 무결성 확인이지 키 생성이 아니다."}},{"id":"written-2025-2-99","no":99,"unit":"정보시스템 구축 관리","q":"Public 메소드에서 Private 배열이 반환되는 경우 발생하는 문제점으로 가장 옳은 것은?","choices":["시스템 내부 정보가 노출된다.","배열의 주소가 외부에 공개되어 외부에서 접근이 가능해진다.","동기화 오류가 생긴다.","메소드에 접근할 수 없게 된다."],"ans":2,"exp":{"concept":"private 배열은 클래스 안에서만 다루라고 숨겨 둔 데이터다. 그런데 public 메소드가 이 배열을 그대로 반환하면, 배열은 참조(주소)로 전달되므로 외부에서 그 주소로 배열 내용을 직접 바꿀 수 있다. 이것은 시큐어 코딩의 캡슐화 약점으로, 배열을 복사한 사본을 반환해 해결한다.","choices":[{"verdict":"오답","why":"시스템 내부 정보가 오류 메시지 등으로 노출되는 것은 '시스템 데이터 정보 노출'이라는 다른 캡슐화 약점이다."},{"verdict":"정답","why":"private 배열을 public 메소드가 반환하면 배열의 주소가 외부에 공개되어 외부에서 배열에 접근·수정할 수 있게 된다. 정답이다."},{"verdict":"오답","why":"동기화 오류는 여러 스레드가 공유 자원에 동시에 접근할 때 생기는 문제로, 배열 반환과는 관계없다."},{"verdict":"오답","why":"메소드가 public이므로 외부에서 메소드에 접근할 수 없게 되는 일은 없다."}],"keywords":[{"term":"캡슐화","desc":"데이터와 함수를 묶고 내부 구현을 외부로부터 숨기는 것"},{"term":"Public 메소드로부터 반환된 Private 배열","desc":"배열 주소가 노출되어 외부에서 수정 가능해지는 보안 약점"},{"term":"Private 배열에 Public 데이터 할당","desc":"public으로 받은 값을 private 배열에 직접 저장해 외부에서 배열을 수정할 수 있게 되는 약점"}],"memo":"배열은 주소로 넘어간다. private 배열은 그대로 반환하지 말고 복사본(clone)을 반환한다."}},{"id":"written-2025-2-100","no":100,"unit":"정보시스템 구축 관리","q":"다음 중 소프트웨어 개발 보안 생명주기 방법론에 해당하지 않는 것은?","choices":["Seven Touchpoints","CLASP","PIMS","SDL"],"ans":3,"exp":{"concept":"소프트웨어 개발 보안 생명주기 방법론은 개발 초기부터 보안을 단계별로 넣어 안전한 소프트웨어를 만드는 방법론이다. 대표적으로 마이크로소프트의 MS-SDL, OWASP의 CLASP, Seven Touchpoints가 있다. PIMS는 기업의 개인정보 보호 관리체계를 뜻하는 말로 개발 방법론이 아니다.","choices":[{"verdict":"오답","why":"Seven Touchpoints는 소프트웨어 보안의 모범 사례를 개발 생명주기에 통합한 보안 개발 방법론이다."},{"verdict":"오답","why":"CLASP는 OWASP가 만든, 개발 초기 단계부터 보안을 강화하기 위한 보안 개발 방법론이다."},{"verdict":"정답","why":"PIMS(Personal Information Management System)는 개인정보 보호 관리체계로, 소프트웨어 개발 보안 생명주기 방법론이 아니다."},{"verdict":"오답","why":"SDL(Security Development Lifecycle)은 마이크로소프트가 만든 보안 개발 생명주기 방법론이다."}],"keywords":[{"term":"MS-SDL","desc":"마이크로소프트가 개발한 보안 강화 개발 생명주기 방법론"},{"term":"CLASP","desc":"OWASP가 만든 개발 초기 단계 보안 강화 방법론"},{"term":"Seven Touchpoints","desc":"보안 모범 사례를 생명주기에 통합한 방법론"},{"term":"PIMS","desc":"개인정보 보호 관리체계"}],"memo":"보안 개발 방법론은 'SDL, CLASP, Seven Touchpoints' 세 개. PIMS와 ISMS는 관리체계 인증이다."}}]};